B.h_j=new A.b(B.oL,["wfx_leg_prv1","wfp_legend","This map is 59 nodes and 60 edges, derived BY HAND on 2026-08-18 by reading the code - isan at origin/dev ff89793, flutterboard, isa_kit, datakit, the server hooks folder and DATA_SOURCES.md.","text",70,552,900,40,10,12],t.M)
