B.e7u=new A.b(B.bs,["Base: the middle path, with filled inputs at their most likely value.","\uae30\uc900: \uac00\uc6b4\ub370 \uacbd\ub85c, \ucc44\uc6b4 \uc785\ub825\uac12\uc740 \uac00\uc7a5 \uac00\ub2a5\uc131 \ub192\uc740 \uac12.","Base: la trayectoria central, con los datos estimados en su valor m\xe1s probable.","Base : la trajectoire m\xe9diane, donn\xe9es estim\xe9es \xe0 leur valeur la plus probable.","Basis: der mittlere Pfad, gesch\xe4tzte Eingaben auf ihrem wahrscheinlichsten Wert.","\u57fa\u6e96: \u771f\u3093\u4e2d\u306e\u7d4c\u8def\u3002\u88dc\u5b8c\u5024\u306f\u6700\u3082\u53ef\u80fd\u6027\u306e\u9ad8\u3044\u5024\u3002","\u57fa\u51c6\uff1a\u4e2d\u95f4\u8def\u5f84\uff0c\u8865\u9f50\u7684\u8f93\u5165\u53d6\u6700\u53ef\u80fd\u7684\u503c\u3002"],t.w)
B.e7P=new A.b(B.bs,["Low: the average of the worst fifth of paths, with filled inputs at the edge of their range that hurts.","\ub0ae\uc74c: \uac00\uc7a5 \ub098\uc05c 5\ubd84\uc758 1 \uacbd\ub85c\uc758 \ud3c9\uade0, \ucc44\uc6b4 \uc785\ub825\uac12\uc740 \ubd88\ub9ac\ud55c \ucabd \ub05d.","Bajo: la media del peor quinto de trayectorias, con los datos estimados en el extremo que perjudica.","Bas : la moyenne du pire cinqui\xe8me des trajectoires, donn\xe9es estim\xe9es au bord d\xe9favorable.","Tief: der Durchschnitt des schlechtesten F\xfcnftels der Pfade, gesch\xe4tzte Eingaben am ung\xfcnstigen Rand.","\u4f4e: \u6700\u3082\u60aa\u30445\u5206\u306e1\u306e\u7d4c\u8def\u306e\u5e73\u5747\u3002\u88dc\u5b8c\u5024\u306f\u4e0d\u5229\u306a\u5074\u306e\u7aef\u3002","\u4f4e\uff1a\u6700\u5dee\u4e94\u5206\u4e4b\u4e00\u8def\u5f84\u7684\u5e73\u5747\uff0c\u8865\u9f50\u7684\u8f93\u5165\u53d6\u4e0d\u5229\u4e00\u7aef\u3002"],t.w)
B.e8h=new A.b(B.bs,["High: the average of the best fifth of paths, with filled inputs at the edge that helps.","\ub192\uc74c: \uac00\uc7a5 \uc88b\uc740 5\ubd84\uc758 1 \uacbd\ub85c\uc758 \ud3c9\uade0, \ucc44\uc6b4 \uc785\ub825\uac12\uc740 \uc720\ub9ac\ud55c \ucabd \ub05d.","Alto: la media del mejor quinto de trayectorias, con los datos estimados en el extremo que ayuda.","Haut : la moyenne du meilleur cinqui\xe8me des trajectoires, donn\xe9es estim\xe9es au bord favorable.","Hoch: der Durchschnitt des besten F\xfcnftels der Pfade, gesch\xe4tzte Eingaben am g\xfcnstigen Rand.","\u9ad8: \u6700\u3082\u826f\u30445\u5206\u306e1\u306e\u7d4c\u8def\u306e\u5e73\u5747\u3002\u88dc\u5b8c\u5024\u306f\u6709\u5229\u306a\u5074\u306e\u7aef\u3002","\u9ad8\uff1a\u6700\u597d\u4e94\u5206\u4e4b\u4e00\u8def\u5f84\u7684\u5e73\u5747\uff0c\u8865\u9f50\u7684\u8f93\u5165\u53d6\u6709\u5229\u4e00\u7aef\u3002"],t.w)
