B.eDW=new A.b(B.h,["One-year correlation of the chart with stocks\xf7bonds.","\ucc28\ud2b8\uc640 \uc8fc\uc2dd\xf7\ucc44\uad8c\uc758 1\ub144 \uc0c1\uad00\uad00\uacc4\uc608\uc694."],t.w)
B.SY=new A.b(B.h,["One-year regression channel on price.","\uac00\uaca9\uc758 1\ub144 \ud68c\uadc0 \ucc44\ub110\uc774\uc5d0\uc694."],t.w)
B.eou=new A.b(B.h,["Put the sleeve you want to judge on the chart (SPY, TLT, GLD or DBC). Growth up + inflation down favours SPY; growth down favours TLT; inflation up favours GLD and DBC. A positive composite says the regime and the trend agree for that sleeve.","\ud310\ub2e8\ud558\uace0 \uc2f6\uc740 \ubb36\uc74c(SPY, TLT, GLD, DBC)\uc744 \ucc28\ud2b8\uc5d0 \uc62c\ub9ac\uc138\uc694. \uc131\uc7a5 \uc0c1\uc2b9 + \uc778\ud50c\ub808\uc774\uc158 \ud558\ub77d\uc740 SPY\uc5d0, \uc131\uc7a5 \ud558\ub77d\uc740 TLT\uc5d0, \uc778\ud50c\ub808\uc774\uc158 \uc0c1\uc2b9\uc740 GLD\uc640 DBC\uc5d0 \uc720\ub9ac\ud574\uc694. \uc885\ud569 \uc810\uc218\uac00 \uc591\uc218\uc774\uba74 \uadf8 \ubb36\uc74c\uc5d0\uc11c \uad6d\uba74\uacfc \ucd94\uc138\uac00 \uc77c\uce58\ud55c\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694."],t.w)
B.eX_=new A.b(B.h,["Long, clear regimes: the disinflationary expansion of the 2010s (stocks) or the inflation surge of 2021\u201322 (commodities).","2010\ub144\ub300\uc758 \ub514\uc2a4\uc778\ud50c\ub808\uc774\uc158 \ud655\uc7a5\uae30(\uc8fc\uc2dd)\ub098 2021~22\ub144\uc758 \uc778\ud50c\ub808\uc774\uc158 \uae09\ub4f1\uae30(\uc6d0\uc790\uc7ac)\ucc98\ub7fc \uae38\uace0 \ub69c\ub837\ud55c \uad6d\uba74\uc5d0\uc11c \uc798 \ub9de\uc544\uc694."],t.w)
B.eyu=new A.b(B.h,["Fast regime flips, like the 2020 crash and rebound within months, and 2022, when stocks and bonds fell together.","\uba87 \ub2ec \uc548\uc5d0 \ud3ed\ub77d\uacfc \ubc18\ub4f1\uc774 \uc788\uc5c8\ub358 2020\ub144\uc774\ub098 \uc8fc\uc2dd\uacfc \ucc44\uad8c\uc774 \ud568\uaed8 \ub5a8\uc5b4\uc9c4 2022\ub144\ucc98\ub7fc \uad6d\uba74\uc774 \ube60\ub974\uac8c \ubc14\ub014 \ub54c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694."],t.w)
B.eJi=new A.b(B.h,["Growth votes read XLI, RSP and SPY; inflation votes read FRED breakevens and crude futures inside TradingView.","\uc131\uc7a5 \uc2e0\ud638\ub294 XLI, RSP, SPY\ub97c \uc77d\uace0, \uc778\ud50c\ub808\uc774\uc158 \uc2e0\ud638\ub294 TradingView \uc548\uc5d0\uc11c FRED \uae30\ub300 \uc778\ud50c\ub808\uc774\uc158\uacfc \uc6d0\uc720 \uc120\ubb3c\uc744 \uc77d\uc5b4\uc694."],t.w)
B.aRI=new A.b(B.h,["Liquidity-Gated Trend","\uc720\ub3d9\uc131 \uac8c\uc774\ud2b8 \ucd94\uc138"],t.w)
B.eh4=new A.b(B.h,["Fast + slow trend on the index, only while Fed net liquidity rises; a credit kill switch goes flat.","\uc9c0\uc218\uc758 \ube60\ub978 \ucd94\uc138 + \ub290\ub9b0 \ucd94\uc138\ub97c \uc5f0\uc900 \uc21c\uc720\ub3d9\uc131\uc774 \uc624\ub97c \ub54c\ub9cc \ub530\ub77c\uac00\uc694. \uc2e0\uc6a9 \ud0ac \uc2a4\uc704\uce58\uac00 \uc791\ub3d9\ud558\uba74 \uad00\ub9dd\ud574\uc694."],t.w)
B.em3=new A.b(B.h,["Trend following works best when money is flowing in. This stack blends fast and slow trend signals (EWMAC and a Donchian breakout), lets net liquidity (Fed balance sheet minus the Treasury's cash account and reverse repo) vote, and adds a hard credit kill switch: when the high-yield spread widens fast, the position goes flat. The liquidity rule is a practitioner heuristic; the trend and credit parts are published research.","\ucd94\uc138 \ucd94\uc885\uc740 \ub3c8\uc774 \ub4e4\uc5b4\uc62c \ub54c \uac00\uc7a5 \uc798 \ub9de\uc544\uc694. \uc774 \uad6c\uc131\uc740 \ube60\ub978 \ucd94\uc138\uc640 \ub290\ub9b0 \ucd94\uc138 \uc2e0\ud638(EWMAC\uc640 Donchian \ub3cc\ud30c)\ub97c \uc11e\uace0, \uc21c\uc720\ub3d9\uc131(\uc5f0\uc900 \ub300\ucc28\ub300\uc870\ud45c\uc5d0\uc11c \uc7ac\ubb34\ubd80 \ud604\uae08 \uacc4\uc88c\uc640 \uc5ed\ub808\ud3ec\ub97c \ube80 \uac12)\uc5d0 \ud22c\ud45c\ud558\uac8c \ud558\uace0, \uac15\ud55c \uc2e0\uc6a9 \ud0ac \uc2a4\uc704\uce58\ub97c \ub354\ud574\uc694. \ud558\uc774\uc77c\ub4dc \uc2a4\ud504\ub808\ub4dc\uac00 \ube60\ub974\uac8c \ubc8c\uc5b4\uc9c0\uba74 \ud3ec\uc9c0\uc158\uc744 \uc815\ub9ac\ud574\uc694. \uc720\ub3d9\uc131 \uaddc\uce59\uc740 \uc2e4\ubb34\uc790\uc758 \uacbd\ud5d8\uce59\uc774\uace0, \ucd94\uc138\uc640 \uc2e0\uc6a9 \ubd80\ubd84\uc740 \ubc1c\ud45c\ub41c \uc5f0\uad6c\uc608\uc694."],t.w)
B.eXv=new A.b(B.h,["Fast + slow trend: EWMAC (1.5\xd7), Donchian 55/20, time-series momentum; ADX and credit kill-switch gates; volatility-sized.","\ube60\ub978 \ucd94\uc138 + \ub290\ub9b0 \ucd94\uc138: EWMAC(1.5\ubc30), Donchian 55/20, \uc2dc\uacc4\uc5f4 \ubaa8\uba58\ud140\uc774\uc5d0\uc694. ADX\uc640 \uc2e0\uc6a9 \ud0ac \uc2a4\uc704\uce58 \uac8c\uc774\ud2b8\ub97c \uac78\uace0 \ubcc0\ub3d9\uc131\uc5d0 \ub9de\ucdb0 \ube44\uc911\uc744 \uc815\ud574\uc694."],t.w)
B.eZQ=new A.b(B.h,["Liquidity gate blended in: net liquidity (double weight), its impulse, M2 impulse.","\uc720\ub3d9\uc131 \uac8c\uc774\ud2b8\ub97c \uc11e\uc5b4\uc694. \uc21c\uc720\ub3d9\uc131(2\ubc30), \uadf8 \ubcc0\ud654 \uc18d\ub3c4, M2 \ubcc0\ud654 \uc18d\ub3c4\uc608\uc694."],t.w)
B.ehF=new A.b(B.h,["Credit stress blended in: high-yield spread, credit curve, Chicago Fed financial conditions.","\uc2e0\uc6a9 \uc2a4\ud2b8\ub808\uc2a4\ub97c \uc11e\uc5b4\uc694. \ud558\uc774\uc77c\ub4dc \uc2a4\ud504\ub808\ub4dc, \uc2e0\uc6a9 \uace1\uc120, \uc2dc\uce74\uace0 \uc5f0\uc900 \uae08\uc735 \uc5ec\uac74\uc774\uc5d0\uc694."],t.w)
B.f_j=new A.b(B.h,["The net-liquidity inputs: Fed assets, Treasury account, reverse repo (FRED).","\uc21c\uc720\ub3d9\uc131\uc758 \uc785\ub825\uac12: \uc5f0\uc900 \uc790\uc0b0, \uc7ac\ubb34\ubd80 \uacc4\uc88c, \uc5ed\ub808\ud3ec(FRED)\uc608\uc694."],t.w)
B.eIY=new A.b(B.h,["The high-yield spread itself (FRED).","\ud558\uc774\uc77c\ub4dc \uc2a4\ud504\ub808\ub4dc \uc790\uccb4\uc608\uc694(FRED)."],t.w)
B.eye=new A.b(B.h,["6-month correlation of price with the spread: strongly negative means credit is driving stocks.","\uac00\uaca9\uacfc \uc2a4\ud504\ub808\ub4dc\uc758 6\uac1c\uc6d4 \uc0c1\uad00\uad00\uacc4\uc608\uc694. \uac15\ud55c \uc74c\uc218\uc774\uba74 \uc2e0\uc6a9\uc774 \uc8fc\uc2dd\uc744 \uc6c0\uc9c1\uc774\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694."],t.w)
B.eqQ=new A.b(B.h,["The Liquidity tug-of-war scenario: Fed, Treasury and money-fund stances, three branch cones and the 2019 repo-spike analog.","2019\ub144 \ub808\ud3ec \uae09\ub4f1 \uc720\uc0ac \uc0ac\ub840\uac00 \uc788\ub294 \uc720\ub3d9\uc131 \uc904\ub2e4\ub9ac\uae30 \uc2dc\ub098\ub9ac\uc624\uc608\uc694. \uc5f0\uc900, \uc7ac\ubb34\ubd80, \uba38\ub2c8\ub9c8\ucf13\ud380\ub4dc\uc758 \uc785\uc7a5\uacfc \uac08\ub798\ubcc4 \ubc94\uc704 \uc138 \uac1c\uac00 \ub098\uc640\uc694."],t.w)
B.eBp=new A.b(B.h,["Use on SPY or QQQ. Long when the trend composite clears the entry threshold AND the liquidity votes are not negative. A grey flat stretch with a wide spread is the kill switch at work.","SPY\ub098 QQQ\uc5d0\uc11c \uc4f0\uc138\uc694. \ucd94\uc138 \uc885\ud569 \uc810\uc218\uac00 \uc9c4\uc785 \uae30\uc900\uc744 \ub118\uace0 \uc720\ub3d9\uc131 \uc2e0\ud638\uac00 \uc74c\uc218\uac00 \uc544\ub2d0 \ub54c \ub9e4\uc218\ud574\uc694. \uc2a4\ud504\ub808\ub4dc\uac00 \ub113\uc740\ub370 \ud68c\uc0c9 \uad00\ub9dd \uad6c\uac04\uc774 \ub098\uc624\uba74 \ud0ac \uc2a4\uc704\uce58\uac00 \uc791\ub3d9\ud55c \uac70\uc608\uc694."],t.w)
B.eZL=new A.b(B.h,["Liquidity-driven rallies such as April 2020\u20132021, when the Fed's balance sheet grew quickly.","\uc5f0\uc900\uc758 \ub300\ucc28\ub300\uc870\ud45c\uac00 \ube60\ub974\uac8c \ucee4\uc9c4 2020\ub144 4\uc6d4~2021\ub144\ucc98\ub7fc \uc720\ub3d9\uc131\uc774 \uc774\ub048 \uc0c1\uc2b9\uc5d0\uc11c \uc798 \ub9de\uc544\uc694."],t.w)
B.eWf=new A.b(B.h,["Rallies that ignore liquidity, such as much of 2023, when stocks rose while quantitative tightening continued (approx).","\uc591\uc801 \uae34\ucd95\uc774 \uc774\uc5b4\uc9c0\ub294\ub370\ub3c4 \uc8fc\uc2dd\uc774 \uc62c\ub790\ub358 2023\ub144 \ub300\ubd80\ubd84\ucc98\ub7fc(\ub300\ub7b5) \uc720\ub3d9\uc131\uc744 \ubb34\uc2dc\ud55c \uc0c1\uc2b9\uc5d0\uc11c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694."],t.w)
B.ekK=new A.b(B.h,["Most votes are FRED series: neutral in this preview until a FRED feed is on; real inside TradingView.","\ub300\ubd80\ubd84\uc758 \uc2e0\ud638\ub294 FRED \uc9c0\ud45c\uc608\uc694. FRED \uc5f0\uacb0 \uc804\uc5d0\ub294 \ubbf8\ub9ac\ubcf4\uae30\uc5d0\uc11c \uc911\ub9bd\uc774\uace0, TradingView \uc548\uc5d0\uc11c\ub294 \uc2e4\uc81c \uac12\uc774\uc5d0\uc694."],t.w)
B.aSs=new A.b(B.h,["Curve-Shape Duration","\uace1\uc120 \ubaa8\uc591 \ub4c0\ub808\uc774\uc158"],t.w)
B.eWX=new A.b(B.h,["Labels the yield-curve move (bull/bear, steepener/flattener) and tilts between short, middle and long Treasuries.","\uc218\uc775\ub960 \uace1\uc120\uc758 \uc6c0\uc9c1\uc784(\ubd88/\ubca0\uc5b4, \uc2a4\ud2f0\ud504\ub108/\ud50c\ub798\ud2b8\ub108)\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\uace0, \ub2e8\uae30\xb7\uc911\uae30\xb7\uc7a5\uae30 \uad6d\ucc44 \uc0ac\uc774\uc5d0\uc11c \ube44\uc911\uc744 \uae30\uc6b8\uc5ec\uc694."],t.w)
B.eln=new A.b(B.h,["How the curve moves matters more than its level. A bull steepener (short rates falling fastest) usually means cuts are coming; a bear steepener (long rates rising fastest) hurts long bonds. This stack votes on curve shape (steepener, butterfly, term premium, inversion, policy gap), confirms with the bond trend, and checks inflation pressure before favouring duration.","\uace1\uc120\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\uac00 \uc218\uc900\ubcf4\ub2e4 \uc911\uc694\ud574\uc694. \ubd88 \uc2a4\ud2f0\ud504\ub108(\ub2e8\uae30 \uae08\ub9ac\uac00 \uac00\uc7a5 \ube68\ub9ac \ub0b4\ub9bc)\ub294 \ubcf4\ud1b5 \uc778\ud558\uac00 \uc628\ub2e4\ub294 \ub73b\uc774\uace0, \ubca0\uc5b4 \uc2a4\ud2f0\ud504\ub108(\uc7a5\uae30 \uae08\ub9ac\uac00 \uac00\uc7a5 \ube68\ub9ac \uc624\ub984)\ub294 \uc7a5\uae30 \ucc44\uad8c\uc5d0 \ud0c0\uaca9\uc774\uc5d0\uc694. \uc774 \uad6c\uc131\uc740 \uace1\uc120 \ubaa8\uc591(\uc2a4\ud2f0\ud504\ub108, \ubc84\ud130\ud50c\ub77c\uc774, \uae30\uac04 \ud504\ub9ac\ubbf8\uc5c4, \uc5ed\uc804, \uc815\ucc45 \uac2d)\uc5d0 \ud22c\ud45c\ud558\uace0, \ucc44\uad8c \ucd94\uc138\ub85c \ud655\uc778\ud558\uace0, \ub4c0\ub808\uc774\uc158\uc744 \uc120\ud638\ud558\uae30 \uc804\uc5d0 \uc778\ud50c\ub808\uc774\uc158 \uc555\ub825\uc744 \uc810\uac80\ud574\uc694."],t.w)
B.eng=new A.b(B.h,["Curve votes: steepener (double weight), butterfly, term premium, inversion, 2-year vs Fed funds; recession bands on.","\uace1\uc120 \uc2e0\ud638: \uc2a4\ud2f0\ud504\ub108(2\ubc30), \ubc84\ud130\ud50c\ub77c\uc774, \uae30\uac04 \ud504\ub9ac\ubbf8\uc5c4, \uc5ed\uc804, 2\ub144 \uae08\ub9ac \ub300 \uc5f0\ubc29\uae30\uae08\uae08\ub9ac\uc608\uc694. \uacbd\uae30 \uce68\uccb4 \uad6c\uac04\uc744 \ucf1c \ub46c\uc694."],t.w)
B.eH4=new A.b(B.h,["Duration trend blended in: time-series momentum and the 50/200 regime on the chart (use TLT or IEF).","\ub4c0\ub808\uc774\uc158 \ucd94\uc138\ub97c \uc11e\uc5b4\uc694. \ucc28\ud2b8\uc758 \uc2dc\uacc4\uc5f4 \ubaa8\uba58\ud140\uacfc 50/200 \uad6d\uba74\uc774\uc5d0\uc694(TLT\ub098 IEF\ub97c \uc4f0\uc138\uc694)."],t.w)
B.eIO=new A.b(B.h,["Inflation pressure blended in: breakevens, core PCE, inflation expectations anchor.","\uc778\ud50c\ub808\uc774\uc158 \uc555\ub825\uc744 \uc11e\uc5b4\uc694. \uae30\ub300 \uc778\ud50c\ub808\uc774\uc158, \uadfc\uc6d0 PCE, \uc778\ud50c\ub808\uc774\uc158 \uae30\ub300 \uc575\ucee4\uc608\uc694."],t.w)
B.exf=new A.b(B.h,["10y\u20132y and 10y\u20133m spreads (FRED).","10\ub144-2\ub144, 10\ub144-3\uac1c\uc6d4 \uae08\ub9ac \ucc28\uc608\uc694(FRED)."],t.w)
B.eYi=new A.b(B.h,["The 10-year yield (FRED).","10\ub144 \uae08\ub9ac\uc608\uc694(FRED)."],t.w)
B.eoB=new A.b(B.h,["The duration ladder: SHY (1\u20133y), IEF (7\u201310y), TLT (20y+).","\ub4c0\ub808\uc774\uc158 \uc0ac\ub2e4\ub9ac\uc608\uc694. SHY(1~3\ub144), IEF(7~10\ub144), TLT(20\ub144 \uc774\uc0c1)\uc774\uc5d0\uc694."],t.w)
B.eYV=new A.b(B.h,["TLT \xf7 SHY: rising = long duration winning.","TLT \xf7 SHY: \uc624\ub974\uba74 \uc7a5\uae30 \ub4c0\ub808\uc774\uc158\uc774 \uc55e\uc11c\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694."],t.w)
B.eLv=new A.b(B.h,["One-year correlation of the chart with long\xf7short duration.","\ucc28\ud2b8\uc640 \uc7a5\uae30\xf7\ub2e8\uae30 \ub4c0\ub808\uc774\uc158\uc758 1\ub144 \uc0c1\uad00\uad00\uacc4\uc608\uc694."],t.w)
B.eYT=new A.b(B.h,["Put TLT (or IEF) on the chart. Positive = curve shape and trend favour duration; negative with rising breakevens = stay short (SHY). Watch the TLT\xf7SHY line for confirmation.","TLT(\ub610\ub294 IEF)\ub97c \ucc28\ud2b8\uc5d0 \uc62c\ub9ac\uc138\uc694. \uc591\uc218\uba74 \uace1\uc120 \ubaa8\uc591\uacfc \ucd94\uc138\uac00 \ub4c0\ub808\uc774\uc158\uc5d0 \uc720\ub9ac\ud558\ub2e4\ub294 \ub73b\uc774\uace0, \uc74c\uc218\uc5d0 \uae30\ub300 \uc778\ud50c\ub808\uc774\uc158\uc774 \uc624\ub974\uba74 \ub2e8\uae30(SHY)\uc5d0 \uba38\ubb34\ub974\uc138\uc694. \ud655\uc778\uc6a9\uc73c\ub85c TLT\xf7SHY \uc120\uc744 \uc9c0\ucf1c\ubcf4\uc138\uc694."],t.w)
B.eNi=new A.b(B.h,["Easing cycles that start with a bull steepener, such as 2007\u201308 and 2019.","2007~08\ub144\uacfc 2019\ub144\ucc98\ub7fc \ubd88 \uc2a4\ud2f0\ud504\ub108\ub85c \uc2dc\uc791\ud558\ub294 \uc644\ud654 \uc0ac\uc774\ud074\uc5d0\uc11c \uc798 \ub9de\uc544\uc694."],t.w)
B.eMj=new A.b(B.h,["Inflation-driven sell-offs where every maturity falls at once, such as 2022.","2022\ub144\ucc98\ub7fc \ubaa8\ub4e0 \ub9cc\uae30\uac00 \ud55c\uaebc\ubc88\uc5d0 \ub5a8\uc5b4\uc9c0\ub294 \uc778\ud50c\ub808\uc774\uc158\ubc1c \ub9e4\ub3c4\uc7a5\uc5d0\uc11c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694."],t.w)
B.eZ8=new A.b(B.h,["Curve votes are FRED series (neutral here until a FRED feed is on); SHY, IEF and TLT are market data.","\uace1\uc120 \uc2e0\ud638\ub294 FRED \uc9c0\ud45c\uc608\uc694(FRED \uc5f0\uacb0 \uc804\uc5d0\ub294 \uc5ec\uae30\uc11c \uc911\ub9bd). SHY, IEF, TLT\ub294 \uc2dc\uc7a5 \ub370\uc774\ud130\uc608\uc694."],t.w)
