B.enN=new A.b(B.h,["Six stress gauges vote; enough of them red turns defensive, with hysteresis to cut whipsaw.","\uc2a4\ud2b8\ub808\uc2a4 \uc9c0\ud45c \uc5ec\uc12f \uac1c\uac00 \ud22c\ud45c\ud574\uc694. \ucda9\ubd84\ud788 \ub9ce\uc740 \uc9c0\ud45c\uac00 \ube68\uac1c\uc9c0\uba74 \ubc29\uc5b4\ub85c \ub3cc\uc544\uc11c\uace0, \uc7a6\uc740 \ub4a4\uc9d1\ud798\uc744 \uc904\uc774\ub824\uace0 \uc774\ub825(\ud788\uc2a4\ud14c\ub9ac\uc2dc\uc2a4)\uc744 \ub46c\uc694."],t.w)
B.eJr=new A.b(B.h,["No single indicator calls every crisis, but stress tends to show up in several places before it reaches stock prices: credit spreads, the VIX term structure, regional banks, copper vs gold, the dollar and unemployment. Six equal votes make the composite; the strategy enters above +20 and only exits below 0, so one noisy gauge cannot flip it back and forth.","\ubaa8\ub4e0 \uc704\uae30\ub97c \uc54c\ub824 \uc8fc\ub294 \uc9c0\ud45c\ub294 \uc5c6\uc9c0\ub9cc, \uc2a4\ud2b8\ub808\uc2a4\ub294 \uc8fc\uac00\uc5d0 \ub2ff\uae30 \uc804\uc5d0 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694. \uc2e0\uc6a9 \uc2a4\ud504\ub808\ub4dc, VIX \uae30\uac04 \uad6c\uc870, \uc9c0\uc5ed \uc740\ud589, \uad6c\ub9ac \ub300 \uae08, \ub2ec\ub7ec, \uc2e4\uc5c5\uc774\uc5d0\uc694. \ub3d9\ub4f1\ud55c \uc5ec\uc12f \ud45c\uac00 \uc885\ud569 \uc810\uc218\ub97c \ub9cc\ub4e4\uace0, \uc804\ub7b5\uc740 +20 \uc704\uc5d0\uc11c \uc9c4\uc785\ud574 0 \uc544\ub798\uc5d0\uc11c\ub9cc \uccad\uc0b0\ud558\ubbc0\ub85c \uc7a1\uc74c\uc774 \ub9ce\uc740 \uc9c0\ud45c \ud558\ub098\uac00 \uc774\ub9ac\uc800\ub9ac \ub4a4\uc9d1\uc744 \uc218 \uc5c6\uc5b4\uc694."],t.w)
B.ew5=new A.b(B.h,["Six warning votes: high-yield spread, VIX \xf7 VIX3M, KRE \xf7 SPY, copper \xf7 gold, dollar trend, Sahm rule. Volatility-sized.","\uacbd\uace0 \uc2e0\ud638 \uc5ec\uc12f \uac1c: \ud558\uc774\uc77c\ub4dc \uc2a4\ud504\ub808\ub4dc, VIX \xf7 VIX3M, KRE \xf7 SPY, \uad6c\ub9ac \xf7 \uae08, \ub2ec\ub7ec \ucd94\uc138, Sahm \uaddc\uce59\uc774\uc5d0\uc694. \ubcc0\ub3d9\uc131\uc5d0 \ub9de\ucdb0 \ube44\uc911\uc744 \uc815\ud574\uc694."],t.w)
