B.emi=new A.b(B.h,["The Positioning cascade scenario: trend followers, dealers and short-vol sellers, with the 2018, 2020 and 2024 analogs.","2018\ub144, 2020\ub144, 2024\ub144 \uc720\uc0ac \uc0ac\ub840\uac00 \uc788\ub294 \ud3ec\uc9c0\uc158 \uc5f0\uc1c4 \ud558\ub77d \uc2dc\ub098\ub9ac\uc624\uc608\uc694. \ucd94\uc138 \ucd94\uc885\uc790, \ub51c\ub7ec, \ubcc0\ub3d9\uc131 \ub9e4\ub3c4\uc790\uac00 \ub098\uc640\uc694."],t.w)
B.exo=new A.b(B.h,["Use on SPY. Green markers = enough gauges calm to re-enter; red = the composite fell below 0. Check which data panels turned first: that is the stress's source.","SPY\uc5d0\uc11c \uc4f0\uc138\uc694. \ucd08\ub85d \ud45c\uc2dc\ub294 \uc7ac\uc9c4\uc785\ud560 \ub9cc\ud07c \ucda9\ubd84\ud55c \uc9c0\ud45c\uac00 \uc7a0\uc7a0\ud558\ub2e4\ub294 \ub73b\uc774\uace0, \ube68\uac04 \ud45c\uc2dc\ub294 \uc885\ud569 \uc810\uc218\uac00 0 \uc544\ub798\ub85c \ub0b4\ub824\uac14\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \uc5b4\ub5a4 \ub370\uc774\ud130 \ud328\ub110\uc774 \uba3c\uc800 \ubc14\ub00c\uc5c8\ub294\uc9c0 \ubcf4\uc138\uc694. \uadf8\uac8c \uc2a4\ud2b8\ub808\uc2a4\uc758 \ucd9c\ucc98\uc608\uc694."],t.w)
B.et0=new A.b(B.h,["Slow-building stress such as 2007\u201308, when credit spreads and banks weakened months before the worst of the stock decline.","2007~08\ub144\ucc98\ub7fc \uc8fc\uac00 \ud558\ub77d\uc774 \uac00\uc7a5 \uc2ec\ud574\uc9c0\uae30 \uba87 \ub2ec \uc804\uc5d0 \uc2e0\uc6a9 \uc2a4\ud504\ub808\ub4dc\uc640 \uc740\ud589\uc774 \uc57d\ud574\uc9c4 \uc11c\uc11c\ud788 \uc313\uc774\ub294 \uc2a4\ud2b8\ub808\uc2a4\uc5d0\uc11c \uc798 \ub9de\uc544\uc694."],t.w)
B.eFW=new A.b(B.h,["Sudden shocks with no build-up (March 2020) and sharp V-shaped recoveries, where the exit-below-0 rule re-enters late.","2020\ub144 3\uc6d4\ucc98\ub7fc \ubbf8\ub9ac \uc313\uc778 \uc9d5\ud6c4\uac00 \uc5c6\ub294 \uac11\uc791\uc2a4\ub7ec\uc6b4 \ucda9\uaca9\uacfc, 0 \uc544\ub798 \uccad\uc0b0 \uaddc\uce59\uc774 \ub2a6\uac8c \uc7ac\uc9c4\uc785\ud558\ub294 \uae09\ud55c V\uc790 \ud68c\ubcf5\uc5d0\uc11c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694."],t.w)
B.eB3=new A.b(B.h,["VIX, KRE, copper, gold and the dollar are market data; the spread and the Sahm rule are FRED series.","VIX, KRE, \uad6c\ub9ac, \uae08, \ub2ec\ub7ec\ub294 \uc2dc\uc7a5 \ub370\uc774\ud130\uc774\uace0, \uc2a4\ud504\ub808\ub4dc\uc640 Sahm \uaddc\uce59\uc740 FRED \uc9c0\ud45c\uc608\uc694."],t.w)
B.aTu=new A.b(B.h,["Cycle-Phase Sector Rotation","\uc0ac\uc774\ud074 \uad6d\uba74 \uc5c5\uc885 \uc21c\ud658"],t.w)
B.eRc=new A.b(B.h,["Reads the business-cycle phase from the curve, jobs and industry; shows which sector pair the phase favours.","\uc218\uc775\ub960 \uace1\uc120, \uace0\uc6a9, \uc0b0\uc5c5\uc73c\ub85c \uacbd\uae30 \uc0ac\uc774\ud074 \uad6d\uba74\uc744 \uc77d\uace0, \uadf8 \uad6d\uba74\uc5d0 \uc720\ub9ac\ud55c \uc5c5\uc885 \uc30d\uc744 \ubcf4\uc5ec \uc918\uc694."],t.w)
B.eju=new A.b(B.h,["Sectors tend to lead at different points in the business cycle: consumer discretionary and financials early, technology and industrials mid-cycle, energy and materials late, staples and utilities in recession. The phase comes from the yield curve, jobless claims, unemployment and industry; relative strength must confirm. The phase map is a practitioner heuristic; academic tests of sector rotation are mixed, so treat it as a hypothesis.","\uc5c5\uc885\uc740 \uacbd\uae30 \uc0ac\uc774\ud074\uc758 \uc2dc\uc810\ub9c8\ub2e4 \uc55e\uc11c\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694. \ucd08\ubc18\uc5d0\ub294 \uacbd\uae30\uc18c\ube44\uc7ac\uc640 \uae08\uc735, \uc911\ubc18\uc5d0\ub294 \uae30\uc220\uacfc \uc0b0\uc5c5\uc7ac, \ud6c4\ubc18\uc5d0\ub294 \uc5d0\ub108\uc9c0\uc640 \uc18c\uc7ac, \uce68\uccb4\uae30\uc5d0\ub294 \ud544\uc218\uc18c\ube44\uc7ac\uc640 \uc720\ud2f8\ub9ac\ud2f0\uc608\uc694. \uad6d\uba74\uc740 \uc218\uc775\ub960 \uace1\uc120, \uc2e4\uc5c5\uc218\ub2f9 \uccad\uad6c, \uc2e4\uc5c5, \uc0b0\uc5c5\uc5d0\uc11c \ub098\uc624\uace0, \uc0c1\ub300 \uac15\ub3c4\uac00 \uc774\ub97c \ud655\uc778\ud574\uc57c \ud574\uc694. \uad6d\uba74 \uc9c0\ub3c4\ub294 \uc2e4\ubb34\uc790\uc758 \uacbd\ud5d8\uce59\uc774\uace0 \uc5c5\uc885 \uc21c\ud658\uc5d0 \ub300\ud55c \ud559\uc220 \uc2dc\ud5d8\uc740 \uc5c7\uac08\ub824\uc694. \uac00\uc124\ub85c \ub2e4\ub904 \uc8fc\uc138\uc694."],t.w)
B.eR8=new A.b(B.h,["Cycle-phase votes: growth regime (double weight), steepener, claims, industrial production, unemployment.","\uc0ac\uc774\ud074 \uad6d\uba74 \uc2e0\ud638: \uc131\uc7a5 \uad6d\uba74(2\ubc30), \uc2a4\ud2f0\ud504\ub108, \uc2e4\uc5c5\uc218\ub2f9 \uccad\uad6c, \uc0b0\uc5c5 \uc0dd\uc0b0, \uc2e4\uc5c5\uc774\uc5d0\uc694."],t.w)
