B.eJl=new A.b(B.h,['When the debt limit binds, the Treasury runs down its cash account until Congress acts. Bills maturing near the "X-date" trade at a premium yield; a late deal can bring a rating downgrade; after any deal the Treasury rebuilds its cash, which drains liquidity.',"\ubd80\ucc44 \ud55c\ub3c4\uc5d0 \uac78\ub9ac\uba74 \uc758\ud68c\uac00 \uc6c0\uc9c1\uc77c \ub54c\uae4c\uc9c0 \uc7ac\ubb34\ubd80\ub294 \ud604\uae08 \uacc4\uc88c\ub97c \uc904\uc5ec \uac00\uba70 \ubc84\ud168\uc694. 'X-date' \uadfc\ucc98\uc5d0 \ub9cc\uae30\uac00 \uc624\ub294 \ub2e8\uae30 \uad6d\ucc44\ub294 \ud504\ub9ac\ubbf8\uc5c4 \uae08\ub9ac\ub85c \uac70\ub798\ub3fc\uc694. \ud569\uc758\uac00 \ub2a6\uc73c\uba74 \ub4f1\uae09 \uac15\ub4f1\uc774 \uc62c \uc218 \uc788\uace0, \uc5b4\ub5a4 \ud569\uc758\ub4e0 \ub4a4\uc5d0\ub294 \uc7ac\ubb34\ubd80\uac00 \ud604\uae08\uc744 \ub2e4\uc2dc \uc313\uc544\uc11c \uc720\ub3d9\uc131\uc774 \ube60\uc838\ub098\uac00\uc694."],t.w)
