B.eYp=new A.b(B.h,["Implied volatility usually sits above realized volatility; when realized volatility overtakes the VIX the market is under stress. The build combines that premium with the volatility regime and a trend vote. It is a flag on the chart symbol, not an options strategy.","\ub0b4\uc7ac \ubcc0\ub3d9\uc131\uc740 \ubcf4\ud1b5 \uc2e4\ud604 \ubcc0\ub3d9\uc131\ubcf4\ub2e4 \ub192\uc544\uc694. \uc2e4\ud604 \ubcc0\ub3d9\uc131\uc774 VIX\ub97c \ub118\uc5b4\uc11c\uba74 \uc2dc\uc7a5\uc774 \uc555\ubc15\uc744 \ubc1b\ub294 \uac70\uc608\uc694. \uc774 \uad6c\uc131\uc740 \uadf8 \ud504\ub9ac\ubbf8\uc5c4\uc5d0 \ubcc0\ub3d9\uc131 \uad6d\uba74\uacfc \ucd94\uc138 \ud22c\ud45c\ub97c \ud569\uccd0\uc694. \ucc28\ud2b8 \uc885\ubaa9\uc5d0 \uac70\ub294 \ud45c\uc2dc\uc774\uc9c0, \uc635\uc158 \uc804\ub7b5\uc774 \uc544\ub2c8\uc5d0\uc694."],t.w)
B.exT=new A.b(B.h,["Premium positive, volatility regime low and trend up = calm market (positive composite). A negative premium or a top-of-year volatility rank flips the mix toward cash.","\ud504\ub9ac\ubbf8\uc5c4\uc774 \ud50c\ub7ec\uc2a4\uc774\uace0 \ubcc0\ub3d9\uc131 \uad6d\uba74\uc774 \ub0ae\uace0 \ucd94\uc138\uac00 \uc704 = \uc794\uc794\ud55c \uc2dc\uc7a5(\uc885\ud569 \uc810\uc218 \ud50c\ub7ec\uc2a4)\uc774\uc5d0\uc694. \ud504\ub9ac\ubbf8\uc5c4\uc774 \ub9c8\uc774\ub108\uc2a4\uc774\uac70\ub098 \ubcc0\ub3d9\uc131 \uc21c\uc704\uac00 \uc5f0\uc911 \ucd5c\uc0c1\uc704\uba74 \ud63c\ud569 \uc810\uc218\uac00 \ud604\uae08 \ucabd\uc73c\ub85c \uae30\uc6b8\uc5b4\uc694."],t.w)
B.eIC=new A.b(B.h,["Stretches where volatility spikes and stays high, such as extended sell-offs.","\uae34 \ud558\ub77d\uc7a5\ucc98\ub7fc \ubcc0\ub3d9\uc131\uc774 \uce58\uc19f\uc544 \ub192\uac8c \uba38\ubb34\ub294 \uad6c\uac04\uc774\uc5d0\uc694."],t.w)
B.eJU=new A.b(B.h,["Brief spikes that reverse within days: the flag cuts exposure near the low.","\uba70\uce60 \uc548\uc5d0 \ub418\ub3cc\uc544\uac00\ub294 \uc9e7\uc740 \uae09\ub4f1: \ud45c\uc2dc\uac00 \uc800\uc810 \uadfc\ucc98\uc5d0\uc11c \ud22c\uc790 \ube44\uc911\uc744 \uc904\uc5ec\uc694."],t.w)
B.eQR=new A.b(B.h,["VIX and SPY (market symbols, live via your forge in the app), plus the chart's own prices.","VIX\uc640 SPY(\uc2dc\uc7a5 \uc885\ubaa9, \uc571\uc5d0\uc11c\ub294 forge\ub85c \uc2e4\uc2dc\uac04), \uadf8\ub9ac\uace0 \ucc28\ud2b8 \uc790\uccb4\uc758 \uac00\uaca9\uc774\uc5d0\uc694."],t.w)
B.eX9=new A.b(B.h,["Volatility premium (double weight), volatility regime, realized volatility and the 10-month average; ADX gate; volatility-target sizing.","\ubcc0\ub3d9\uc131 \ud504\ub9ac\ubbf8\uc5c4(\uac00\uc911\uce58 \ub450 \ubc30), \ubcc0\ub3d9\uc131 \uad6d\uba74, \uc2e4\ud604 \ubcc0\ub3d9\uc131, 10\uac1c\uc6d4 \ud3c9\uade0\uc774\uc5d0\uc694. ADX \uac8c\uc774\ud2b8\uc640 \ubaa9\ud45c \ubcc0\ub3d9\uc131 \ud22c\uc785 \ube44\uc911\ub3c4 \uc368\uc694."],t.w)
