B.eLw=new A.b(B.h,["Spread and ratio z-scores against a pair, only while the two stay correlated.","\uc9dd \uc885\ubaa9\uacfc\uc758 \uc2a4\ud504\ub808\ub4dc\uc640 \ube44\uc728 z-\uc810\uc218\ub97c \uc4f0\ub418, \ub450 \uc885\ubaa9\uc774 \uc0c1\uad00\uad00\uacc4\ub97c \uc720\uc9c0\ud560 \ub54c\ub9cc \uc368\uc694."],t.w)
B.eIn=new A.b(B.h,["Two closely related assets tend to drift back together after an unusual gap. The build votes for convergence from the log spread (guarded by return correlation) and the price ratio, and shows the pair and their correlation so you can judge whether the link still holds.","\uc11c\ub85c \uac00\uae4c\uc6b4 \ub450 \uc790\uc0b0\uc740 \ud3c9\uc18c\uc640 \ub2e4\ub978 \uaca9\ucc28\uac00 \ubc8c\uc5b4\uc9c4 \ub4a4 \ub2e4\uc2dc \ubd99\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694. \uc774 \uad6c\uc131\uc740 \ub85c\uadf8 \uc2a4\ud504\ub808\ub4dc(\uc218\uc775\ub960 \uc0c1\uad00\uad00\uacc4\ub85c \ubcf4\ud638)\uc640 \uac00\uaca9 \ube44\uc728\ub85c \uc218\ub834\uc5d0 \ud22c\ud45c\ud558\uace0, \uc9dd\uacfc \ub458\uc758 \uc0c1\uad00\uad00\uacc4\ub97c \ubcf4\uc5ec\uc918\uc11c \uc5f0\uacb0\uc774 \uc544\uc9c1 \uc720\ud6a8\ud55c\uc9c0 \ud310\ub2e8\ud560 \uc218 \uc788\uac8c \ud574\uc694."],t.w)
B.eIh=new A.b(B.h,["Composite negative = the chart symbol is rich against its pair; positive = cheap. A zero spread vote while the ratio vote is active means the correlation guard switched the spread off.","\uc885\ud569 \uc810\uc218\uac00 \ub9c8\uc774\ub108\uc2a4 = \ucc28\ud2b8 \uc885\ubaa9\uc774 \uc9dd\uc5d0 \ube44\ud574 \ube44\uc2f8\uc694. \ud50c\ub7ec\uc2a4 = \uc2f8\uc694. \ube44\uc728 \ud22c\ud45c\ub294 \ucf1c\uc838 \uc788\ub294\ub370 \uc2a4\ud504\ub808\ub4dc \ud22c\ud45c\uac00 0\uc774\uba74, \uc0c1\uad00\uad00\uacc4 \ubcf4\ud638 \uc7a5\uce58\uac00 \uc2a4\ud504\ub808\ub4dc\ub97c \uaebc \ub454 \uac70\uc608\uc694."],t.w)
B.f_h=new A.b(B.h,["Stable pairs (same industry, close substitutes) that wander around a steady relationship.","\uac19\uc740 \uc0b0\uc5c5\uc774\ub098 \ube44\uc2b7\ud55c \ub300\uccb4\uc7ac\ucc98\ub7fc, \uc548\uc815\uc801\uc778 \uad00\uacc4 \uc8fc\ubcc0\uc744 \uc624\uac00\ub294 \uc9dd\uc774\uc5d0\uc694."],t.w)
