B.eFj=new A.b(B.h,["The pair symbol's price.","\uc9dd \uc885\ubaa9\uc758 \uac00\uaca9\uc774\uc5d0\uc694."],t.w)
B.eNf=new A.b(B.h,["Half-year correlation of price with the pair.","\uc9dd \uc885\ubaa9\uacfc \uac00\uaca9\uc758 \ubc18\ub144 \uc0c1\uad00\uad00\uacc4\uc608\uc694."],t.w)
B.aTU=new A.b(B.h,["Quality Momentum","\ud488\uc9c8 \ubaa8\uba58\ud140"],t.w)
B.eTv=new A.b(B.h,["12-1 momentum that counts only clean, persistent trends, with a crash-risk gate.","\uae54\ub054\ud558\uace0 \uafb8\uc900\ud55c \ucd94\uc138\ub9cc \uc138\ub294 12-1 \ubaa8\uba58\ud140\uc774\uc5d0\uc694. \ubd95\uad34 \uc704\ud5d8 \uac8c\uc774\ud2b8\uac00 \uc788\uc5b4\uc694."],t.w)
B.eSJ=new A.b(B.h,["Not all trends are equal: a smooth trend built from many small steps and a high efficiency ratio tends to differ from one built on a few jumps. The build blends 12-1 momentum with three quality measures and cuts exposure in the panic state where momentum has crashed.","\ucd94\uc138\uac00 \ub2e4 \uac19\uc740 \uac74 \uc544\ub2c8\uc5d0\uc694. \uc791\uc740 \uac78\uc74c\uc774 \uc313\uc774\uace0 \ud6a8\uc728 \ube44\uc728\uc774 \ub192\uc740 \ub9e4\ub044\ub7ec\uc6b4 \ucd94\uc138\ub294 \uba87 \ubc88\uc758 \uc810\ud504\ub85c \ub9cc\ub4e0 \ucd94\uc138\uc640 \ub2ec\ub77c\uc694. \uc774 \uad6c\uc131\uc740 12-1 \ubaa8\uba58\ud140\uc5d0 \ud488\uc9c8 \uc9c0\ud45c \uc138 \uac1c\ub97c \uc11e\uace0, \ubaa8\uba58\ud140\uc774 \ubb34\ub108\uc9c4 \uacf5\ud3ec \uc0c1\ud0dc\uc5d0\uc11c\ub294 \ud22c\uc790 \ube44\uc911\uc744 \uc904\uc5ec\uc694."],t.w)
B.ek5=new A.b(B.h,["All four votes positive = a strong, smooth uptrend. Momentum positive but efficiency and smoothness near zero = a choppy advance. The gate halves or flattens the mix after a bear year with high volatility.","\ud22c\ud45c \ub124 \uac1c\uac00 \ubaa8\ub450 \ud50c\ub7ec\uc2a4 = \uac15\ud558\uace0 \ub9e4\ub044\ub7ec\uc6b4 \uc0c1\uc2b9 \ucd94\uc138\uc608\uc694. \ubaa8\uba58\ud140\uc740 \ud50c\ub7ec\uc2a4\uc778\ub370 \ud6a8\uc728\uacfc \ub9e4\ub044\ub7ec\uc6c0\uc774 0 \uadfc\ucc98 = \ub4e4\ucb49\ub0a0\ucb49\ud55c \uc0c1\uc2b9\uc774\uc5d0\uc694. \ud558\ub77d\ud55c \ud574\uc5d0 \ubcc0\ub3d9\uc131\uae4c\uc9c0 \ub192\uc73c\uba74 \uac8c\uc774\ud2b8\uac00 \ud63c\ud569 \uc810\uc218\ub97c \uc808\ubc18\uc73c\ub85c \uc904\uc774\uac70\ub098 \ud604\uae08\uc73c\ub85c \ub46c\uc694."],t.w)
B.evt=new A.b(B.h,["Long, orderly trends.","\uae38\uace0 \uc9c8\uc11c \uc788\ub294 \ucd94\uc138\uc608\uc694."],t.w)
B.el5=new A.b(B.h,["Sharp V-shaped reversals; the gate reacts to the panic state, not to the turn itself.","\uae09\uaca9\ud55c V\uc790 \ubc18\uc804: \uac8c\uc774\ud2b8\ub294 \uc804\ud658 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uacf5\ud3ec \uc0c1\ud0dc\uc5d0 \ubc18\uc751\ud574\uc694."],t.w)
