B.eUD=new A.b(B.h,["12-1 momentum (double weight), Kaufman efficiency, frog-in-the-pan smoothness and the Hurst persistence vote; momentum crash gate; volatility-target sizing.","12-1 \ubaa8\uba58\ud140(\uac00\uc911\uce58 \ub450 \ubc30), \uce74\uc6b0\ud504\ub9cc \ud6a8\uc728, \uac1c\uad6c\ub9ac \ub0c4\ube44(frog-in-the-pan) \ub9e4\ub044\ub7ec\uc6c0, \ud5c8\uc2a4\ud2b8 \uc9c0\uc18d\uc131 \ud22c\ud45c\uc608\uc694. \ubaa8\uba58\ud140 \ubd95\uad34 \uac8c\uc774\ud2b8\uc640 \ubaa9\ud45c \ubcc0\ub3d9\uc131 \ud22c\uc785 \ube44\uc911\ub3c4 \ud568\uaed8 \uc368\uc694."],t.w)
B.aTe=new A.b(B.h,["Risk-Parity Macro Sleeve","\uc704\ud5d8 \uade0\ud615 \uac70\uc2dc \uc2ac\ub9ac\ube0c"],t.w)
B.eVQ=new A.b(B.h,["Trend and macro votes sized by inverse volatility against bonds and gold, with a correlation gate.","\ucc44\uad8c, \uae08\uc5d0 \ub300\ud55c \ubcc0\ub3d9\uc131 \uc5ed\uc218\ub85c \uaddc\ubaa8\ub97c \uc815\ud55c \ucd94\uc138\uc640 \uac70\uc2dc \ud22c\ud45c\uc608\uc694. \uc0c1\uad00\uad00\uacc4 \uac8c\uc774\ud2b8\uac00 \uc788\uc5b4\uc694."],t.w)
B.eQz=new A.b(B.h,["A sleeve of a balanced portfolio: trend and two rate votes decide the direction, the position is sized by its inverse-volatility share against bonds and gold, and the mix is cut when stocks, bonds and gold start moving together.","\uade0\ud615 \uc7a1\ud78c \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uc758 \ud55c \uc870\uac01\uc774\uc5d0\uc694. \ucd94\uc138\uc640 \uae08\ub9ac \ud22c\ud45c \ub450 \uac1c\uac00 \ubc29\ud5a5\uc744 \uc815\ud558\uace0, \ucc44\uad8c\xb7\uae08 \ub300\ube44 \uc5ed\ubcc0\ub3d9\uc131 \ubaab\uc73c\ub85c \ud3ec\uc9c0\uc158 \ud06c\uae30\ub97c \uc815\ud574\uc694. \uc8fc\uc2dd, \ucc44\uad8c, \uae08\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud558\uba74 \ud63c\ud569 \uc810\uc218\ub97c \uc904\uc5ec\uc694."],t.w)
B.eB_=new A.b(B.h,["Composite above zero = hold the sleeve; the sizing scalar below 1 means the chart symbol is riskier than its basket mates. The gate shrinking toward 0 = diversification is failing.","\uc885\ud569 \uc810\uc218\uac00 0\ubcf4\ub2e4 \ub192\uc73c\uba74 \uc2ac\ub9ac\ube0c\ub97c \ubcf4\uc720\ud574\uc694. \ud22c\uc785 \ube44\uc911 \uac12\uc774 1\ubcf4\ub2e4 \uc791\uc73c\uba74 \ucc28\ud2b8 \uc885\ubaa9\uc774 \ubc14\uc2a4\ucf13\uc758 \ub2e4\ub978 \uc790\uc0b0\ubcf4\ub2e4 \uc704\ud5d8\ud558\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \uac8c\uc774\ud2b8\uac00 0 \ucabd\uc73c\ub85c \uc904\uba74 \ubd84\uc0b0 \ud6a8\uacfc\uac00 \uc0ac\ub77c\uc9c0\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694."],t.w)
