B.egd=new A.b(B.h,["Episodes when stocks and bonds fall together; the gate cuts size but cannot make the sleeve safe.","\uc8fc\uc2dd\uacfc \ucc44\uad8c\uc774 \ud568\uaed8 \ub5a8\uc5b4\uc9c0\ub294 \uc2dc\uae30: \uac8c\uc774\ud2b8\uac00 \uaddc\ubaa8\ub97c \uc904\uc774\uc9c0\ub9cc \uc2ac\ub9ac\ube0c\ub97c \uc548\uc804\ud558\uac8c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\uc5b4\uc694."],t.w)
B.eoG=new A.b(B.h,["TLT, GLD and SPY (market symbols), the 10-year real yield and the 10y minus 2y spread (FRED).","TLT, GLD, SPY(\uc2dc\uc7a5 \uc885\ubaa9), 10\ub144 \uc2e4\uc9c8\uae08\ub9ac, 10\ub144\ubb3c \u2212 2\ub144\ubb3c \uc2a4\ud504\ub808\ub4dc(FRED)\uc608\uc694."],t.w)
B.eF4=new A.b(B.h,["TSMOM, the 10-month average, the real-yield vote and curve slope momentum; correlation-regime gate; inverse-volatility sizing.","TSMOM, 10\uac1c\uc6d4 \ud3c9\uade0, \uc2e4\uc9c8\uae08\ub9ac \ud22c\ud45c, \uae08\ub9ac \uace1\uc120 \uae30\uc6b8\uae30 \ubaa8\uba58\ud140\uc774\uc5d0\uc694. \uc0c1\uad00\uad00\uacc4 \uad6d\uba74 \uac8c\uc774\ud2b8\uc640 \uc5ed\ubcc0\ub3d9\uc131 \ud22c\uc785 \ube44\uc911\ub3c4 \uc368\uc694."],t.w)
B.eM2=new A.b(B.h,["Long bonds (TLT): one of the two assets the sizing compares against.","\uc7a5\uae30\ucc44(TLT): \ud22c\uc785 \ube44\uc911\uc774 \ube44\uad50\ud558\ub294 \ub450 \uc790\uc0b0 \uc911 \ud558\ub098\uc608\uc694."],t.w)
B.eHd=new A.b(B.h,["Gold (GLD): the other basket asset.","\uae08(GLD): \ubc14\uc2a4\ucf13\uc758 \ub2e4\ub978 \uc790\uc0b0\uc774\uc5d0\uc694."],t.w)
B.eOa=new A.b(B.h,["Half-year correlation of price with long bonds.","\uc7a5\uae30\ucc44\uc640 \uac00\uaca9\uc758 \ubc18\ub144 \uc0c1\uad00\uad00\uacc4\uc608\uc694."],t.w)
B.eKA=new A.b(B.h,["Stocks that did worst over a week tended to do better the next week, and the best ones worse, over decades of US data; much of it looked like short-term overreaction.","\uc218\uc2ed \ub144\uc758 \ubbf8\uad6d \ub370\uc774\ud130\uc5d0\uc11c, \ud55c \uc8fc \ub3d9\uc548 \uac00\uc7a5 \ubd80\uc9c4\ud588\ub358 \uc8fc\uc2dd\uc740 \ub2e4\uc74c \uc8fc\uc5d0 \ub354 \ub098\uc558\uace0 \uac00\uc7a5 \uc88b\uc558\ub358 \uc8fc\uc2dd\uc740 \ub354 \ub098\ube74\uc5b4\uc694. \ub300\ubd80\ubd84 \ub2e8\uae30 \uacfc\uc789 \ubc18\uc751\uc73c\ub85c \ubcf4\uc600\uc5b4\uc694."],t.w)
B.elM=new A.b(B.h,["The RSI fade on daily bars: it leans against a recent fall or rise. One symbol, free daily data, no costs in the score. A pattern in old data, not a promise.","\uc77c\ubd09 \uae30\uc900 RSI \uc5ed\ucd94\uc138\uc608\uc694. \ucd5c\uadfc\uc758 \ud558\ub77d\uc774\ub098 \uc0c1\uc2b9\uc5d0 \ubc18\ub300\ub85c \uac00\uc694. \uc885\ubaa9 \ud558\ub098, \ubb34\ub8cc \uc77c\uac04 \ub370\uc774\ud130, \uc810\uc218\uc5d0\ub294 \ube44\uc6a9\uc774 \ube60\uc838 \uc788\uc5b4\uc694. \uacfc\uac70 \ub370\uc774\ud130\uc758 \ud328\ud134\uc77c \ubfd0 \uc57d\uc18d\uc774 \uc544\ub2c8\uc5d0\uc694."],t.w)
B.eSm=new A.b(B.h,["Past one-month returns of single stocks predicted the next month with the opposite sign, a short-term reversal that stood out from the longer-term momentum seen over months.","\uac1c\ubcc4 \uc8fc\uc2dd\uc758 \uc9c0\ub09c \ud55c \ub2ec \uc218\uc775\ub960\uc740 \ub2e4\uc74c \ub2ec\uc5d0 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc774\uc5b4\uc84c\uc5b4\uc694. \uba87 \ub2ec\uc5d0 \uac78\uce5c \uc7a5\uae30 \ubaa8\uba58\ud140\uacfc\ub294 \ub2e4\ub978, \ub2e8\uae30 \ubc18\uc804\uc774\uc5c8\uc5b4\uc694."],t.w)
B.eYx=new A.b(B.h,["The RSI fade uses a few days to two weeks of price, not a ranked basket of stocks, so it only borrows the idea. Check it after costs.","RSI \uc5ed\ucd94\uc138\ub294 \uc885\ubaa9 \ubb36\uc74c\uc758 \uc21c\uc704\uac00 \uc544\ub2c8\ub77c \uba70\uce60\uc5d0\uc11c 2\uc8fc \uc815\ub3c4\uc758 \uac00\uaca9\uc744 \uc368\uc694. \uadf8\ub798\uc11c \uc544\uc774\ub514\uc5b4\ub9cc \ube4c\ub9b0 \uac70\uc608\uc694. \ube44\uc6a9\uc744 \ube80 \ub4a4\uc5d0 \ud655\uc778\ud558\uc138\uc694."],t.w)
B.eTd=new A.b(B.h,["A series can switch between a few hidden states (for example growth and slump), each with its own average and spread, and the switch can be estimated from the data.","\uc2dc\uacc4\uc5f4\uc740 \uba87 \uac00\uc9c0 \uc228\uc740 \uc0c1\ud0dc(\uc608: \uc131\uc7a5\uacfc \uce68\uccb4) \uc0ac\uc774\ub97c \uc624\uac08 \uc218 \uc788\uc5b4\uc694. \uc0c1\ud0dc\ub9c8\ub2e4 \ud3c9\uade0\uacfc \ud769\uc5b4\uc9d0\uc774 \ub2e4\ub974\uace0, \uc774 \uc804\ud658\uc740 \ub370\uc774\ud130\uc5d0\uc11c \ucd94\uc815\ud560 \uc218 \uc788\uc5b4\uc694."],t.w)
B.erk=new A.b(B.h,["No hidden-state model here: the block just labels calm and stormy stretches of daily volatility. It borrows the idea of regimes, not the estimation.","\uc228\uc740 \uc0c1\ud0dc \ubaa8\ub378\uc740 \uc4f0\uc9c0 \uc54a\uc544\uc694. \ube14\ub85d\uc740 \uc77c\uac04 \ubcc0\ub3d9\uc131\uc774 \uc7a0\uc7a0\ud55c \uad6c\uac04\uacfc \uac70\uce5c \uad6c\uac04\uc5d0 \uc774\ub984\uc744 \ubd99\uc77c \ubfd0\uc774\uc5d0\uc694. \uad6d\uba74\uc774\ub77c\ub294 \uc544\uc774\ub514\uc5b4\ub9cc \ube4c\ub9ac\uace0, \ucd94\uc815 \ubc29\ubc95\uc740 \ube4c\ub9ac\uc9c0 \uc54a\uc558\uc5b4\uc694."],t.w)
B.eMY=new A.b(B.h,["A short published discussion of the firm's reported returns and whether they can be explained away.","\uc774 \ud68c\uc0ac\uac00 \ubcf4\uace0\ud55c \uc218\uc775\ub960\uacfc, \uadf8\uac83\uc744 \ub2e4\ub978 \uc694\uc778\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc788\ub294\uc9c0\ub97c \uc9e7\uac8c \ub2e4\ub8ec \uacf5\uac1c \ub17c\uc758\uc608\uc694."],t.w)
