B.fTC=new A.b(B.dR,["Each block votes between -1 and +1; the weighted average becomes a -100..+100 regime score (above 0 = net bullish, above +50 = strong).","\uac01 \ube14\ub85d\uc740 -1\uc5d0\uc11c +1 \uc0ac\uc774\ub85c \ud22c\ud45c\ud558\uace0, \uac00\uc911 \ud3c9\uade0\uc774 -100~+100\uc758 \ub808\uc9d0 \uc810\uc218\uac00 \ub429\ub2c8\ub2e4 (0 \ucd08\uacfc = \uc21c\uac15\uc138, +50 \ucd08\uacfc = \uac15\ud55c \uac15\uc138).","\u6bcf\u4e2a\u533a\u5757\u5728\u22121\u5230+1\u4e4b\u95f4\u6295\u7968,\u52a0\u6743\u5e73\u5747\u5f97\u5230\u2212100~+100\u7684\u72b6\u6001\u5f97\u5206(\u5927\u4e8e0=\u51c0\u770b\u6da8,\u5927\u4e8e+50=\u5f3a\u70c8\u770b\u6da8)\u3002","\u5404\u30d6\u30ed\u30c3\u30af\u306f\u22121\u304b\u3089+1\u3067\u6295\u7968\u3057\u3001\u305d\u306e\u52a0\u91cd\u5e73\u5747\u304c\u2212100\u301c+100\u306e\u30ec\u30b8\u30fc\u30e0\u30b9\u30b3\u30a2\u306b\u306a\u308a\u307e\u3059(0\u8d85=\u30cd\u30c3\u30c8\u5f37\u6c17\u3001+50\u8d85=\u5f37\u3044\u5f37\u6c17)\u3002","Elk blok stemt tussen \u22121 en +1; het gewogen gemiddelde wordt een regimescore van \u2212100 tot +100 (boven 0 = netto bullish, boven +50 = sterk bullish)."],t.w)
