B.b46=new A.D("swipeActions",B.W,'Opt-in swipe-left reveal buttons (off unless set): objects { label, icon, action, role:"danger" } or builtins "edit"/"delete"; label may be a {lang: text} map.',B.l,null,!1)
B.i6o=new A.D("relativeHeaders",B.a9,'Humanize section headers: "Today"/"Tomorrow"/"Yesterday", a weekday + short date for the next 2-6 days, and the raw date string beyond that (default off \u2014 exact prior behavior).',B.l,null,!1)
B.hOF=new A.D("timeColumn",B.L,'A text column holding "HH:MM" (rules.time). When set, rows within each date section sort by it ascending (empty/unparseable rows last, preserving their existing order) and each row shows the parsed time as a leading label.',B.l,null,!1)
B.hXS=new A.D("hideWhenEmpty",B.a9,"Opt-in (njnest-1111): with no rows (and no search) the agenda shows nothing at all \u2014 no empty state.",B.l,null,!1)
B.hXx=new A.D("filter",B.W,"Static pre-filter { column, value|in } \u2014 OR a LIST of such maps, ANDed (same shape as `cards`' filter) \u2014 narrows the source rows before grouping, e.g. keeping a shared table's member/comment rows off the agenda, or combining a kind gate with a board scope.",B.l,null,!1)
