B.hdf=new A.dp("agenda","Rows grouped by their first present date.",B.d_P,!1)
B.hLi=new A.D("titleColumn",B.L,"Column shown on each day cell.",B.l,null,!1)
B.aaT=new A.D("action",B.W,"Row-tap action spec { fn, args }.",B.l,null,!1)
B.hIS=new A.D("addAction",B.W,'Day-tap action { fn, args }; the tapped date is merged into the new row\'s values under dateColumn. weekBoxes: fired by tapping a box\'s empty area or its "+ Tap/Click to add" line \u2014 every "$boxDate" in it becomes the box\'s yyyy-MM-dd (weekend box: its first day) and the date is merged into args.values[dateColumn] of the top-level step or of each addRow step of a chain, e.g. chain addRow {values, select: true} then goto the detail screen.',B.l,null,!1)
B.hP3=new A.D("dateColumn",B.L,"Column the tapped date fills for addAction (default first dateColumns).",B.l,null,!1)
B.hYn=new A.D("weekStart",B.Q,"First day of week: monday (default) or sunday.",B.l,null,!1)
B.i3n=new A.D("weekStartTable",B.b4,"Single-row prefs table whose weekStartColumn overrides weekStart live.",B.l,null,!1)
B.hG7=new A.D("weekStartColumn",B.L,"Column in weekStartTable holding monday|sunday (end-user preference).",B.l,null,!1)
B.hKq=new A.D("scroll",B.a9,"Continuous vertical scroll through months (centered on the current month) instead of the paged prev/next single month.",B.l,null,!1)
B.hHp=new A.D("continuous",B.a9,"Alias for scroll: continuous vertical scroll through months instead of the paged prev/next single month.",B.l,null,!1)
B.dyL=s(["today","firstWithData"],t.s)
B.hRF=new A.D("initialView",B.bG,'Which month opens first. "today" (default) opens the current month; "firstWithData" opens the earliest month containing any row (by dateColumns-resolved date) \u2014 falls back to today when the table has no dated rows.',B.dyL,null,!1)
B.hIg=new A.D("weekBoxes",B.a9,'Opt-in weekly planner: one box per weekday (Mon\u2013Fri) + a Weekend box for the week holding `$day:<settingKey>`; items show time + title (check-off via doneColumn/doneWhen), today\'s box is highlighted. Wide = 2-column grid; narrow = stacked, an empty day is one "Nothing yet" line. Uses table/dateColumn(s)/timeColumn/titleColumn/kindColumn/kindColors/filter/action like dayAgenda.',B.l,null,!1)
B.i2A=new A.D("settingKey",B.Q,"weekBoxes: the setting (a daybar's key) whose day picks the week; unset/invalid = this week.",B.l,null,!1)
B.hGo=new A.D("mergeWeekend",B.a9,"weekBoxes: default true \u2014 Saturday + Sunday share one Weekend box (items prefixed with their weekday); false = seven boxes.",B.l,null,!1)
B.i25=new A.D("weekendTint",B.a9,"weekBoxes and dayAgenda month: Saturday + Sunday take the weekend tint (lavender, or the app palette's weekend colours).",B.l,null,!1)
B.di1=s(["classic","accent"],t.s)
B.i5n=new A.D("todayStyle",B.bG,'weekBoxes and dayAgenda month: "accent" = today in the accent border with a peach header/fill (default: the classic highlight).',B.di1,null,!1)
B.i5S=new A.D("selectable",B.a9,"weekBoxes (needs settingKey): tapping a box's empty space writes its day to settingKey and marks it \"Adding here\" (unless it is today); replaces addAction's add line. The header still fires dayAction.",B.l,null,!1)
B.hGl=new A.D("undatedBox",B.W,'weekBoxes: true or {label?, hideDone? (default true)} \u2014 one more box, "To do \xb7 no day yet", listing the filtered rows with no date.',B.l,null,!1)
B.hE7=new A.D("gridColumns",B.aS,"weekBoxes: columns from gridMinWidth (default 2); rows share a bounded height (4 = a 4\xd72 week with undatedBox).",B.l,null,!1)
B.hVx=new A.D("gridMinWidth",B.aS,"weekBoxes: width from which gridColumns applies (default 840).",B.l,null,!1)
B.dv0=s(["plain","boxed"],t.s)
B.hVy=new A.D("cellStyle",B.bG,'dayAgenda month: "boxed" = every day a bordered card.',B.dv0,null,!1)
B.hPY=new A.D("dayAction",B.W,'weekBoxes: box-header tap action { fn, args } \u2014 every "$boxDate" in it becomes that box\'s yyyy-MM-dd (the weekend box: its first day), e.g. chain setSetting {key, value: "$boxDate"} then goto.',B.l,null,!1)
B.i1W=new A.D("openValue",B.Q,"weekBoxes: with doneValue, the doneColumn value written when un-checking a text-valued done column (weekBoxes reads doneValue as the doneColumn value meaning done; default boolean true/false).",B.l,null,!1)
B.i72=new A.D("dayAgenda",B.a9,"Opt-in month + selected-day agenda: tapping a day shows that day's items (time, kind accent, optional check-off) in the same node \u2014 beside the month on wide screens, under a compact dot-density month on phones. Dates come from dateColumns, else dateColumn. Absent: the classic month grid, unchanged.",B.l,null,!1)
B.i0D=new A.D("timeColumn",B.L,'dayAgenda: an "HH:mm" (rules.time) column; rows sort by it within a day (no time = all day, listed first) and show it in app.clock style.',B.l,null,!1)
B.i3O=new A.D("doneColumn",B.L,"dayAgenda: a boolean column; agenda rows show a checkbox that writes it directly (gated by doneWhen).",B.l,null,!1)
B.hTs=new A.D("doneWhen",B.W,"dayAgenda: { column, value|in } (filter shape) limiting which rows get the checkbox, e.g. only to-dos. Absent: every row.",B.l,null,!1)
B.aaS=new A.D("repeat",B.W,"Opt-in repeating tasks (ndrepeat-1114): { column?, dateColumn?, untilColumn?, fromColumn?, doneColumn?, clear?: [columns] }. Ticking a row with a repeat rule done adds its next occurrence (a fresh open copy on the next rule day, not before today, with clear emptied) once, never past untilColumn (inclusive).",B.l,null,!1)
B.i5o=new A.D("carry",B.W,"Opt-in carry-through (carry-1108): { startColumn?, doneColumn?, doneAtColumn?, skipIf?: [columns], filter?, label? } or true. An undone row with a start date shows on every day from it on; once done, from start to the doneAt day (no doneAt: the start day only). A set skipIf column (e.g. a time, a repeat) or a row outside filter keeps its own day. weekBoxes: the row is in every box of its span with a span line. dayAgenda month: a span bar per week row (open: solid to today, dashed after); the day agenda lists it.",B.l,null,!1)
B.aaR=new A.D("doneAtColumn",B.L,"Optional (carry-1108): the done toggle also writes this column \u2014 now (UTC ISO-8601) when ticked, cleared when unticked. Default: carry.doneAtColumn.",B.l,null,!1)
B.hGJ=new A.D("subtasks",B.W,"Opt-in subtasks (ndnotes-1109): true or { parentColumn? (default parentId), titleColumn?, doneColumn?, orderColumn?, values?: {\u2026written on each new subtask}, promoteValues?: {\u2026written when reparent makes one top-level}, parentFilter? }. A subtask is a row of the same table whose parentColumn names a live row passing parentFilter, or a subtask itself (ndfix-1110: nesting is unlimited; done/total counts direct subtasks). maxLevels? (njround4-1121): cap a tree at N levels counting the top task; deeper adds/drops are refused.  weekBoxes: subtasks are not listed; a parent shows done/total.",B.l,null,!1)
B.hNu=new A.D("kindColumn",B.L,"dayAgenda: column whose value picks the row's accent via kindColors.",B.l,null,!1)
B.i35=new A.D("kindColors",B.W,"dayAgenda: map of kindColumn value \u2192 color (ramp name or #hex) for day dots and agenda accents.",B.l,null,!1)
B.hQV=new A.D("filter",B.W,"Static pre-filter { column, value|in } \u2014 OR a LIST of such maps, ANDed (same shape as `cards`' filter) \u2014 narrows the source rows before placing them on the grid, e.g. keeping a shared table's member/comment rows off the calendar, or combining a kind gate with a board scope.",B.l,null,!1)
