B.hDS=new A.D("subtitleColumns",B.kT,"Columns shown as subtitle.",B.l,null,!1)
B.i6z=new A.D("action",B.W,"Alias for `onTap` (row-tap action spec { fn, args }); either name works \u2014 the shared action dispatch reads `action` first.",B.l,null,!1)
