B.i3Z=new A.D("hideDefaultComposeChips",B.a9,'dispshared-1125: the composer "as <author>" and "to: <recipient>" chips are bare icons while at their default (the picker stays). Default false.',B.l,null,!1)
B.i0f=new A.D("authorPicker",B.a9,'Opt-in: the composer shows an "as <name> \u25be" chip to attribute the next entry to any authorTable row (the user\u2194collaborator turn). The choice is sticky and always resolves to a real row.',B.l,null,!1)
B.hEu=new A.D("defaultAuthor",B.Q,'Row id (or a value token \u2014 `$setting:<key>` etc., resolved via the shared resolveValueToken) used as the author when the signed-in user is not itself an authorTable row (else the first authorFilter-matching row). Keeps the "by <name>" line from ever rendering blank.',B.l,null,!1)
B.hQF=new A.D("authorFilter",B.W,'Static { column, value|in } narrowing which authorTable rows can be attributed: the "as \u25be" picker only offers matching rows, and the first-row fallback only draws from them. When configured with NO matching rows, attribution resolves to EMPTY (renders the unattributed state) rather than any arbitrary row. Omitted (default): every authorTable row is eligible, exact prior behavior.',B.l,null,!1)
B.i3B=new A.D("promptingColumn",B.L,"Ref column that records WHO a composed entry is directed at (the turn-taking recipient); written as a one-element list.",B.l,null,!1)
B.i_9=new A.D("promptingPicker",B.a9,'Opt-in: the composer shows a "to: <name> \u25be" chip to address the next entry to a recipient from authorTable ("Anyone" = no target).',B.l,null,!1)
B.i4Z=new A.D("awaitingColumn",B.L,"Boolean column set true when a composed entry is directed at someone \u2014 opens the turn so the recipient sees it as pending until answered.",B.l,null,!1)
B.i4w=new A.D("editedByColumn",B.L,"Opt-in: editing a comment/title INLINE stamps this ref column with the current user (+ editedAtColumn=today) \u2014 the inline counterpart of the record editor's edit stamping.",B.l,null,!1)
