B.i6d=new A.D("parentEditedAtColumn",B.L,'Opt-in: posting a new entry (Add entry / attach / reply) stamps this date column on the THREAD\'S OWN node (nodeId, a row of `table`) with now \u2014 activity counts as an edit, so a task with fresh discussion but no direct field edit still surfaces in "edited recently" filters/sort. No-op unless declared (backward compatible).',B.l,null,!1)
B.hRS=new A.D("attachInline",B.a9,"Show + add attachments right on each card (thumbnails for images, chips for files, an Attach button in editable mode).",B.l,null,!1)
