B.hEQ=new A.D("titleless",B.a9,"Entries are COMMENTS: no title field \u2014 the comment is the card's primary text, the author/time line heads it, and the composer writes the comment column. The composer gains a paperclip for attachment-only entries (when attachInline).",B.l,null,!1)
B.hV8=new A.D("timeColumn",B.L,'ISO-8601 text column stamped on new entries and shown as a relative "\xb7 2h ago" beside the author.',B.l,null,!1)
B.i73=new A.D("createTypes",B.W,'Tool types creatable from the log (e.g. ["wireframe","sketchpad"]): the composer gains a "+ tool" menu (new typed entry) and a plain note\'s \u22ee menu gains "Add <tool> here" (sets its type once).',B.l,null,!1)
B.hIT=new A.D("surface",B.a9,"Wrap the log in a tinted rounded AREA (cards go white with borders) so it reads as its own region apart from the detail header.",B.l,null,!1)
