B.hE0=new A.D("roots",B.a9,"Whole-graph mode: the top level is EVERY idea that nothing flows into (each chain root plus every loose / disconnected idea) instead of one anchored thread, so no `id` is needed. Pair with `nested` to expand each root into its full sub-chain \u2014 a readable outline of the entire graph.",B.l,null,!1)
B.i0d=new A.D("nested",B.a9,"Every entry is a thread of its own: its contains-children render as nested sub-entry cards (recursive, cycle-safe) and each card gains a Reply affordance. In this mode a card's \"Attach\u2026\" menu creates a CHILD of the picked tool type (the entry stays a comment) instead of converting the entry's own type.",B.l,null,!1)
B.i19=new A.D("parentColumn",B.L,"Physical containment column on the ROWS table: a row whose parent column points at another renders as its CHILD (and never as a root), alongside edge children \u2014 so an idea nested inside a bubble reads as nested in the outline. Absent \u2192 edges only.",B.l,null,!1)
B.hWW=new A.D("anyEdgeType",B.a9,"Treat EVERY edge as a containment edge, ignoring edgeType/containsType. For graphs whose edges are all one relation, and for data whose edges were saved without a type (older data / links drawn on a canvas) \u2014 otherwise the type filter rejects them and the tree renders flat. Default off (type-filtered); new edges are still stamped with containsType.",B.l,null,!1)
B.hZR=new A.D("rootFilter",B.W,'ideasgraft-1026, `roots` mode: which rows may LEAD the outline, in the shared `filter` grammar (e.g. {"column":"inbox","empty":true} keeps unfiled captures out of the top level). Only the root candidates are filtered \u2014 a filtered row still nests under its parents. Absent = every root, unchanged.',B.l,null,!1)
B.dxa=s(["section","only"],t.s)
B.i4c=new A.D("ownAttachments",B.Q,'Opt-in (dufb-1017): "section" pulls the node\'s OWN attachmentTypes children (files on the task/project itself) out of the comment stream into a labelled section above it; "only" renders just that section (e.g. a project overview files block). Comment attachments stay inside their comments.',B.dxa,null,!1)
B.i1T=new A.D("ownAttachmentsLabel",B.Q,'Header for the ownAttachments section (default "Attached here").',B.l,null,!0)
B.hO4=new A.D("ownAttachmentsEmpty",B.Q,'Empty line for ownAttachments "only" mode.',B.l,null,!0)
B.hNw=new A.D("attachmentTypes",B.W,'Child `type` values treated as attachment OBJECTS (e.g. ["image","wireframe","sheets","docs","sketchpad"]). At the LOG level each renders as a proper ENTRY CARD housing its object (author line + tile/inline editor) in stream order \u2014 never a loose tile on the log surface; INSIDE a comment they render as tiles on that entry. Tap opens FULL-SCREEN (back returns to the log).',B.l,null,!1)
B.hMg=new A.D("excludeTypes",B.W,"Child `type` values the thread never shows (they belong to another surface \u2014 e.g. sub-tasks listed in a rail tree).",B.l,null,!1)
B.hRv=new A.D("collapseToggle",B.a9,"Show a log-header toggle that collapses/expands EVERYTHING at once: comments clamp to one line, attachment previews fold to chips. Per-attachment minimize/show picks reset when toggled.",B.l,null,!1)
B.hGq=new A.D("attachmentsStartMinimized",B.a9,"Inline-editable attachment previews start as compact CHIPS; tap a chip (or its menu) to open the live preview.",B.l,null,!1)
B.hMJ=new A.D("composeCard",B.a9,'Compose AS a card: "Add entry" (and Reply, in nested mode) creates the entry immediately and opens it as an editable card \u2014 title (optional) + comment + Attach \u2014 instead of a one-line composer bar.',B.l,null,!1)
B.i_E=new A.D("addEntryLabel",B.Q,'Label for the compose-card add button (default "Add entry").',B.l,null,!1)
B.hWK=new A.D("searchable",B.a9,"Show a search box above the log that filters entries by comment text + author name. A match keeps its ancestors so nested replies are not orphaned; empty query shows everything.",B.l,null,!1)
B.hG3=new A.D("searchHint",B.Q,'Placeholder for the search box (default "Search\u2026").',B.l,null,!1)
B.hYT=new A.D("searchSource",B.Q,'Where the query comes from: "app" reads the GLOBAL app-header search (board.searchQuery) and hides the in-body box, so one header search filters the log. Omit for the node\'s own in-body search box.',B.l,null,!1)
B.hQ5=new A.D("attachInlineEdit",B.a9,"Render attachment tiles whose type is in inlineEditTypes as a LIVE, bounded, EDITABLE embed (not just a tap-only tile), with an Expand-to-fullscreen control. Other attachment types stay tap-to-open tiles.",B.l,null,!1)
B.hON=new A.D("inlineEditTypes",B.W,'Attachment `type` values that get the inline editable embed when attachInlineEdit is on (default ["wireframe","docs"] \u2014 the types with a solo screen).',B.l,null,!1)
B.hRy=new A.D("typeIcons",B.W,"devflow-1012: per-attachment-kind tile icon, `{kind: iconName}` (names: smartphone, phone_iphone, devices, web_asset, dashboard, image, table_chart, description, brush, attachment). Wins over the built-in icon for that kind; unknown names/kinds fall back to the built-in or generic attachment glyph.",B.l,null,!1)
B.i27=new A.D("typeLabels",B.W,'devflow-1012: per-attachment-kind display name, `{kind: label}`, used on tiles and in the "New <label>" menus. Wins over the built-in friendly name; absent = built-in name, else the raw kind.',B.l,null,!1)
B.hEo=new A.D("logEntryColumn",B.L,"projdash-0810 fix-forward: opt-in boolean column stamped `true` on every entry this node CREATES (the compose/reply path) \u2014 marks it as log chatter rather than a first-class project item, so a host explorer node's matching `overviewLogColumn` can exclude it from the per-project Overview dashboard's counts. Pair the two props with the SAME column name. Unset (default) is a no-op: entries are written exactly as before this prop existed.",B.l,null,!1)
B.cSd=s([B.IF,B.hRZ,B.hVP,B.hIc,B.b3Y,B.b49,B.b4F,B.i_z,B.hFz,B.hTu,B.hId,B.i0n,B.hOu,B.hJz,B.hRh,B.hS6,B.hEk,B.hWX,B.hUr,B.hLt,B.hPg,B.hFp,B.hOi,B.hLS,B.hKj,B.hQB,B.hRk,B.i_g,B.hWV,B.i3Z,B.i0f,B.hEu,B.hQF,B.i3B,B.i_9,B.i4Z,B.i4w,B.hL0,B.i6d,B.hRS,B.hJa,B.hEQ,B.hV8,B.i73,B.hIT,B.i_J,B.hE0,B.i0d,B.i19,B.hWW,B.hZR,B.i4c,B.i1T,B.hO4,B.hNw,B.hMg,B.hRv,B.hGq,B.hMJ,B.i_E,B.hWK,B.hG3,B.hYT,B.hQ5,B.hON,B.hRy,B.i27,B.hEo],t.G)
B.hca=new A.dp("entrythread","A thread-forward view of one node's CONTAINS-children (resolved via an edges table): each child renders as a readable card (title + comment + type chip), tap to open. Pair with a bindRow detail so `rowId` is the selected node.",B.cSd,!1)
B.hJN=new A.D("excludeArchived",B.a9,'dufb17a-0924: drop rows hidden by the ARCHIVE lifecycle (rows whose incoming edges are all type "archived", plus their contains-subtrees), read via the scope* edge keys. Scoped views already never reach them; this covers whole-table use. Absent/false = unchanged.',B.l,null,!1)
B.hM3=new A.D("title",B.L,"Column shown as each card title.",B.l,null,!1)
B.hEb=new A.D("subtitle",B.L,'Column shown as a muted subtitle. Also honored by `density:"row"` (wikipick-acceptfix-0831): set, the row tile grows from one line (44-52px) to two (58-68px) to fit it, ellipsized to one line; absent (default), the row stays exactly the single-line tile it always was.',B.l,null,!1)
B.hGb=new A.D("groupBy",B.L,"Group cards into sections by column.",B.l,null,!1)
B.hLp=new A.D("groupFilter",B.W,'Restrict group HEADERS when grouping by a reference column: { column, value } \u2014 only referenced rows whose column==value become group sections (e.g. group tasks only by project-kind units: {"column":"kind","value":"project"}).',B.l,null,!1)
B.hMF=new A.D("valueLabels",B.W,"Opt-in raw-value \u2192 display map for rendered DATA VALUES (group section headers, tag pills, subtitle, expandFields values): {raw: text-or-{lang:text}} or column-keyed {column: {raw: ...}}, resolved against the ambient locale; unmapped values render exactly as before (passthrough, never blank). Display-only \u2014 stored values, groupOrder matching and tag `colors` keys stay RAW.",B.l,null,!1)
B.a5s=s(["board"],t.s)
B.hEW=new A.D("configSource",B.bG,"Subscribe to the BOARD shared data config: \"board\" applies the dataset's shared filters/sort (data_config.dart) before this node's own grouping/search/filter/sort refinements \u2014 the same opt-in used by `map`/`report`, so a cards view can share filters with a sibling view of the same table (e.g. a map\u21c4cards toggle).",B.a5s,null,!1)
B.hZZ=new A.D("filterableColumns",B.kT,"Curated allowlist of columns offered in the Filter & sort panel (filter fields, sort dropdown, group-by dropdown). Unset = every schema column (except id), unchanged. Set this to hide implementation-detail columns (raw lat/lon, derived sort keys) from the user-facing filter UI.",B.l,null,!1)
B.dxy=s(["spine","flow"],t.s)
B.hR5=new A.D("layout",B.bG,'archhome-0912: opt-in NARRATIVE layout for a view whose order is the point, so a designed structure need not degrade into a generic card list. "spine" draws a vertical time spine \u2014 a hairline rail down the left with one dot per card, and the `spineLabel` value printed ONCE in mono above each consecutive run of cards sharing it (day-group headers). "flow" stacks the cards as stages with a short connector line BETWEEN consecutive cards, read per-row from `connectorColumn` (or the static `connector` string); the connector describes what happens after THIS card, so the last card never draws one. Both force one column at every width and own their own vertical spacing. Presentation only \u2014 same tiles, taps and data; unset (default) or an unrecognised value renders exactly the classic grid.',B.dxy,null,!1)
B.i3H=new A.D("spineLabel",B.L,'With `layout: "spine"`: the column whose value is the mono day-group marker above each run of cards sharing it (e.g. a "2026-09-12" or "Today" stamp). Unset draws the rail and dots with no markers.',B.l,null,!1)
B.hHc=new A.D("connectorColumn",B.L,'With `layout: "flow"`: the column holding the connector text drawn BELOW each card (what happens next, e.g. "lands after tests pass"). Empty on a row draws plain spacing, never an empty band.',B.l,null,!1)
B.hWS=new A.D("connector",B.Q,'With `layout: "flow"`: a static connector string used when `connectorColumn` is unset or empty for a row (e.g. "\u2193").',B.l,null,!1)
B.hEG=new A.D("monoColumns",B.kT,"Columns whose rendered value is a STAMP (a build id, a version, a time code), not prose: those values render with a monospace fallback family and tabular figures so a column of them lines up. Applies to the card/row subtitle today. Unset (default) changes nothing.",B.l,null,!1)
B.hSD=new A.D("phoneColumns",B.aS,'Number of columns to keep at PHONE width (default 1, clamped 1-3) \u2014 the only opt-out from the one-column-on-phone rule, for a genuinely matrix-shaped view where one column per cell would lose the comparison (e.g. a dev|prod pair per component, grouped by component). Ignored by `layout: "spine"`/`"flow"`, which are single-column by definition, and no effect above phone width.',B.l,null,!1)
B.hLL=new A.D("masonry",B.a9,"Lay cards out as a staggered masonry wall (variable-height tiles in independent columns) instead of the uniform grid. Off by default.",B.l,null,!1)
B.i3y=new A.D("minCardWidth",B.aS,"Target minimum card width in px driving the column count (default 280, clamped 160-640); the grid packs more cards as the board widens rather than stretching a few very wide. Phones stay one column regardless.",B.l,null,!1)
B.hTi=new A.D("search",B.a9,"Show a search box at the top.",B.l,null,!1)
B.hTd=new A.D("typeToSearch",B.a9,"Desktop/web: start typing on the idle view to begin a search without clicking the box first (needs search:true). Inert on touch.",B.l,null,!1)
B.i_j=new A.D("searchColumns",B.kT,"Columns the search matches.",B.l,null,!1)
B.i1y=new A.D("searchSource",B.Q,'Set "app" to read the GLOBAL app-header search (board.searchQuery) instead of an in-body box, so the header search filters these cards. The in-body search field is then hidden.',B.l,null,!1)
B.hFH=new A.D("sortBy",B.L,"Column to sort cards by.",B.l,null,!1)
B.hJh=new A.D("sort",B.W,"Static sort applied before grouping { column, dir: asc|desc } \u2014 an alternative to sortBy/sortDir when the sort must run pre-grouping.",B.l,null,!1)
B.hWs=new A.D("starColumn",B.L,"Generic star: each card's title gets a trailing tap-to-toggle star icon bound to this boolean column; starred cards sort ahead of unstarred ones within whatever sort/grouping is already in effect.",B.l,null,!1)
B.i1w=new A.D("filter",B.W,'Static pre-filter { column, value|in }. `value` and each `in` element resolve live tokens ($rowId/$playerId/$selected:<table>/$setting:<key>/today/now/uuid) at evaluation time \u2014 e.g. {column: "board", value: "$setting:tasklyCurrentBoard"}. An unresolved token fails OPEN (behaves as unfiltered), not closed \u2014 the opposite of scopeRowId\'s empty-set contract. MAY ALSO be a LIST of such maps, ANDed \u2014 e.g. [{column: "kind", in: ["task","event"]}, {column: "board", value: "$setting:tasklyCurrentBoard"}] \u2014 for a view that needs two constraints at once (each element gets the full per-constraint treatment above, narrowing progressively). Empty list = no constraint.',B.l,null,!1)
B.hKR=new A.D("groupByOptions",B.W,"Offer a group-by picker: List of { label, column }; the user chooses which grouping is live (overrides the static groupBy).",B.l,null,!1)
B.hQq=new A.D("tableView",B.a9,'The "view as table" toolbar affordance (exportable table sheet) is on by default for every cards node; set false to opt out.',B.l,null,!1)
B.hLM=new A.D("tableColumns",B.W,'Opt-in (disppage-1125), with density "row": the rows become a table that uses the width - one column per entry {column?, label, width (px, default 100), kind?}; kind "tags" shows the first tag pill, kind "progress" a mini done/total bar over the row\'s descendants (statusColumn, doneValue, typeColumn, excludeTypes, color) for rows that contain others; otherwise the column\'s value. The name takes the rest of the width and wraps (nothing is cut); when the name would get under 200 px the facts wrap on a line under it. One header row with the labels. Absent = the row tile.',B.l,null,!1)
B.hMd=new A.D("tableNameLabel",B.Q,"With tableColumns: the header label over the name column.",B.l,null,!0)
B.hF7=new A.D("insideCount",B.a9,'With tableColumns: the name gains "N inside" (direct children over the scope edges) for rows that contain others.',B.l,null,!1)
B.hU5=new A.D("toolbarActions",B.W,'Extra icon buttons rendered INSIDE the same top search/filter/view-as-table toolbar row \u2014 List of { icon, tooltip, action, position? }, each firing its `action` (same dispatch as any other button) with no row context. Lets an applet add e.g. a "+" new-row button to the toolbar instead of a separate button row above the cards. Each item defaults to LEADING (before the search box \u2014 "[+] [search] [filter] [view]"); set `"position": "trailing"` to place it at the very right instead, after filter/view \u2014 "[search] [filter] [view] [+]". Default empty: no change to any existing applet.',B.l,null,!1)
B.hJb=new A.D("recent",B.aS,'With `collapsible`: show only the first N cards of a section behind a "show all" toggle.',B.l,null,!1)
B.hRr=new A.D("open",B.W,'Label (or {lang: text} map) for an explicit "open" button on each card; absent shows no such button.',B.l,null,!1)
B.hUt=new A.D("pulse",B.W,'Breathing highlight for "under work" rows { column, value|values }.',B.l,null,!1)
B.hVv=new A.D("tags",B.W,'Colored pill specs (List of { column, colors }). A NUMERIC column may instead use { column, positiveColor, negativeColor, prefix, suffix } to render a +/- threshold pill (e.g. "+5" green, "-3.4%" red).',B.l,null,!1)
B.hR7=new A.D("imageColumn",B.L,"Column holding a base64 data-uri or image url \u2014 shown as a ~48px rounded leading thumbnail on each card.",B.l,null,!1)
B.i52=new A.D("badge",B.W,"Opt-in person badge (ndtags-1109): { typeColumn, value, nameColumn?, colorColumn? } \u2014 a row whose typeColumn equals value leads with a round initials badge (first letters of up to two words of nameColumn/title, coloured by colorColumn). Local labels only.",B.l,null,!1)
B.i08=new A.D("iconColumn",B.L,"Column holding an icon name or a leading emoji \u2014 shown as a leading accent chip on each card.",B.l,null,!1)
B.hIJ=new A.D("accentColumn",B.L,"Column whose value maps (via accentColors) to a colored left stripe.",B.l,null,!1)
B.i5X=new A.D("accentColors",B.W,"Map of accentColumn value \u2192 ramp name (teal/coral/...) or #hex for the left stripe.",B.l,null,!1)
B.hJt=new A.D("splitBar",B.W,'wikipick-picture-b2-0831: a slim (4px) two-segment bar rendered under the subtitle on THIS row \u2014 {partColumn, totalColumn, color?, label?}. Reads `partColumn`/`totalColumn` off the row as numbers; the filled segment (partColumn/totalColumn, `color` ramp, default "blue") represents the part, the remainder is a muted outline tint. An optional `label` ({lang: text} map, e.g. "shared") renders after a trailing "part/total" digit pair, same dense-stat convention as the rest of the engine (numbers from data, words from a static localized map \u2014 never mix untranslated words into stored data). Zero/absent totalColumn draws nothing (no divide-by-zero sliver). Fills the one visual gap cards had for a per-row progress/proportion bar (a rollup `progress` node is table-wide, not per-row) \u2014 e.g. a per-seed crawl-progress bar or a per-seed shared-vs-exclusive article split.',B.l,null,!1)
B.i7a=new A.D("emptyIcon",B.Q,"Icon name shown on the empty-state panel when the table has no rows.",B.l,null,!1)
B.hNc=new A.D("emptyTitle",B.Q,"Headline shown on the empty-state panel when the table has no rows; may be a {lang: text} map.",B.l,null,!0)
B.hZc=new A.D("emptyText",B.Q,"Supporting line shown on the empty-state panel; may be a {lang: text} map.",B.l,null,!0)
B.hZ6=new A.D("emptyAction",B.W,"Optional empty-state button action spec { fn, args, label }. cards' own convention carries the label inline on this map; the shared `emptyActionLabel`/`emptyActionIcon` props (used by list/tree/agenda) are also honored here and WIN when set, so either authoring style works and both may be set without conflict.",B.l,null,!1)
B.hUe=new A.D("emptyActionLabel",B.Q,"Shared empty-state action-button label (same prop list/tree/agenda use). Overrides emptyAction.label when both are set. May be a {lang: text} map.",B.l,null,!0)
B.hGP=new A.D("emptyActionIcon",B.Q,"Shared empty-state action-button icon name (same prop list/tree/agenda use). Shown on the button leading edge when set.",B.l,null,!1)
B.hHU=new A.D("collapsible",B.a9,"Collapse long sections behind a toggle.",B.l,null,!1)
B.hVW=new A.D("groupsCollapsed",B.a9,"Grouped sections start CLOSED (header only) until tapped open. Calm default for dense registries and nested module lists.",B.l,null,!1)
B.hRO=new A.D("groupDateLabels",B.a9,'Opt-in (newdays-1115): when groupBy is a DATE column, each section header reads as the locale medium date (e.g. "Thu, Nov 12") instead of yyyy-MM-dd. Display only; absent -> unchanged.',B.l,null,!1)
B.du2=s(["open","expand"],t.s)
B.hSm=new A.D("tapBehavior",B.bG,"tapopen-0830 (BINDING fleet UX standard) + house rule 7a: tapping a card ALWAYS OPENS it \u2014 a generic detail surface with the card's full content \u2014 the configured `action`/`onTap` if set, else the engine's own detail surface. tapfull-0831: on phone that surface is a PUSHED full-screen route (app bar + back), never a slide-up bottom sheet; on desktop/wide it is a full-view centered dialog (house rule 7a \u2014 the old right side-sheet is retired). Set \"expand\" (LEGACY value, kept for source compat) to also guarantee the inline expand-in-place chevron is shown (see `expandChevron`) without needing to opt into it separately \u2014 the body tap itself still OPENS either way; expand-in-place is reachable ONLY via the chevron icon, never the body (house rule 7a: one tap, one outcome).",B.du2,null,!1)
B.hQb=new A.D("expandable",B.a9,"Whether this card can expand inline at all (default true). Set false for a card with nothing to expand \u2014 no chevron renders.",B.l,null,!1)
B.hQl=new A.D("expandSingle",B.a9,'LEGACY (`tapBehavior: "expand"` only): opening a card collapses its siblings \u2014 at most one card expanded at a time (a card mid-edit keeps its editor).',B.l,null,!1)
B.i0e=new A.D("expandChevron",B.a9,'Shows the expand affordance as an explicit trailing chevron icon (44px hit box) under the default `tapBehavior: "open"` \u2014 the body tap opens the item; only the chevron toggles the inline `expandFields` preview. Under `tapBehavior: "expand"` the chevron is ALWAYS shown (this prop is a no-op there, since expand-in-place has no other affordance once the body tap opens) \u2014 house rule 7a: the card body tap always opens, expand is reachable only via an explicit icon.',B.l,null,!1)
B.aaM=new A.D("height",B.aS,"Optional fixed height.",B.l,null,!1)
B.du5=s(["outlined","elevated","flat","feature"],t.s)
B.hXg=new A.D("variant",B.bG,"Card treatment (defaults to the style): outlined, elevated, flat, feature.",B.du5,null,!1)
B.hMa=new A.D("action",B.W,"Open-record action spec { fn, args }.",B.l,null,!1)
B.hQa=new A.D("cardActions",B.W,"ALWAYS-VISIBLE per-row icon button(s) in the card's title row \u2014 no swipe, no long-press, no expand needed (unlike `swipeActions`, reveal-on-gesture only, or `openActions`, expanded-card only). List of { icon, label, action, column?, equals?, notEquals? }: with `column` set, the button is gated against THIS row's own value (shown only when it equals/notEquals the given value); omitted `column` = always shown. `label` may be a {lang: text} map and is used as the button's tooltip. Each fires its `action` spec on the row through the normal dispatch (chains included). Use for a discoverable \"add without opening\" affordance on a live list, e.g. a search-results card whose row tap reads the item but whose `cardActions` entry saves it \u2014 gated `notEquals` the row's own \"already saved\" flag so a saved row shows its state instead.",B.l,null,!1)
B.i4J=new A.D("longPressActions",B.W,"Press-and-hold action menu \u2014 same entry shape/gating as `cardActions` (List of { icon, label, action, column?, equals?, notEquals? }). When present (non-empty), it REPLACES the engine's built-in Open/Edit/Delete long-press menu for this node; absent, long-press keeps showing that built-in menu. Either way the popup opens as an anchored contextual dropdown AT the touch point (longpress-anchored-0831), never a slide-up sheet.",B.l,null,!1)
B.i4U=new A.D("rowMenuExtras",B.W,"Same gated entry shape as `cardActions`/`longPressActions` (List of { icon, label, action, column?, equals?, notEquals?, destructive? }), but APPENDS to the engine's built-in Open/Edit/Delete long-press menu (between Open and Edit) instead of replacing it \u2014 use this when a node wants ONE more contextual action alongside the built-in menu rather than a full custom replacement (rowmenu-extras-0903). An entry with `destructive: true` (e.g. a replacement Delete) renders in the theme's error color, same as the built-in Delete, and is moved to the END of the menu regardless of its position in this list \u2014 non-destructive extras stay between Open and Edit in author order, destructive ones sort after the built-in Delete (rowmenu-extras-destructive-0912).",B.l,null,!1)
B.hWH=new A.D("builtinDelete",B.a9,"Set false to suppress the engine's own row Delete everywhere it would otherwise appear \u2014 the \u22ee overflow menu, the long-press row menu, AND the default \"delete\" swipe entry, all three at once (default true, exact prior behavior when omitted). Use when the applet declares its OWN guarded delete (e.g. confirms an item count, refuses when shared) so a more-discoverable built-in Delete can't bypass it and orphan data.",B.l,null,!1)
B.hO9=new A.D("titleFromColumn",B.L,'Opt-in first-line titles (notes): the card title follows the first line of THIS column (the body) while the stored title column is empty or is itself a first-line derivation; the subtitle then skips that line. An explicit stored title is shown as-is. Display only \u2014 nothing is written. Empty notes show a localized "New note".',B.l,null,!1)
B.hKo=new A.D("titleAutoColumn",B.L,'Memo column for titleFromColumn (default "titleAuto"); keep it equal to the notepad\'s titleAutoColumn.',B.l,null,!1)
B.i_A=new A.D("expandFields",B.W,'Extra "label: value" rows shown when a card is expanded. List of { column, label?, format?: currency|percent|compact|relative|number|duration|epochSeconds|epochMillis, decimals?, prefix?, inputUnit?, style? } \u2014 `format` renders the value as a number, or (`relative`) humanizes an ISO-8601 timestamp column as "3m ago"/"2h ago"/"3d ago"; `duration` shows seconds (or `inputUnit:"millis"`) as a compact localized "3d 4h 12m" / "4h 12m" / "12m 5s" (negative \u2192 "\u2014"); `epochSeconds`/`epochMillis` show a Unix timestamp as localized device-time-zone text, `style` = date | time | dateTime (default) | relative. Non-numeric values pass through untouched.',B.l,null,!1)
B.i5V=new A.D("expandDetail",B.W,"A child node rendered INLINE when a card is expanded, with the row's id injected (and the cards `table` unless the node sets its own). Lets a row edit in place \u2014 e.g. a notepad or embed \u2014 with no popup.",B.l,null,!1)
B.hMv=new A.D("expandHeight",B.aS,"Fixed height for `expandDetail` (default 340). Set it for an embed that needs a bounded canvas.",B.l,null,!1)
B.hGm=new A.D("contentSurface",B.a9,"Render expandDetail on a clean opaque surface so the card tint can't dim an embedded widget/note (default true; set false to opt out).",B.l,null,!1)
B.hTP=new A.D("expandFit",B.a9,"Size `expandDetail` to its content instead of the 340 default \u2014 a short note stays short (the child must self-size, e.g. an autoHeight notepad or an embed with its own height).",B.l,null,!1)
B.hEB=new A.D("editToolbar",B.a9,"An expanded card opens with a compact control row \u2014 an optional `toolbarLead` node, an edit pencil (\u2713 to finish, \u2717 to cancel-and-revert) and a \u22ee options menu \u2014 and `expandDetail` opens read-only until the pencil turns edit on (the `editing` flag flows in).",B.l,null,!1)
B.hE1=new A.D("toolbarLead",B.W,"A node rendered at the LEFT of the edit toolbar, row-bound (e.g. a `pick` content-type dropdown).",B.l,null,!1)
B.hVj=new A.D("menuActions",B.W,'Extra \u22ee menu items [{ label, icon?, action }] fired with the row injected (e.g. "Add subtask"); a built-in Delete is always present.',B.l,null,!1)
B.hEC=new A.D("expandExtra",B.W,"A SECOND inline node below `expandDetail` when expanded, row-bound and content-fit (e.g. a nested cards filtered to this row's children \u2014 a subtask sub-thread, or a box's packed items). Filter it with value \"$rowId\" (the parent's internal id) or \"$parentField:<column>\" (the parent row's value for <column> \u2014 e.g. a plain-number parent key like a box's `number`, when the child table isn't a `ref`). Both tokens also resolve inside `toolbarActions[].action.args.values` (and anywhere else in this spec), so an inline \"+ add\" button can pre-fill the new child row's parent-key field.",B.l,null,!1)
B.hVi=new A.D("expandPeek",B.W,"A HOST-COMPUTED detail line shown on the EXPANDED card face: { call, tapCall? } \u2014 `call` names a host query ([HostQuery], NOT a synced column) invoked with the row when the card expands; its returned text renders in muted secondary styling below the other expanded content, hidden while pending and hidden entirely when the result is null/empty. Optional `tapCall` names a second host query fired with the row when the line itself is tapped (e.g. open a detail page) \u2014 omit it for a non-tappable line. For read-only, per-viewer, or otherwise host-owned lookup data that must never be written into the board's synced tables (a dictionary lookup, a live status ping, \u2026); the engine never caches the result beyond the card staying expanded. Malformed/absent config renders nothing, byte-identical to before this prop existed.",B.l,null,!1)
B.i4i=new A.D("hideWhenEmpty",B.a9,"Render nothing (no empty notice) when there are no cards \u2014 for a nested sub-thread that should stay invisible until it has rows.",B.l,null,!1)
B.i2u=new A.D("autoEditNew",B.a9,"Auto-open a freshly-added row expanded + in edit mode when a host flags it via board.settings[_autoEditRow] (e.g. add-to-thread drops a new empty card already editing). Gated to the row author.",B.l,null,!1)
B.hZ8=new A.D("addCard",B.W,'A tappable "add" card ({ label, icon?, action }) AFTER the last item, firing its action with no row \u2014 an inline add affordance that scrolls with the list. With an addCard the empty state is just the add card.',B.l,null,!1)
B.hU7=new A.D("openIcon",B.Q,"Under `editToolbar`, the row `open`/action surfaces as this top-right toolbar icon (default open_in_full) instead of a bottom button; the `open` label becomes its tooltip.",B.l,null,!1)
B.hRx=new A.D("openActions",B.W,'Extra buttons beside the `open` button on an expanded card, each { label, icon?, action } fired with the row injected (e.g. "Show on map" \u2192 focusRow chained with goto). Ignored under `editToolbar`.',B.l,null,!1)
B.dhN=s(["card","row"],t.s)
B.hN1=new A.D("density",B.bG,'Card treatment density. "card" (default) is the classic multi-line card; "row" renders a compact single-line tile (~44-52px): leading checkbox/dot/icon, title, up to 2 trailing tag chips, whole-row tap.',B.dhN,null,!1)
B.hKi=new A.D("sectionLabel",B.Q,"An eyebrow header owned by this node, rendered ABOVE its cards \u2014 but ONLY while the list actually has rows right now (reactive: reads the same live row set the node already recomputes). Lets a category caption disappear along with its list instead of sitting over an empty panel (design-real-estate-efficiency \u2014 wikipick-0830ui); may be a {lang: text} map.",B.l,null,!0)
B.i4F=new A.D("combineEmptyAlsoEmptyTable",B.b4,"Opt-in gate so two sibling `cards` nodes on one screen can share ONE combined empty panel instead of each showing its own: this node's authored empty* props render ONLY when this table is empty AND the named sibling table is ALSO currently empty; when the sibling still has rows, this node renders nothing at all (design-real-estate-efficiency \u2014 wikipick-0830ui).",B.l,null,!1)
B.i6T=new A.D("dotColumn",B.L,"Column whose value maps (via `colors`) to a small leading color dot \u2014 works in both `density` modes. Falls back to `imageColumn`/`iconColumn` when those are also set (dot is the lowest-priority leading affordance).",B.l,null,!1)
B.i4M=new A.D("toggle",B.a9,"Row density only: show a tappable checkbox as the leading affordance instead of the image/icon/dot, wired to `statusColumn`/`doneValue`/`openValue` (same toggleField convention agenda/tree/list use).",B.l,null,!1)
B.i_a=new A.D("statusColumn",B.L,'With `toggle`: the column read/written by the leading checkbox (default "status").',B.l,null,!1)
B.hQY=new A.D("doneValue",B.Q,'With `toggle`: the stored value meaning "done"/checked (default "done").',B.l,null,!1)
B.i14=new A.D("openValue",B.Q,'With `toggle`: the stored value meaning "open"/unchecked (default "todo").',B.l,null,!1)
B.i_p=new A.D("scopeRowId",B.Q,"OPT-IN subtree scope (rehome-0804, mirrors `priolanes`' `scopeRowId`): a literal row id or a `$`-token (`$rowId`, `$selected:<table>`). Unconfigured (absent) leaves the card population byte-identical. Configured but UNRESOLVED (e.g. a `$selected:` token with nothing selected) fails CLOSED to the empty set \u2014 never falls back to the whole board. Configured + resolved keeps only rows reachable walking `scopeEdgesTable` DOWNWARD (contains edges) from the resolved row id; the root row itself is included.",B.l,null,!1)
B.CG=new A.D("scopeEdgesTable",B.b4,'With `scopeRowId`: the edges table to walk (default "relations").',B.l,null,!1)
B.hWu=new A.D("scopeEdgeFrom",B.L,'With `scopeRowId`: the edge\'s parent-id column (default "from" \u2014 matches `priolanes`\' own default; set explicitly when the edges table uses different column names, e.g. "fromId").',B.l,null,!1)
B.CE=new A.D("scopeEdgeTo",B.L,'With `scopeRowId`: the edge\'s child-id column (default "to").',B.l,null,!1)
B.CD=new A.D("scopeEdgeType",B.L,'With `scopeRowId`: the edge-kind column checked against `scopeContainsType` (default "type").',B.l,null,!1)
B.CF=new A.D("scopeContainsType",B.Q,'With `scopeRowId`: the edge-kind value meaning "contains" (default "contains").',B.l,null,!1)
B.i2U=new A.D("scopeDepth",B.aS,'With `scopeRowId` (dispfb-1018): `1` narrows the scope to the root\'s DIRECT children only, root excluded \u2014 a one-level "contents of this folder" list. Absent = the default whole-subtree, root-inclusive scope (byte-identical to before).',B.l,null,!1)
B.i21=new A.D("limit",B.aS,'dispusab-0804: opt-in TOP-N cap \u2014 render at most N cards, applied AFTER scope, filter, live search/column filters and sort, so `limit: 3` means "the top 3 of what this view would have shown". The PREVIEW idiom: a compact strip on an overview screen beside a button that opens the full view. Unset / <= 0 renders every row (byte-identical to before); a limit larger than the row count is a no-op.',B.l,null,!1)
B.hZS=new A.D("tag",B.W,"A SINGLE tag chip spec { column, colors?, positiveColor?, negativeColor?, prefix?, suffix? } \u2014 the singular form of `tags`, appended to whatever `tags` already declares.",B.l,null,!1)
B.hRl=new A.D("colorColumn",B.L,"Column whose value tints the card body, resolved through `colors`. Orthogonal to `accentColumn` (the left stripe) \u2014 a card may carry both.",B.l,null,!1)
B.hK3=new A.D("colors",B.W,"Map of value -> ramp name or #hex, shared by `colorColumn` (body tint) and `dotColumn` (status dot).",B.l,null,!1)
B.dw1=s([B.IF,B.yA,B.hJN,B.hM3,B.hEb,B.hGb,B.b4_,B.hLp,B.hMF,B.hEW,B.hZZ,B.hR5,B.i3H,B.hHc,B.hWS,B.hEG,B.hSD,B.hLL,B.i3y,B.hTi,B.hTd,B.i_j,B.i1y,B.hFH,B.b4r,B.hJh,B.hWs,B.aaO,B.i1w,B.hKR,B.hQq,B.hLM,B.hMd,B.hF7,B.hU5,B.hJb,B.hRr,B.hUt,B.hVv,B.hR7,B.i52,B.i08,B.hIJ,B.i5X,B.hJt,B.i7a,B.hNc,B.hZc,B.hZ6,B.hUe,B.hGP,B.hHU,B.hVW,B.hRO,B.hSm,B.hQb,B.hQl,B.i0e,B.aaM,B.hXg,B.hMa,B.b4e,B.hQa,B.i4J,B.i4U,B.UM,B.UQ,B.hWH,B.hO9,B.hKo,B.i_A,B.i5V,B.hMv,B.hGm,B.hTP,B.hEB,B.hE1,B.hVj,B.hEC,B.hVi,B.i4i,B.i2u,B.hZ8,B.hU7,B.hRx,B.hN1,B.hKi,B.i4F,B.i6T,B.i4M,B.i_a,B.hQY,B.i14,B.i_p,B.CG,B.hWu,B.CE,B.CD,B.CF,B.i2U,B.i21,B.hZS,B.hRl,B.hK3,B.UN],t.G)
B.hd2=new A.dp("cards","An elegant, expandable card view of a table's rows.",B.dw1,!1)
B.i6v=new A.D("id",B.Q,"This node's handle \u2014 used as the PageStorage key so the selected segment survives a structural rebuild (e.g. a window resize flipping the phone/desktop layout branch). An id-less segments still restores its index across such a rebuild via a fallback key derived from the segment labels, but an explicit id is more robust if segments are added/removed/relabelled.",B.l,null,!1)
B.hKm=new A.D("segments",B.W,"List of { label, child, icon?, action? } segments. An optional `action` is fired when the person switches TO that segment (never on first build).",B.l,null,!1)
B.hMi=new A.D("initial",B.aS,"Index of the segment shown before the person picks one (default 0). A remembered pick (PageStorage) still wins.",B.l,null,!1)
B.i74=new A.D("fill",B.a9,'Fill the (bounded) parent and hand the active tab the remaining height via Expanded \u2014 needed when a tab hosts a height-filling surface (a bubl board, notepad, nested explorer, or a map/table/chart asking for height:"fill"). The active tab also republishes its own bounded height, so a height:"fill" child fills the TAB exactly (not the whole body) and pans internally. As a ROOT body it also takes the exact viewport height instead of the page-scroll fallback. Default off: segments shrink-wrap and drop into a scroll view.',B.l,null,!1)
B.i4f=new A.D("chips",B.a9,"Render the header as a compact row of small icon chips instead of full FilledButton text pills. Each segment map may carry an `icon` (a nav icon-name string, same registry as tab-bar icons); without one the chip falls back to the label's first letter in a small circle. The active chip is tinted, inactive chips are faint, and the current segment's label is shown next to the strip. Default off: the classic text-pill header (byte-identical to before this key existed).",B.l,null,!1)
B.hGQ=new A.D("swipe",B.a9,"With `chips:true`, a horizontal drag ANYWHERE ON THE CHIP STRIP (never the body) advances/retreats the active segment, with an animated slide transition. Deliberately scoped to the strip \u2014 never a body-wide PageView \u2014 so a one-finger drag inside the active tab (a bubl board drag/marquee, an outline scroll, a canvas pan) is never intercepted. Default off.",B.l,null,!1)
B.i2R=new A.D("transition",B.Q,'With `swipe:true`, how the active tab\'s body animates on switch: "fade" (default) \u2014 a capped 150ms cross-fade, incoming child on top so a heavy outgoing child (a gantt, a big table) never reads as "stuck" over the new one \u2014 or "none" \u2014 an instant swap with no AnimatedSwitcher at all, for content sensitive to any transition cost. Ignored without `swipe:true`.',B.l,null,!1)
B.hMz=new A.D("scrollBody",B.a9,'The active tab\'s body scrolls INSIDE the bounded pane instead of being clipped, while the header/tab-bar stays docked above it \u2014 for a tab whose content (a list/column of rows) is naturally taller than the available slot. Implies `fill` (needs the same bounded pane); combine with a fixed screen/parent height, not with a child asking `height:"fill"` (that child would lose its bounded pane \u2014 use `fill` alone for that case). Default off: byte-identical to before this key existed.',B.l,null,!1)
B.hZO=new A.D("trailing",B.W,"Opt-in node drawn at the right end of the tab row: tabs on the left (scrolling sideways if they run out of room) and this node on the SAME row. Unset = the wrapping tab header.",B.l,null,!1)
B.i5f=new A.D("trailingPhone",B.W,"Replaces `trailing` under 600px wide (e.g. just a refresh button).",B.l,null,!1)
B.hDN=new A.D("dense",B.a9,"Compact tab strip: 2px outer inset and a 32px minimum height instead of the full M3 FilledButton size \u2014 matches a `pick` segmented control's density so the two read as one control language.",B.l,null,!1)
B.hOD=new A.D("color",B.Q,"Pin the inactive tab fill (hex) instead of inheriting the theme's DERIVED secondaryContainer, which can land on an unrelated hue.",B.l,null,!1)
B.hZx=new A.D("textColor",B.Q,"Pin the inactive tab label color (hex).",B.l,null,!1)
B.hSk=new A.D("borderColor",B.Q,"Pin an outline color (hex) on every tab.",B.l,null,!1)
B.hWe=new A.D("selectedColor",B.Q,"Pin the ACTIVE tab fill (hex).",B.l,null,!1)
B.i1H=new A.D("selectedTextColor",B.Q,"Pin the ACTIVE tab label color (hex).",B.l,null,!1)
B.i4V=new A.D("darkColor",B.Q,"Dark-mode `color` override.",B.l,null,!1)
