B.hUF=new A.D("fitOnLoad",B.a9,"Default ON: on first load, if the drawn content is not fully visible at the origin view, the camera fits it (centered, zoom \u2264 1\xd7) \u2014 a small preview shows the drawing, not an empty grid corner. Set false to keep the raw origin view.",B.l,null,!1)
