B.i_r=new A.D("edgesTable",B.b4,"Table holding the edges.",B.l,null,!1)
B.hLk=new A.D("labelColumn",B.L,"Column shown on each node.",B.l,null,!1)
B.hHZ=new A.D("xColumn",B.L,"Node x-position column (free layout).",B.l,null,!1)
B.hJE=new A.D("yColumn",B.L,"Node y-position column (free layout).",B.l,null,!1)
B.hT8=new A.D("fromColumn",B.L,"Edge source-node id column.",B.l,null,!1)
B.hGF=new A.D("toColumn",B.L,"Edge target-node id column.",B.l,null,!1)
B.hHa=new A.D("edgeLabelColumn",B.L,'Edge label column (defaults to "label" when unset) \u2014 drawn on the edge itself, distinct from `labelColumn` which labels each node.',B.l,null,!1)
B.b4n=new A.D("height",B.Q,'Canvas height. Accepts a number (logical px), "fill" (the full available body height, scrolling/panning internally), or "<frac>fill" (e.g. "0.55fill").',B.l,null,!1)
