B.i4o=new A.D("parentColumn",B.L,"Graph/dag: physical containment column on the nodes table \u2014 a nested node ranks one column right of its parent and connects with a soft DASHED (arrowless) line, distinct from the data edges.",B.l,null,!1)
B.i3p=new A.D("collapsible",B.a9,'Graph/dag (needs parentColumn): a node with nested children shows a collapse/expand toggle; collapsing hides its whole contained subtree and shows a "+N" badge (N = hidden descendants). Session-only, not persisted.',B.l,null,!1)
B.hUX=new A.D("sketchTable",B.b4,"Enable a freehand SKETCH overlay (draw/write/add text on top of the diagram). Strokes persist as JSON in this table's first row.",B.l,null,!1)
B.hRC=new A.D("sketchColumn",B.L,'Column holding the sketch strokes JSON (default "strokes").',B.l,null,!1)
B.i67=new A.D("sketchScope",B.W,"artboard-r1-1012. Optional `{column, value}`: the sketch overlay reads/writes the row of `sketchTable` whose column equals value (a fresh row is stamped with it), so one ink table holds many independent drawings. Absent = the table's first row.",B.l,null,!1)
B.hSE=new A.D("artboard",B.W,"artboard-r1-1012. Optional `{width, height, label?}`: the region at the scene origin the drawing is FOR (e.g. a phone frame), drawn as an outlined sheet behind the content and used as the first-load fit target. Absent = no sheet.",B.l,null,!1)
B.hQy=new A.D("fidelity",B.bG,'How nodes RENDER (free layout): "auto" (default tinted card), "wireframe" (mono outline + white fill), or "themed" (each `kind` drawn as a real component \u2014 button/input/list/nav/image/text/section/frame).',B.a5r,null,!1)
B.hOw=new A.D("confirmDelete",B.a9,'Ask to confirm before deleting a node (also honors the app-wide "confirm before deleting" setting).',B.l,null,!1)
B.hKJ=new A.D("pageTable",B.b4,'RENAME: table holding the current PAGE row. Set with pageId to show a tappable "rename page" chip on the canvas (for solo/embedded views).',B.l,null,!1)
B.i5U=new A.D("pageId",B.Q,"RENAME: id of the current page row (defaults to the injected `rowId`, so a canvas inside a pages/explorer detail renames the open page).",B.l,null,!1)
B.i2x=new A.D("pageNameColumn",B.L,'RENAME: page name column (default "name").',B.l,null,!1)
B.hPL=new A.D("pageRenameTitle",B.Q,'RENAME: dialog title for the page rename (default "Rename page").',B.l,null,!1)
