B.hNV=new A.D("laneColumn",B.L,"Graph/dag layout: column naming each node's swimlane (track).",B.l,null,!1)
B.hQZ=new A.D("milestoneColumn",B.L,"Graph layout: column naming each node's time-bucket (milestone).",B.l,null,!1)
B.hQL=new A.D("laneOrder",B.W,"Graph layout: explicit lane display order (List of laneColumn values).",B.l,null,!1)
B.hZJ=new A.D("milestoneOrder",B.W,"Graph layout: explicit milestone display order (List of milestoneColumn values).",B.l,null,!1)
