B.hUv=new A.D("linesToggle",B.W,'Show a routes/polyline-overlay toggle chip controlling linesAsset2 (layer 1, linesAsset, has no manual toggle \u2014 its own linesFilterProperty/selection already gates visibility). Independent of overlayToggle (polygon layer only); a String sets its label (default "Routes").',B.l,null,!1)
B.hN5=new A.D("linesAsset2",B.Q,"A SECOND, independent GeoJSON asset of LineString/MultiLineString features, drawn alongside linesAsset \u2014 lets one map combine a filtered layer (e.g. linesAsset + linesFilterProperty for a per-selection hub route tree) with an always-on one (e.g. linesAsset2 with no linesFilterProperty2, for a full network of links) at the same time, since one filter can't apply to only some features in one asset.",B.l,null,!1)
