B.hXU=new A.D("action",B.W,'Action spec { fn, args } fired on change; any literal "$value" in args (nested lists/maps included) is substituted with the current number first \u2014 e.g. drives mapSetFilter/mapSetPaint directly with zero extra plumbing.',B.l,null,!1)
B.hZP=new A.D("play",B.a9,"Opt-in auto-play/timelapse (default off): shows a play/pause button beside the slider that sweeps the value from the active range's start to its end, advancing by `step` (or 1/100th of the span when step is 0/omitted) every `playIntervalMs`, firing the SAME setting-write / action a manual change fires at every step. Pressing play restarts from the active-range start when the thumb is already at the end, otherwise continues from the current value. Any manual drag pauses playback in place (the `databars` play convention).",B.l,null,!1)
B.b4q=new A.D("playIntervalMs",B.aS,"Milliseconds between auto-play steps \u2014 default ~1200. Only used with play:true.",B.l,null,!1)
B.hK1=new A.D("playLoop",B.a9,"Whether auto-play wraps to the active-range start after reaching the end \u2014 default false (stops and flips the button back to play). Only used with play:true.",B.l,null,!1)
