B.hOk=new A.D("minuteStep",B.aS,"time mode: minute increment (default 1).",B.l,null,!1)
B.hSG=new A.D("firstDate",B.Q,"date mode: earliest date, ISO yyyy-MM-dd (default 100 years back).",B.l,null,!1)
B.hJT=new A.D("lastDate",B.Q,"date mode: latest date, ISO yyyy-MM-dd (default 100 years ahead).",B.l,null,!1)
