B.hST=new A.D("debounceMs",B.aS,"Debounce window in ms for the change-fired action (default 350). Submit always fires immediately, uncoupled from this.",B.l,null,!1)
B.i5D=new A.D("action",B.W,'Action spec { fn, args } fired on debounced change and on submit; any literal "$value" in args (nested lists/maps included) is substituted with the field\'s current text first.',B.l,null,!1)
B.i_6=new A.D("focusSignal",B.W,'{table, id, column} \u2014 a value the host BUMPS to command external keyboard focus (e.g. a magnifier "start searching" toggle). Watched every rebuild; any change from the previously seen value requests focus. Optional.',B.l,null,!1)
B.hGS=new A.D("resetSignal",B.W,"{table, id, column} \u2014 same shape as focusSignal, but a change clears the field's own visible text and fires its `action` with an empty string, so bound downstream state clears too. Optional; distinct from focusSignal so one external toggle can choose either behavior per host-side state.",B.l,null,!1)
B.i0m=new A.D("contentPadding",B.W,"{left, top, right, bottom} in px, each optional (default 12 per side \u2014 the ordinary decoration inset). Lets the field's own text inset be pulled in line with unrelated sibling content sharing its row (e.g. list-row titles below it that start flush at the row's own screen inset, with no further indent of their own).",B.l,null,!1)
B.doB=s([B.hHD,B.hST,B.i5D,B.i_6,B.hGS,B.i0m],t.G)
B.hcg=new A.dp("textinput",'A single-line free-text field \u2014 the `slider` $value-substitution pattern generalized from numeric to text. On every change (debounced) AND on submit (immediate) it can fire an `action` (any literal "$value" in args, however deeply nested, is substituted with the field\'s current text first \u2014 an empty field still fires, so a "clear" is expressible). No table binding of its own; drives whatever action the applet author wires (e.g. a debounced search-as-you-type `http` fetch).',B.doB,!1)
B.hLN=new A.D("table",B.b4,"Dataset the chips filter.",B.l,null,!1)
