B.hd0=new A.dp("datasegment","CONTROL block: one-tap VALUE CHIPS for a low-cardinality column (scenario/status switch). Multi-select; each tap toggles that value in the shared choice filter; none selected = no constraint. Hides itself when the column is not segment-shaped.",B.d_6,!1)
B.i6x=new A.D("table",B.b4,"Dataset the bars bucket.",B.l,null,!1)
