B.hcu=new A.dp("notepad",'An inline, auto-saving text editor for one row\'s text column, with a Write/Preview toggle (lightweight Markdown). The natural page editor for a page-able document \u2014 reads an injected "rowId".',B.d9F,!1)
B.hMT=new A.D("table",B.b4,"Table that receives each sent row.",B.l,null,!1)
B.hUG=new A.D("column",B.L,'Column the typed text fills (default "text").',B.l,null,!1)
B.hHH=new A.D("placeholder",B.Q,"Empty-input hint text; may be a {lang: text} map.",B.l,null,!0)
B.hW6=new A.D("values",B.W,"Columns preset on every sent row; values resolve $playerId/now/uuid.",B.l,null,!1)
B.i1A=new A.D("sendIcon",B.Q,"Send-button icon (send/arrow).",B.l,null,!1)
B.hYJ=new A.D("action",B.W,"Optional action fired on the new row (e.g. translate it).",B.l,null,!1)
B.hHF=new A.D("helperAction",B.W,'Optional "compose helper" action fired on the DRAFT still in the text field (no row created) \u2014 draftText is merged into its own args. Renders a small icon button next to send ONLY when set.',B.l,null,!1)
B.hUD=new A.D("helperIcon",B.Q,"Compose-helper button icon (translate/auto_awesome/lightbulb).",B.l,null,!1)
B.hM4=new A.D("helperTooltip",B.Q,"Compose-helper button tooltip; may be a {lang: text} map.",B.l,null,!0)
B.hJ9=new A.D("attachments",B.a9,"Opt-in pending attachments: a leading + attach button inside the text field (file/image picker, all platforms), clipboard-IMAGE paste on web and desktop only, thumbnail chips with a remove x above the input. Send commits text + all pending files as ONE row (text-less send works when files are pending). Default off.",B.l,null,!1)
B.i6l=new A.D("attachmentsColumn",B.L,'Column that receives the pending attachment list (engine inline base64 {name,mime,size,data} maps, same as entry attachments). Default "attachments".',B.l,null,!1)
B.hNY=new A.D("maxAttachBytes",B.aS,"Per-file cap in bytes for composer attachments (default: engine cap).",B.l,null,!1)
B.hNM=new A.D("pasteTable",B.a9,"Opt-in (chatx-1031), web + desktop only: Cmd/Ctrl+V of spreadsheet cells (tab-separated text and/or an HTML <table>; HTML is parsed for cell text only, never rendered) inserts a GitHub-style Markdown table at the caret (first row = header; | and newlines escaped; capped at 200 rows x 30 columns with a note row). Text without tabs and images paste as before. Default off.",B.l,null,!1)
B.hSZ=new A.D("dropFiles",B.a9,"Opt-in (chatx-1031), web + desktop only, requires `attachments`: files dropped on the composer become pending attachment chips with the same caps as the + picker; a highlight shows while dragging over. Default off.",B.l,null,!1)
B.hVZ=new A.D("enterBehavior",B.Q,'Opt-in: "newline" (chatx-1031) makes plain Enter and Shift+Enter insert a newline; send = the send button or Cmd/Ctrl+Enter. "send" (entersend-1101, the standard chat convention) makes plain Enter and Cmd/Ctrl+Enter send and Shift+Enter insert a newline; on touch platforms the soft keyboard return key inserts a newline and the send button sends. Never sends/inserts while an IME composition is active. The send button gets a shortcut-hint tooltip and the field grows up to `maxLines`. Unset = Enter sends (unchanged). Values: "newline" | "send".',B.l,null,!1)
B.hOv=new A.D("enterBehaviorSetting",B.Q,'Opt-in (chatcomposer-1102): a settings key (e.g. "chat:enterKey"). When that setting holds "send" or "newline" it overrides `enterBehavior` live; any other value falls back to `enterBehavior`.',B.l,null,!1)
B.hUA=new A.D("fillSetting",B.Q,'Opt-in (chatcomposer-1102): a settings key holding text the host wants prefilled (e.g. "chat:composerFill"). When the seq setting (`fillSeqSetting`, default "<fillSetting>Seq") changes after mount the composer replaces its text with it, caret at the end, and takes focus. The mount-time seq is the baseline (no stale fire).',B.l,null,!1)
B.hT2=new A.D("fillSeqSetting",B.Q,'Optional seq settings key for `fillSetting` (default "<fillSetting>Seq").',B.l,null,!1)
B.i5c=new A.D("contentMaxWidth",B.aS,"Opt-in (chatlayout-1102): centres the composer in a column of this max width with a 16 px side gutter, matching a thread list whose `bubbles.contentMaxWidth` is the same value.",B.l,null,!1)
B.hHb=new A.D("draftOptions",B.W,'Opt-in chips above the box while a draft is typed, whose values go into the new row: a list of { kind: date|time|multi|single|duration|startNow, column, label?, table?, labelColumn?, allowNew? }. table is required for multi and single. colorColumn? colors a single option. duration (timers-1108): presets? (seconds, default [300,600,1500,3600]), allowCustom? (default true) \u2014 None / lengths / Custom, writes seconds. startNow: Start tracking now / Not now \u2014 when on, send writes the current UTC ISO time to column. newday-r5-1108 (opt-in): single/multi choices? [{value, label}] or choicesRange? [from, to] instead of table; scroll? (one sideways line with a right-edge fade); default? (shown selected, written on send; "" = nothing); sub? [{when: [parent values], ...option}] follow-up rows in one tinted box, never written while hidden; recentColumn? (most recently used first, stamped on send/new); showCount? + countLabel? ("{n} tags") + maxShown?; duration style? "stepper" + step? (seconds, default 60). newday-p1-1109 (opt-in): countLabelOne? ("{n} tag", for exactly one); stepper hours? (h : mm : ss); wrapNarrow? (with scroll: wraps under a 600 px window); single picker? \u2014 a "Choose\u2026" chip (replacing + New) opening a filterable list of every choice with its colour, Enter picks the top match, "+ Create group \u2026" opens the group editor prefilled (pickerTitle?, createLabel? "{name}", orderColumn?, settingKey? for the remembered custom colour).',B.l,null,!1)
B.hPN=new A.D("dayChip",B.W,"Opt-in (newday-r5b-1108): a chip inside the box, on the left, showing the day the entry goes to (\"Sun 8 \u25be\"); tap to pick. true (the first date draftOption's column), a column name, or {column, settingKey}. Day = the draft's pick, else the column's preset in values (e.g. $day:<key>), else settingKey's day, else today; send writes it.",B.l,null,!1)
B.hDw=new A.D("placeholderWith",B.W,'Opt-in (njgrouptags-1125): {"optionColumn": "<column>", "text": {"en": "Add a note to {name}\u2026"}} \u2014 while that table-backed draftOptions row has a pick (its default counts) the box\'s placeholder is `text` with the pick\'s name in {name}; otherwise the plain `placeholder`.',B.l,null,!1)
B.hWb=new A.D("draftPeekUntil",B.Q,'Opt-in (newday-r5-1108), with draftStyle "drawer": the column of the last draftOptions row shown while the keyboard is up; the rest sit below a fade and a "More below" cue until the bar is dragged up (which opens every row and grows the text box to 6 lines).',B.l,null,!1)
B.hRH=new A.D("float",B.a9,"Opt-in (newday-r5-1108), on a root footer composer: on a wide layout (content >= floatMinWidth, default 840) the box floats centred over the content, at most floatMaxWidth (default 640) wide, 16 px above the bottom, with a soft shadow; content gets its height + 16 as bottom padding.",B.l,null,!1)
B.hG_=new A.D("above",B.W,"Opt-in (newday-p1-1109), on a root footer: a node (e.g. groupadd) shown directly above the bottom box, left-aligned with it \u2014 on the docked band on a phone, over the content just above a floating box (counted in the content's bottom padding).",B.l,null,!1)
B.dhY=s(["chips","drawer"],t.s)
B.i2q=new A.D("draftStyle",B.bG,'How draftOptions show: "chips" (default) or "drawer" (a drawer rising with the draft, one line per option; peeks over a phone keyboard, opens when pulled up).',B.dhY,null,!1)
B.hMO=new A.D("trailingActions",B.W,"Opt-in (chatlayout-1102): list of {icon, tooltip, action}; the first entry renders as a 44x44 icon button between the field and Send. Fires without a draft.",B.l,null,!1)
B.hWn=new A.D("maxLines",B.aS,'With `enterBehavior` "newline" or "send": lines the field grows to before it scrolls internally (default 8). Ignored otherwise.',B.l,null,!1)
B.i1M=new A.D("busy",B.W,'Opt-in (chatcap-ui-1031), with `stopAction`: { statusColumn, statuses[], scopeColumn, scopeValue }. While the LATEST non-user row of `table` in scope (scopeColumn == resolved scopeValue, e.g. "$selected:subchats") has a status in `statuses`, the send button becomes a Stop button and sending is disabled.',B.l,null,!1)
B.i7h=new A.D("stopAction",B.W,"Opt-in (chatcap-ui-1031): the action the Stop button fires (see `busy`).",B.l,null,!1)
B.i2k=new A.D("stopLabel",B.Q,"Stop button tooltip; may be a {lang: text} map.",B.l,null,!0)
