B.hdo=new A.dp("composer",'A chat-style "type a message and send" input. Unlike notepad (which edits one row in place), it APPENDS a new row each send \u2014 carrying the typed text plus preset values ($playerId/now/uuid resolved) \u2014 then clears itself. The primitive for chats, comments and logs.',B.dq8,!1)
B.hSc=new A.D("table",B.b4,"Table of the row to edit (defaults to the host/injected table).",B.l,null,!1)
B.hFS=new A.D("rowId",B.Q,"Id of the row to edit (usually injected by a master-detail host). A `$selected:<table>` token binds to the board-level `selectRow` pick instead of a literal id.",B.l,null,!1)
B.hXW=new A.D("emptyText",B.Q,"Placeholder shown when nothing is selected; may be a {lang: text} map.",B.l,null,!0)
B.hRW=new A.D("readOnly",B.a9,"Show a posted row as an un-editable read view; a row just created in the host explorer (isNew) still opens editable so its author can fill it in once.",B.l,null,!1)
B.i0_=new A.D("hideTitle",B.a9,'Editable record only: hide the "Edit <table>" heading (action icons stay) when the record already sits under its own title, e.g. in a popup headed by the row\'s name.',B.l,null,!1)
B.hSy=new A.D("backOnClose",B.a9,"Editable record only (form-input-1101): when the editor closes (Save \u2713, Discard, Delete) step back to the screen that opened this one \u2014 pop the nearest route, else hand `back` to the host. Makes a form screen's Save return to its list. Default off (stays in place).",B.l,null,!1)
B.hXG=new A.D("compact",B.a9,'Intrinsic-height, non-scrolling read view (sits as a header in a column) with an "Edit details" affordance that opens the editor.',B.l,null,!1)
B.i2K=new A.D("layout",B.Q,'Read-view layout. "chips" renders the first field as a heading, long-text fields as a truncate-on-tap line, and the rest as compact inline "Label \xb7 value" chips in a Wrap. Any other value or absent keeps the default stacked label-above-value rows.',B.l,null,!1)
B.i_8=new A.D("fields",B.W,'Explicit list of column names to show (read view + editor). Keeps a detail to its real fields (e.g. ["title","status","description"]) regardless of the stored schema\'s hidden flags; other columns are left untouched on save.',B.l,null,!1)
B.hLs=new A.D("statusColumn",B.L,"Completion reconcile: the status column the editor watches (default status). See completedByColumn.",B.l,null,!1)
B.hZv=new A.D("completedByColumn",B.L,"Opt-in: ref column stamped with the actor when status is saved AT doneStatus, and CLEARED when saved off it \u2014 so reopening an item through the editor never leaves a stale completer.",B.l,null,!1)
B.hGE=new A.D("finishedAtColumn",B.L,"Opt-in: date column stamped today on completion and cleared on reopen (pairs with completedByColumn).",B.l,null,!1)
B.hSN=new A.D("doneStatus",B.Q,"Status value that counts as done for completion stamping (default done).",B.l,null,!1)
B.hWi=new A.D("defaultActor",B.Q,"Fallback completer id when the signed-in user is not a row of the completedBy ref table.",B.l,null,!1)
B.hH9=new A.D("editedByColumn",B.L,'Opt-in: ref column stamped with the actor when a save actually changes a field (not on create, not on a no-op save) \u2014 an honest "last edited by".',B.l,null,!1)
B.i4R=new A.D("editedAtColumn",B.L,"Opt-in: date column stamped today alongside editedByColumn on a real edit.",B.l,null,!1)
B.hIU=new A.D("valueLabels",B.W,'Opt-in (overviewsweep-0822), display-only: raw stored value \u2192 display text map (flat `{value: entry}` or column-keyed `{column: {value: entry}}`), each entry a plain string or a {lang: text} map. Used by the "chips" layout\'s inline "Label \xb7 value" chips so an enum/status column shows a translated word instead of the raw stored value under a non-English locale; the stored value itself is never touched. Same shape/precedence as the "cards" node\'s valueLabels.',B.l,null,!1)
B.hJd=new A.D("chipsInset",B.aS,'dispfb-1018, "chips" layout: horizontal inset (px) around the heading/chips block. Default 20 (unchanged). Set 0 when a parent (e.g. an explorer `detailGutter`) already supplies the gutter.',B.l,null,!1)
B.i6Y=new A.D("placeholders",B.W,'Opt-in (dufb-1017), "chips" layout: `{column: text}` \u2014 a listed field that is EMPTY shows a muted placeholder (e.g. "Untitled", "No comment yet") instead of disappearing, so an untitled row never borrows its next field as the heading. Each text is a {lang: text} map or a plain engine string key (recordPlaceholderUntitled, recordPlaceholderNoComment).',B.l,null,!1)
B.hR4=new A.D("hideValues",B.W,'Opt-in (disppage-1125), "chips" layout: `{column: [stored values]}` - a field whose value is listed (a default such as "normal") is left out of the header. Absent = every filled field shows.',B.l,null,!1)
B.hSY=new A.D("dimColumns",B.W,'Opt-in (disppage-1125), "chips" layout: column names shown as one dim line of text after the chips (e.g. the created date) instead of as chips.',B.l,null,!1)
