B.hNX=new A.D("options",B.W,"The rows, in page order \u2014 the composer draftOptions shape (date, time, duration, startNow, single, multi; choices, sub, scroll, style, recentColumn, showCount\u2026).",B.l,null,!1)
B.hQs=new A.D("timer",B.W,"Countdown columns + alarm, as timercard `timer`; false = none.",B.l,null,!1)
