B.fDq=new A.b(B.m,['Delete column "{name}"?',"\xbfEliminar la columna \xab{name}\xbb?","Supprimer la colonne \xab {name} \xbb ?","Spalte \u201e{name}\u201c l\xf6schen?","Eliminare la colonna \xab{name}\xbb?","Excluir a coluna \u201c{name}\u201d?","Kolom \u201c{name}\u201d verwijderen?","Ta bort kolumnen \u201d{name}\u201d?","Smazat sloupec \u201e{name}\u201c?","\u0394\u03b9\u03b1\u03b3\u03c1\u03b1\u03c6\u03ae \u03c4\u03b7\u03c2 \u03c3\u03c4\u03ae\u03bb\u03b7\u03c2 \xab{name}\xbb;","Usun\u0105\u0107 kolumn\u0119 \u201e{name}\u201d?","\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0441\u0442\u043e\u0432\u043f\u0435\u0446\u044c \xab{name}\xbb?","\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0441\u0442\u043e\u043b\u0431\u0435\u0446 \xab{name}\xbb?","\u201c{name}\u201d s\xfctunu silinsin mi?","X\xf3a c\u1ed9t \u201c{name}\u201d?",'"{name}" \uc5f4\uc744 \uc0ad\uc81c\ud560\uae4c\uc694?',"\u5217\u300c{name}\u300d\u3092\u524a\u9664\u3057\u307e\u3059\u304b?","\u5220\u9664\u5217\u201c{name}\u201d?","\u062d\u0630\u0641 \u0627\u0644\u0639\u0645\u0648\u062f \xab{name}\xbb\u061f","\u0938\u094d\u0924\u0902\u092d \u201c{name}\u201d \u0939\u091f\u093e\u090f\u0901?","\u0633\u062a\u0648\u0646 \xab{name}\xbb \u062d\u0630\u0641 \u0634\u0648\u062f\u061f"],t.w)
B.fBW=new A.b(B.m,["Values stay in stored rows but the column leaves the schema.","Los valores se conservan en las filas guardadas, pero la columna sale del esquema.","Les valeurs restent dans les lignes enregistr\xe9es, mais la colonne quitte le sch\xe9ma.","Die Werte bleiben in den gespeicherten Zeilen, aber die Spalte verl\xe4sst das Schema.","I valori restano nelle righe salvate, ma la colonna esce dallo schema.","Os valores permanecem nas linhas salvas, mas a coluna sai do esquema.","De waarden blijven in de opgeslagen rijen, maar de kolom verdwijnt uit het schema.","V\xe4rdena finns kvar i sparade rader, men kolumnen l\xe4mnar schemat.","Hodnoty z\u016fstanou v ulo\u017een\xfdch \u0159\xe1dc\xedch, ale sloupec opust\xed sch\xe9ma.","\u039f\u03b9 \u03c4\u03b9\u03bc\u03ad\u03c2 \u03c0\u03b1\u03c1\u03b1\u03bc\u03ad\u03bd\u03bf\u03c5\u03bd \u03c3\u03c4\u03b9\u03c2 \u03b1\u03c0\u03bf\u03b8\u03b7\u03ba\u03b5\u03c5\u03bc\u03ad\u03bd\u03b5\u03c2 \u03b3\u03c1\u03b1\u03bc\u03bc\u03ad\u03c2, \u03b1\u03bb\u03bb\u03ac \u03b7 \u03c3\u03c4\u03ae\u03bb\u03b7 \u03c6\u03b5\u03cd\u03b3\u03b5\u03b9 \u03b1\u03c0\u03cc \u03c4\u03bf \u03c3\u03c7\u03ae\u03bc\u03b1.","Warto\u015bci pozostaj\u0105 w zapisanych wierszach, ale kolumna znika ze schematu.","\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u0437\u0430\u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u0432 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u0438\u0445 \u0440\u044f\u0434\u043a\u0430\u0445, \u0430\u043b\u0435 \u0441\u0442\u043e\u0432\u043f\u0435\u0446\u044c \u0437\u043d\u0438\u043a\u0430\u0454 \u0437\u0456 \u0441\u0445\u0435\u043c\u0438.","\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432 \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u044b\u0445 \u0441\u0442\u0440\u043e\u043a\u0430\u0445, \u043d\u043e \u0441\u0442\u043e\u043b\u0431\u0435\u0446 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442 \u0438\u0437 \u0441\u0445\u0435\u043c\u044b.","De\u011ferler kay\u0131tl\u0131 sat\u0131rlarda kal\u0131r ancak s\xfctun \u015femadan \xe7\u0131kar.","Gi\xe1 tr\u1ecb v\u1eabn n\u1eb1m trong c\xe1c h\xe0ng \u0111\xe3 l\u01b0u nh\u01b0ng c\u1ed9t s\u1ebd r\u1eddi kh\u1ecfi l\u01b0\u1ee3c \u0111\u1ed3.","\uac12\uc740 \uc800\uc7a5\ub41c \ud589\uc5d0 \ub0a8\uc9c0\ub9cc \uc5f4\uc740 \uc2a4\ud0a4\ub9c8\uc5d0\uc11c \uc81c\uac70\ub429\ub2c8\ub2e4.","\u5024\u306f\u4fdd\u5b58\u6e08\u307f\u306e\u884c\u306b\u6b8b\u308a\u307e\u3059\u304c\u3001\u5217\u306f\u30b9\u30ad\u30fc\u30de\u304b\u3089\u5916\u308c\u307e\u3059\u3002","\u6570\u503c\u4ecd\u4fdd\u7559\u5728\u5df2\u5b58\u50a8\u7684\u884c\u4e2d,\u4f46\u8be5\u5217\u5c06\u4ece\u67b6\u6784\u4e2d\u79fb\u9664\u3002","\u062a\u0628\u0642\u0649 \u0627\u0644\u0642\u064a\u0645 \u0641\u064a \u0627\u0644\u0635\u0641\u0648\u0641 \u0627\u0644\u0645\u062e\u0632\u0651\u0646\u0629 \u0644\u0643\u0646 \u0627\u0644\u0639\u0645\u0648\u062f \u064a\u063a\u0627\u062f\u0631 \u0627\u0644\u0645\u062e\u0637\u0637.","\u092e\u093e\u0928 \u0938\u0902\u0917\u094d\u0930\u0939\u0940\u0924 \u092a\u0902\u0915\u094d\u0924\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902, \u092a\u0930 \u0938\u094d\u0924\u0902\u092d \u0938\u094d\u0915\u0940\u092e\u093e \u0938\u0947 \u0939\u091f \u091c\u093e\u0924\u093e \u0939\u0948\u0964","\u0645\u0642\u0627\u062f\u06cc\u0631 \u062f\u0631 \u0631\u062f\u06cc\u0641\u200c\u0647\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0634\u062f\u0647 \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f \u0627\u0645\u0627 \u0633\u062a\u0648\u0646 \u0627\u0632 \u0637\u0631\u062d \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f."],t.w)
