B.fyr=new A.b(B.m,["What should this app do?","\xbfQu\xe9 debe hacer esta app?","Que doit faire cette app ?","Was soll diese App k\xf6nnen?","Che cosa deve fare questa app?","O que esta app deve fazer?","Wat moet deze app doen?","Vad ska appen g\xf6ra?","Co m\xe1 tato aplikace d\u011blat?","\u03a4\u03b9 \u03c0\u03c1\u03ad\u03c0\u03b5\u03b9 \u03bd\u03b1 \u03ba\u03ac\u03bd\u03b5\u03b9 \u03b1\u03c5\u03c4\u03ae \u03b7 \u03b5\u03c6\u03b1\u03c1\u03bc\u03bf\u03b3\u03ae;","Co ma robi\u0107 ta aplikacja?","\u0429\u043e \u043c\u0430\u0454 \u0440\u043e\u0431\u0438\u0442\u0438 \u0446\u0435\u0439 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a?","\u0427\u0442\u043e \u0434\u043e\u043b\u0436\u043d\u043e \u0434\u0435\u043b\u0430\u0442\u044c \u044d\u0442\u043e \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435?","Bu uygulama ne yapmal\u0131?","\u1ee8ng d\u1ee5ng n\xe0y c\u1ea7n l\xe0m g\xec?","\uc774 \uc571\uc740 \ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub098\uc694?","\u3053\u306e\u30a2\u30d7\u30ea\u3067\u4f55\u3092\u3057\u307e\u3059\u304b?","\u8fd9\u4e2a\u5e94\u7528\u8981\u505a\u4ec0\u4e48?","\u0645\u0627\u0630\u0627 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0641\u0639\u0644 \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u061f","\u092f\u0939 \u0910\u092a \u0915\u094d\u092f\u093e \u0915\u0930\u0947?","\u0627\u06cc\u0646 \u0628\u0631\u0646\u0627\u0645\u0647 \u0628\u0627\u06cc\u062f \u0686\u0647 \u06a9\u0627\u0631 \u06a9\u0646\u062f\u061f"],t.w)
B.fI6=new A.b(B.m,["e.g. A shopping list I can share with my family, with a checklist and a running total","p. ej., una lista de la compra para compartir con mi familia, con casillas y un total","p. ex. une liste de courses \xe0 partager en famille, avec des cases \xe0 cocher et un total","z. B. eine Einkaufsliste f\xfcr die Familie, mit Abhaken und laufender Summe","es. una lista della spesa da condividere con la famiglia, con caselle e un totale","ex.: uma lista de compras para partilhar com a fam\xedlia, com caixas de sele\xe7\xe3o e um total","bijv. een boodschappenlijst die ik met mijn gezin deel, met afvinken en een totaal","t.ex. en ink\xf6pslista att dela med familjen, med bockar och en summa","nap\u0159. n\xe1kupn\xed seznam sd\xedlen\xfd s rodinou, se za\u0161krt\xe1v\xe1n\xedm a sou\u010dtem","\u03c0.\u03c7. \u03bc\u03b9\u03b1 \u03bb\u03af\u03c3\u03c4\u03b1 \u03b1\u03b3\u03bf\u03c1\u03ce\u03bd \u03b3\u03b9\u03b1 \u03c4\u03b7\u03bd \u03bf\u03b9\u03ba\u03bf\u03b3\u03ad\u03bd\u03b5\u03b9\u03b1, \u03bc\u03b5 \u03c4\u03b9\u03ba \u03ba\u03b1\u03b9 \u03c3\u03cd\u03bd\u03bf\u03bb\u03bf","np. lista zakup\xf3w dla rodziny, z odhaczaniem i sum\u0105","\u043d\u0430\u043f\u0440., \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u043e\u043a\u0443\u043f\u043e\u043a \u0434\u043b\u044f \u0440\u043e\u0434\u0438\u043d\u0438 \u0437 \u043f\u043e\u0437\u043d\u0430\u0447\u043a\u0430\u043c\u0438 \u0442\u0430 \u043f\u0456\u0434\u0441\u0443\u043c\u043a\u043e\u043c","\u043d\u0430\u043f\u0440., \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u043e\u043a\u0443\u043f\u043e\u043a \u0434\u043b\u044f \u0441\u0435\u043c\u044c\u0438 \u0441 \u043e\u0442\u043c\u0435\u0442\u043a\u0430\u043c\u0438 \u0438 \u0438\u0442\u043e\u0433\u043e\u043c","\xf6r. ailemle payla\u015faca\u011f\u0131m, i\u015faretlenebilen ve toplam\u0131 g\xf6steren bir al\u0131\u015fveri\u015f listesi","vd: danh s\xe1ch mua s\u1eafm chia s\u1ebb v\u1edbi gia \u0111\xecnh, c\xf3 \xf4 \u0111\xe1nh d\u1ea5u v\xe0 t\u1ed5ng ti\u1ec1n","\uc608: \uac00\uc871\uacfc \uacf5\uc720\ud558\ub294 \uc7a5\ubcf4\uae30 \ubaa9\ub85d, \uccb4\ud06c\ub9ac\uc2a4\ud2b8\uc640 \ud569\uacc4 \ud3ec\ud568","\u4f8b: \u5bb6\u65cf\u3068\u5171\u6709\u3067\u304d\u308b\u8cb7\u3044\u7269\u30ea\u30b9\u30c8\u3002\u30c1\u30a7\u30c3\u30af\u6b04\u3068\u5408\u8a08\u3064\u304d","\u4f8b\u5982:\u53ef\u4e0e\u5bb6\u4eba\u5171\u4eab\u7684\u8d2d\u7269\u6e05\u5355,\u5e26\u52fe\u9009\u548c\u5408\u8ba1","\u0645\u062b\u0627\u0644: \u0642\u0627\u0626\u0645\u0629 \u062a\u0633\u0648\u0651\u0642 \u0623\u0634\u0627\u0631\u0643\u0647\u0627 \u0645\u0639 \u0639\u0627\u0626\u0644\u062a\u064a\u060c \u0645\u0639 \u062e\u0627\u0646\u0627\u062a \u0627\u062e\u062a\u064a\u0627\u0631 \u0648\u0645\u062c\u0645\u0648\u0639","\u091c\u0948\u0938\u0947: \u092a\u0930\u093f\u0935\u093e\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0938\u093e\u091d\u093e \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0940 \u0916\u093c\u0930\u0940\u0926\u093e\u0930\u0940 \u0938\u0942\u091a\u0940, \u091a\u0947\u0915\u0932\u093f\u0938\u094d\u091f \u0914\u0930 \u0915\u0941\u0932 \u092f\u094b\u0917 \u0915\u0947 \u0938\u093e\u0925","\u0645\u062b\u0644\u0627\u064b: \u0641\u0647\u0631\u0633\u062a \u062e\u0631\u06cc\u062f\u06cc \u06a9\u0647 \u0628\u0627 \u062e\u0627\u0646\u0648\u0627\u062f\u0647 \u0628\u0647 \u0627\u0634\u062a\u0631\u0627\u06a9 \u0628\u06af\u0630\u0627\u0631\u0645\u060c \u0628\u0627 \u062a\u06cc\u06a9\u200c\u0632\u062f\u0646 \u0648 \u062c\u0645\u0639 \u06a9\u0644"],t.w)
B.ffU=new A.b(B.m,["Describe the app first.","Primero describe la app.","D\xe9crivez d\u2019abord l\u2019app.","Beschreibe zuerst die App.","Descrivi prima l\u2019app.","Descreva primeiro a app.","Beschrijf eerst de app.","Beskriv appen f\xf6rst.","Nejprve aplikaci popi\u0161te.","\u03a0\u03b5\u03c1\u03b9\u03b3\u03c1\u03ac\u03c8\u03c4\u03b5 \u03c0\u03c1\u03ce\u03c4\u03b1 \u03c4\u03b7\u03bd \u03b5\u03c6\u03b1\u03c1\u03bc\u03bf\u03b3\u03ae.","Najpierw opisz aplikacj\u0119.","\u0421\u043f\u0435\u0440\u0448\u0443 \u043e\u043f\u0438\u0448\u0456\u0442\u044c \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a.","\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u043f\u0438\u0448\u0438\u0442\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435.","\xd6nce uygulamay\u0131 tan\u0131mlay\u0131n.","H\xe3y m\xf4 t\u1ea3 \u1ee9ng d\u1ee5ng tr\u01b0\u1edbc.","\uba3c\uc800 \uc571\uc744 \uc124\uba85\ud574 \uc8fc\uc138\uc694.","\u307e\u305a\u30a2\u30d7\u30ea\u306e\u8aac\u660e\u3092\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044\u3002","\u8bf7\u5148\u63cf\u8ff0\u8fd9\u4e2a\u5e94\u7528\u3002","\u0635\u0650\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648\u0644\u064b\u0627.","\u092a\u0939\u0932\u0947 \u0910\u092a \u0915\u093e \u0935\u0930\u094d\u0923\u0928 \u0915\u0930\u0947\u0902\u0964","\u0627\u0648\u0644 \u0628\u0631\u0646\u0627\u0645\u0647 \u0631\u0627 \u062a\u0648\u0636\u06cc\u062d \u062f\u0647\u06cc\u062f."],t.w)
B.fai=new A.b(B.m,["This opens a new scenario named after your description, and the assistant builds a first draft there. Every step it takes is shown, can be undone, and is one you can do by hand.","Se abre un escenario nuevo con el nombre de tu descripci\xf3n y el asistente crea ah\xed un primer borrador. Cada paso se muestra, se puede deshacer y puedes hacerlo a mano.","Un nouveau sc\xe9nario nomm\xe9 d\u2019apr\xe8s votre description s\u2019ouvre, et l\u2019assistant y construit un premier jet. Chaque \xe9tape est affich\xe9e, annulable et faisable \xe0 la main.","Ein neues Szenario mit dem Namen deiner Beschreibung wird ge\xf6ffnet, und der Assistent baut dort einen ersten Entwurf. Jeder Schritt wird angezeigt, ist r\xfcckg\xe4ngig zu machen und auch von Hand machbar.","Si apre un nuovo scenario con il nome della tua descrizione e l\u2019assistente vi crea una prima bozza. Ogni passaggio \xe8 visibile, annullabile e fattibile a mano.","Abre-se um cen\xe1rio novo com o nome da sua descri\xe7\xe3o e o assistente cria l\xe1 um primeiro rascunho. Cada passo \xe9 mostrado, pode ser anulado e pode ser feito \xe0 m\xe3o.","Er opent een nieuw scenario met de naam uit je beschrijving, en de assistent bouwt daar een eerste versie. Elke stap wordt getoond, is ongedaan te maken en kun je zelf doen.","Ett nytt scenario med namn efter din beskrivning \xf6ppnas, och assistenten bygger ett f\xf6rsta utkast d\xe4r. Varje steg visas, kan \xe5ngras och kan g\xf6ras f\xf6r hand.","Otev\u0159e se nov\xfd sc\xe9n\xe1\u0159 pojmenovan\xfd podle popisu a asistent v n\u011bm vytvo\u0159\xed prvn\xed n\xe1vrh. Ka\u017ed\xfd krok je vid\u011bt, jde vr\xe1tit a zvl\xe1dnete ho i ru\u010dn\u011b.","\u0391\u03bd\u03bf\u03af\u03b3\u03b5\u03b9 \u03bd\u03ad\u03bf \u03c3\u03b5\u03bd\u03ac\u03c1\u03b9\u03bf \u03bc\u03b5 \u03cc\u03bd\u03bf\u03bc\u03b1 \u03b1\u03c0\u03cc \u03c4\u03b7\u03bd \u03c0\u03b5\u03c1\u03b9\u03b3\u03c1\u03b1\u03c6\u03ae \u03c3\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03bf \u03b2\u03bf\u03b7\u03b8\u03cc\u03c2 \u03c6\u03c4\u03b9\u03ac\u03c7\u03bd\u03b5\u03b9 \u03b5\u03ba\u03b5\u03af \u03ad\u03bd\u03b1 \u03c0\u03c1\u03ce\u03c4\u03bf \u03c0\u03c1\u03bf\u03c3\u03c7\u03ad\u03b4\u03b9\u03bf. \u039a\u03ac\u03b8\u03b5 \u03b2\u03ae\u03bc\u03b1 \u03c6\u03b1\u03af\u03bd\u03b5\u03c4\u03b1\u03b9, \u03b1\u03bd\u03b1\u03b9\u03c1\u03b5\u03af\u03c4\u03b1\u03b9 \u03ba\u03b1\u03b9 \u03b3\u03af\u03bd\u03b5\u03c4\u03b1\u03b9 \u03ba\u03b1\u03b9 \u03bc\u03b5 \u03c4\u03bf \u03c7\u03ad\u03c1\u03b9.","Otworzy si\u0119 nowy scenariusz nazwany wed\u0142ug opisu, a asystent zbuduje w nim pierwsz\u0105 wersj\u0119. Ka\u017cdy krok jest widoczny, mo\u017cna go cofn\u0105\u0107 i wykona\u0107 r\u0119cznie.","\u0412\u0456\u0434\u043a\u0440\u0438\u0454\u0442\u044c\u0441\u044f \u043d\u043e\u0432\u0438\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0456\u0439 \u0456\u0437 \u043d\u0430\u0437\u0432\u043e\u044e \u0437 \u043e\u043f\u0438\u0441\u0443, \u0456 \u043f\u043e\u043c\u0456\u0447\u043d\u0438\u043a \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u044c \u0443 \u043d\u044c\u043e\u043c\u0443 \u043f\u0435\u0440\u0448\u0443 \u0447\u0435\u0440\u043d\u0435\u0442\u043a\u0443. \u041a\u043e\u0436\u0435\u043d \u043a\u0440\u043e\u043a \u0432\u0438\u0434\u043d\u043e, \u0439\u043e\u0433\u043e \u043c\u043e\u0436\u043d\u0430 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0439 \u0437\u0440\u043e\u0431\u0438\u0442\u0438 \u0432\u0440\u0443\u0447\u043d\u0443.","\u041e\u0442\u043a\u0440\u043e\u0435\u0442\u0441\u044f \u043d\u043e\u0432\u044b\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 \u0441 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435\u043c \u0438\u0437 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044f, \u0438 \u043f\u043e\u043c\u043e\u0449\u043d\u0438\u043a \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u0432 \u043d\u0451\u043c \u043f\u0435\u0440\u0432\u044b\u0439 \u0447\u0435\u0440\u043d\u043e\u0432\u0438\u043a. \u041a\u0430\u0436\u0434\u044b\u0439 \u0448\u0430\u0433 \u0432\u0438\u0434\u0435\u043d, \u0435\u0433\u043e \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u0438 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0432\u0440\u0443\u0447\u043d\u0443\u044e.","A\xe7\u0131klaman\u0131zdan ad\u0131n\u0131 alan yeni bir senaryo a\xe7\u0131l\u0131r ve asistan orada ilk tasla\u011f\u0131 kurar. Her ad\u0131m g\xf6sterilir, geri al\u0131nabilir ve elle de yap\u0131labilir.","M\u1ed9t k\u1ecbch b\u1ea3n m\u1edbi mang t\xean theo m\xf4 t\u1ea3 c\u1ee7a b\u1ea1n s\u1ebd m\u1edf ra, v\xe0 tr\u1ee3 l\xfd d\u1ef1ng b\u1ea3n nh\xe1p \u0111\u1ea7u ti\xean \u1edf \u0111\xf3. M\u1ed7i b\u01b0\u1edbc \u0111\u1ec1u hi\u1ec3n th\u1ecb, ho\xe0n t\xe1c \u0111\u01b0\u1ee3c v\xe0 b\u1ea1n c\xf3 th\u1ec3 t\u1ef1 l\xe0m.","\uc124\uba85\uc5d0\uc11c \uc774\ub984\uc744 \ub534 \uc0c8 \uc2dc\ub098\ub9ac\uc624\uac00 \uc5f4\ub9ac\uace0, \uc5b4\uc2dc\uc2a4\ud134\ud2b8\uac00 \uadf8\uacf3\uc5d0 \uccab \ucd08\uc548\uc744 \ub9cc\ub4ed\ub2c8\ub2e4. \ubaa8\ub4e0 \ub2e8\uacc4\ub294 \ud45c\uc2dc\ub418\uba70 \uc2e4\ud589 \ucde8\uc18c\ud560 \uc218 \uc788\uace0 \uc9c1\uc811 \ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\u8aac\u660e\u306b\u3061\u306a\u3093\u3060\u540d\u524d\u306e\u65b0\u3057\u3044\u30b7\u30ca\u30ea\u30aa\u304c\u958b\u304d\u3001\u30a2\u30b7\u30b9\u30bf\u30f3\u30c8\u304c\u305d\u3053\u306b\u6700\u521d\u306e\u4e0b\u66f8\u304d\u3092\u4f5c\u308a\u307e\u3059\u3002\u5404\u624b\u9806\u306f\u8868\u793a\u3055\u308c\u3001\u5143\u306b\u623b\u305b\u3001\u624b\u4f5c\u696d\u3067\u3082\u884c\u3048\u307e\u3059\u3002","\u5c06\u6253\u5f00\u4e00\u4e2a\u4ee5\u4f60\u7684\u63cf\u8ff0\u547d\u540d\u7684\u65b0\u65b9\u6848,\u52a9\u624b\u4f1a\u5728\u5176\u4e2d\u642d\u5efa\u521d\u7a3f\u3002\u6bcf\u4e00\u6b65\u90fd\u4f1a\u663e\u793a\u3001\u53ef\u64a4\u9500,\u4e5f\u90fd\u80fd\u624b\u52a8\u5b8c\u6210\u3002","\u064a\u064f\u0641\u062a\u062d \u0633\u064a\u0646\u0627\u0631\u064a\u0648 \u062c\u062f\u064a\u062f \u0628\u0627\u0633\u0645 \u0645\u0623\u062e\u0648\u0630 \u0645\u0646 \u0648\u0635\u0641\u0643\u060c \u0648\u064a\u0628\u0646\u064a \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0641\u064a\u0647 \u0645\u0633\u0648\u062f\u0629 \u0623\u0648\u0644\u0649. \u0643\u0644 \u062e\u0637\u0648\u0629 \u062a\u0638\u0647\u0631 \u0648\u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647\u0627 \u0648\u062a\u0646\u0641\u064a\u0630\u0647\u0627 \u064a\u062f\u0648\u064a\u064b\u0627.","\u0906\u092a\u0915\u0947 \u0935\u093f\u0935\u0930\u0923 \u0915\u0947 \u0928\u093e\u092e \u0938\u0947 \u090f\u0915 \u0928\u092f\u093e \u092a\u0930\u093f\u0926\u0943\u0936\u094d\u092f \u0916\u0941\u0932\u0924\u093e \u0939\u0948 \u0914\u0930 \u0938\u0939\u093e\u092f\u0915 \u0909\u0938\u092e\u0947\u0902 \u092a\u0939\u0932\u093e \u092e\u0938\u094c\u0926\u093e \u092c\u0928\u093e\u0924\u093e \u0939\u0948\u0964 \u0939\u0930 \u091a\u0930\u0923 \u0926\u093f\u0916\u0924\u093e \u0939\u0948, \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948 \u0914\u0930 \u0906\u092a \u0909\u0938\u0947 \u0939\u093e\u0925 \u0938\u0947 \u092d\u0940 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964","\u0633\u0646\u0627\u0631\u06cc\u0648\u06cc \u062a\u0627\u0632\u0647\u200c\u0627\u06cc \u0628\u0627 \u0646\u0627\u0645\u06cc \u0627\u0632 \u062a\u0648\u0636\u06cc\u062d \u0634\u0645\u0627 \u0628\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u0633\u062a\u06cc\u0627\u0631 \u067e\u06cc\u0634\u200c\u0646\u0648\u06cc\u0633 \u0627\u0648\u0644 \u0631\u0627 \u0622\u0646\u062c\u0627 \u0645\u06cc\u200c\u0633\u0627\u0632\u062f. \u0647\u0631 \u0642\u062f\u0645 \u0646\u0645\u0627\u06cc\u0634 \u062f\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0628\u0631\u06af\u0634\u062a\u200c\u067e\u0630\u06cc\u0631 \u0627\u0633\u062a \u0648 \u062f\u0633\u062a\u06cc \u0647\u0645 \u0634\u062f\u0646\u06cc \u0627\u0633\u062a."],t.w)
B.fI2=new A.b(B.m,["Start","Empezar","Commencer","Starten","Inizia","Come\xe7ar","Beginnen","B\xf6rja","Za\u010d\xedt","\u0388\u03bd\u03b1\u03c1\u03be\u03b7","Zacznij","\u041f\u043e\u0447\u0430\u0442\u0438","\u041d\u0430\u0447\u0430\u0442\u044c","Ba\u015fla","B\u1eaft \u0111\u1ea7u","\uc2dc\uc791","\u958b\u59cb","\u5f00\u59cb","\u0627\u0628\u062f\u0623","\u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902","\u0634\u0631\u0648\u0639"],t.w)
B.fhf=new A.b(B.m,["Your request is kept and sends as soon as a model is set up:","Tu petici\xf3n se guarda y se env\xeda en cuanto haya un modelo configurado:","Votre demande est conserv\xe9e et sera envoy\xe9e d\xe8s qu\u2019un mod\xe8le sera configur\xe9 :","Deine Anfrage bleibt erhalten und wird gesendet, sobald ein Modell eingerichtet ist:","La richiesta resta qui e parte appena configuri un modello:","O seu pedido fica guardado e \xe9 enviado assim que houver um modelo configurado:","Je verzoek blijft bewaard en wordt verstuurd zodra er een model is ingesteld:","Din beg\xe4ran sparas och skickas s\xe5 snart en modell \xe4r konfigurerad:","V\xe1\u0161 po\u017eadavek z\u016fstane ulo\u017een a ode\u0161le se, jakmile nastav\xedte model:","\u03a4\u03bf \u03b1\u03af\u03c4\u03b7\u03bc\u03ac \u03c3\u03b1\u03c2 \u03ba\u03c1\u03b1\u03c4\u03b9\u03ad\u03c4\u03b1\u03b9 \u03ba\u03b1\u03b9 \u03c3\u03c4\u03ad\u03bb\u03bd\u03b5\u03c4\u03b1\u03b9 \u03bc\u03cc\u03bb\u03b9\u03c2 \u03c1\u03c5\u03b8\u03bc\u03b9\u03c3\u03c4\u03b5\u03af \u03ad\u03bd\u03b1 \u03bc\u03bf\u03bd\u03c4\u03ad\u03bb\u03bf:","Pro\u015bba zostaje zachowana i wy\u015ble si\u0119, gdy tylko skonfigurujesz model:","\u0412\u0430\u0448 \u0437\u0430\u043f\u0438\u0442 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e, \u0456 \u0439\u043e\u0433\u043e \u0431\u0443\u0434\u0435 \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u043d\u043e, \u0449\u043e\u0439\u043d\u043e \u043d\u0430\u043b\u0430\u0448\u0442\u0443\u0454\u0442\u0435 \u043c\u043e\u0434\u0435\u043b\u044c:","\u0417\u0430\u043f\u0440\u043e\u0441 \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d \u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u0441\u044f, \u043a\u0430\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0443\u0434\u0435\u0442 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043d\u0430 \u043c\u043e\u0434\u0435\u043b\u044c:","\u0130ste\u011finiz saklan\u0131r ve bir model kurulur kurulmaz g\xf6nderilir:","Y\xeau c\u1ea7u c\u1ee7a b\u1ea1n \u0111\u01b0\u1ee3c gi\u1eef l\u1ea1i v\xe0 s\u1ebd g\u1eedi ngay khi thi\u1ebft l\u1eadp xong m\u1ed9t m\xf4 h\xecnh:","\uc694\uccad\uc740 \ubcf4\uad00\ub418\uba70 \ubaa8\ub378\uc744 \uc124\uc815\ud558\ub294 \uc989\uc2dc \uc804\uc1a1\ub429\ub2c8\ub2e4:","\u30ea\u30af\u30a8\u30b9\u30c8\u306f\u4fdd\u6301\u3055\u308c\u3001\u30e2\u30c7\u30eb\u3092\u8a2d\u5b9a\u3059\u308b\u3068\u3059\u3050\u306b\u9001\u4fe1\u3055\u308c\u307e\u3059:","\u4f60\u7684\u8bf7\u6c42\u5df2\u4fdd\u7559,\u8bbe\u7f6e\u597d\u6a21\u578b\u540e\u4f1a\u7acb\u5373\u53d1\u9001:","\u0637\u0644\u0628\u0643 \u0645\u062d\u0641\u0648\u0638 \u0648\u0633\u064a\u064f\u0631\u0633\u0644 \u0641\u0648\u0631 \u0625\u0639\u062f\u0627\u062f \u0646\u0645\u0648\u0630\u062c:","\u0906\u092a\u0915\u093e \u0905\u0928\u0941\u0930\u094b\u0927 \u0930\u0916\u093e \u0917\u092f\u093e \u0939\u0948 \u0914\u0930 \u092e\u0949\u0921\u0932 \u0938\u0947\u091f \u0939\u094b\u0924\u0947 \u0939\u0940 \u092d\u0947\u091c\u093e \u091c\u093e\u090f\u0917\u093e:","\u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0634\u0645\u0627 \u0646\u06af\u0647 \u062f\u0627\u0634\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0628\u0647\u200c\u0645\u062d\u0636 \u0631\u0627\u0647\u200c\u0627\u0646\u062f\u0627\u0632\u06cc \u06cc\u06a9 \u0645\u062f\u0644 \u0641\u0631\u0633\u062a\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f:"],t.w)
