B.ewo=new A.b(B.h,["Fed balance sheet, net liquidity and M2 impulse, read against growth stocks.","\uc5f0\uc900 \ub300\ucc28\ub300\uc870\ud45c, \uc21c\uc720\ub3d9\uc131, M2 \ubcc0\ud654\ub97c \uc131\uc7a5\uc8fc\uc640 \ube44\uad50\ud574 \ubd10\uc694."],t.w)
B.eyb=new A.b(B.h,['"Don\'t fight the Fed." When the central bank adds money to the system (bond buying, a falling Treasury account or reverse repo), risk assets have tended to rise, with growth stocks most sensitive. When liquidity drains, the tide goes out.',"'\uc5f0\uc900\uacfc \uc2f8\uc6b0\uc9c0 \ub9c8\ub77c.' \uc911\uc559\uc740\ud589\uc774 \uc2dc\uc7a5\uc5d0 \ub3c8\uc744 \ub354\ud558\uba74(\ucc44\uad8c \ub9e4\uc785, \uad6d\uace0 \uacc4\uc88c\ub098 \uc5ed\ub808\ud3ec \uac10\uc18c) \uc704\ud5d8 \uc790\uc0b0\uc774 \uc624\ub974\ub294 \uacbd\ud5a5\uc774 \uc788\uc5c8\uace0, \uc131\uc7a5\uc8fc\uac00 \uac00\uc7a5 \ubbfc\uac10\ud588\uc5b4\uc694. \uc720\ub3d9\uc131\uc774 \ube60\uc9c0\uba74 \ubc00\ubb3c\uc774 \ube60\uc838\ub098\uac00\uc694."],t.w)
B.ekT=new A.b(B.h,["Net liquidity (2\xd7), its impulse, M2 level and impulse, bank credit and the 50/200 regime.","\uc21c\uc720\ub3d9\uc131(2\ubc30)\uacfc \uadf8 \ubcc0\ud654 \uc18d\ub3c4, M2 \uc218\uc900\uacfc \ubcc0\ud654 \uc18d\ub3c4, \uc740\ud589 \uc2e0\uc6a9, 50/200 \uad6d\uba74\uc744 \uc368\uc694."],t.w)
B.eLj=new A.b(B.h,["Fed total assets and M2 money supply.","\uc5f0\uc900 \ucd1d\uc790\uc0b0\uacfc M2 \ud1b5\ud654\ub7c9\uc774\uc5d0\uc694."],t.w)
B.en4=new A.b(B.h,["The Nasdaq-100 (QQQ) on the price chart: the most liquidity-sensitive large index.","\uac00\uaca9 \ucc28\ud2b8 \uc704\uc758 \ub098\uc2a4\ub2e5 100(QQQ)\uc774\uc5d0\uc694. \uc720\ub3d9\uc131\uc5d0 \uac00\uc7a5 \ubbfc\uac10\ud55c \ub300\ud615 \uc9c0\uc218\uc608\uc694."],t.w)
B.eHz=new A.b(B.h,["A one-year regression channel on price.","\uac00\uaca9\uc758 1\ub144 \ud68c\uadc0 \ucc44\ub110\uc774\uc5d0\uc694."],t.w)
B.eZX=new A.b(B.h,["Turning points in the impulse votes tend to lead. A composite that rolls over while QQQ is still at the top of its channel is the early warning.","\ubcc0\ud654 \uc18d\ub3c4 \uc2e0\ud638\uc758 \uc804\ud658\uc810\uc774 \uba3c\uc800 \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694. QQQ\uac00 \ucc44\ub110 \uc0c1\ub2e8\uc5d0 \uc788\ub294\ub370 \uc885\ud569 \uc810\uc218\uac00 \uaebe\uc774\uba74 \uc774\ub978 \uacbd\uace0\uc608\uc694."],t.w)
B.eRQ=new A.b(B.h,["Quantitative-easing eras (2009\u20132014, 2020\u201321) and the 2022 tightening.","\uc591\uc801 \uc644\ud654 \uc2dc\uae30(2009~2014\ub144, 2020~21\ub144)\uc640 2022\ub144 \uae34\ucd95\uae30\uc5d0 \uc798 \ub9de\uc544\uc694."],t.w)
B.eMg=new A.b(B.h,["When earnings or other forces dominate: in 2023 stocks rose while the Fed shrank its balance sheet.","\uc2e4\uc801\uc774\ub098 \ub2e4\ub978 \uc694\uc778\uc774 \uc2dc\uc7a5\uc744 \uc88c\uc6b0\ud560 \ub54c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694. 2023\ub144\uc5d0\ub294 \uc5f0\uc900\uc774 \ub300\ucc28\ub300\uc870\ud45c\ub97c \uc904\uc600\ub294\ub370\ub3c4 \uc8fc\uc2dd\uc774 \uc62c\ub790\uc5b4\uc694."],t.w)
