B.aSj=new A.b(B.h,["Crisis Hedge: Credit Stress","\uc704\uae30 \ud5e4\uc9c0: \uc2e0\uc6a9 \ubd88\uc548"],t.w)
B.eew=new A.b(B.h,["High-yield spreads, financial conditions and VIX, with Treasuries as the hedge.","\ud558\uc774\uc77c\ub4dc \uc2a4\ud504\ub808\ub4dc, \uae08\uc735 \uc5ec\uac74, VIX\ub97c \ubcf4\uace0 \ubbf8\uad6d \uad6d\ucc44\ub85c \ud5e4\uc9c0\ud574\uc694."],t.w)
B.eCB=new A.b(B.h,["In a crisis, investors sell risky debt and buy government bonds (flight to quality). This stack measures stress directly (spreads, the Chicago Fed's financial conditions index, VIX) and shows whether long Treasuries are doing their hedging job.","\uc704\uae30\uc5d0\ub294 \ud22c\uc790\uc790\ub4e4\uc774 \uc704\ud5d8\ud55c \ucc44\uad8c\uc744 \ud314\uace0 \uad6d\ucc44\ub97c \uc0ac\uc694(\uc548\uc804 \uc790\uc0b0 \uc120\ud638). \uc774 \uad6c\uc131\uc740 \uc2a4\ud2b8\ub808\uc2a4\ub97c \uc9c1\uc811 \uc7ac\uc694(\uc2a4\ud504\ub808\ub4dc, \uc2dc\uce74\uace0 \uc5f0\uc900\uc758 \uae08\uc735 \uc5ec\uac74 \uc9c0\uc218, VIX). \uadf8\ub9ac\uace0 \uc7a5\uae30 \uad6d\ucc44\uac00 \ubc29\uc5b4 \uc5ed\ud560\uc744 \ud558\uace0 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc918\uc694."],t.w)
B.eSo=new A.b(B.h,["High-yield spread (2\xd7), the credit curve, financial conditions, HYG/LQD and VIX. Negative = stress building. Recession bands shown.","\ud558\uc774\uc77c\ub4dc \uc2a4\ud504\ub808\ub4dc(2\ubc30), \uc2e0\uc6a9 \uace1\uc120, \uae08\uc735 \uc5ec\uac74, HYG/LQD, VIX\ub97c \uc368\uc694. \uc74c\uc218\ub294 \uc2a4\ud2b8\ub808\uc2a4\uac00 \uc313\uc774\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \uacbd\uae30 \uce68\uccb4 \uad6c\uac04\ub3c4 \ud45c\uc2dc\ud574\uc694."],t.w)
B.eqA=new A.b(B.h,["The ICE BofA high-yield option-adjusted spread. Spikes = credit panic.","ICE BofA \ud558\uc774\uc77c\ub4dc \uc635\uc158 \uc870\uc815 \uc2a4\ud504\ub808\ub4dc\uc608\uc694. \uae09\ub4f1\uc740 \uc2e0\uc6a9 \uacf5\ud669\uc744 \ub73b\ud574\uc694."],t.w)
B.eAo=new A.b(B.h,["Long Treasuries (TLT) on the price chart: the classic crisis hedge.","\uac00\uaca9 \ucc28\ud2b8 \uc704\uc758 \uc7a5\uae30 \uad6d\ucc44(TLT)\uc608\uc694. \uc804\ud1b5\uc801\uc778 \uc704\uae30 \ub300\ube44 \uc218\ub2e8\uc774\uc5d0\uc694."],t.w)
B.eS5=new A.b(B.h,["Half-year correlation of price with TLT. Negative = bonds are hedging; positive = both falling together (no hedge).","\uac00\uaca9\uacfc TLT\uc758 6\uac1c\uc6d4 \uc0c1\uad00\uad00\uacc4\uc608\uc694. \uc74c\uc218\uba74 \ucc44\uad8c\uc774 \uc704\ud5d8\uc744 \ub9c9\uc544 \uc8fc\uace0, \uc591\uc218\uba74 \ub458 \ub2e4 \ud568\uaed8 \ub5a8\uc5b4\uc838\uc11c \ubc29\uc5b4\uac00 \uc548 \ub3fc\uc694."],t.w)
B.eD5=new A.b(B.h,["Act on the combination: composite below zero, spread panel rising, and the stock\u2013bond correlation still negative means Treasuries should cushion the fall. A positive correlation is the 2022 warning: the hedge isn't working.","\uc870\ud569\uc73c\ub85c \ud310\ub2e8\ud558\uc138\uc694. \uc885\ud569 \uc810\uc218\uac00 0 \uc544\ub798\uc774\uace0, \uc2a4\ud504\ub808\ub4dc \ud328\ub110\uc774 \uc624\ub974\uace0, \uc8fc\uc2dd\uacfc \ucc44\uad8c\uc758 \uc0c1\uad00\uad00\uacc4\uac00 \uc544\uc9c1 \uc74c\uc218\uc774\uba74 \uad6d\ucc44\uac00 \ud558\ub77d\uc744 \uc644\ucda9\ud574 \uc904 \uac70\uc608\uc694. \uc0c1\uad00\uad00\uacc4\uac00 \uc591\uc218\ub85c \ubc14\ub00c\uba74 2022\ub144 \uac19\uc740 \uacbd\uace0\uc608\uc694. \ubc29\uc5b4\uac00 \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694."],t.w)
B.eVK=new A.b(B.h,["Credit crises and deflationary shocks: 2008, early 2020.","\uc2e0\uc6a9 \uc704\uae30\uc640 \ub514\ud50c\ub808\uc774\uc158 \ucda9\uaca9\uc5d0\uc11c \uc798 \ub9de\uc544\uc694. 2008\ub144, 2020\ub144 \ucd08\uac00 \uadf8 \uc608\uc608\uc694."],t.w)
B.eBo=new A.b(B.h,["Inflation shocks, where bonds and stocks fall together, and quick stress spikes that reverse within days.","\ucc44\uad8c\uacfc \uc8fc\uc2dd\uc774 \ud568\uaed8 \ub5a8\uc5b4\uc9c0\ub294 \uc778\ud50c\ub808\uc774\uc158 \ucda9\uaca9, \uadf8\ub9ac\uace0 \uba70\uce60 \uc548\uc5d0 \ub418\ub3cc\ub824\uc9c0\ub294 \uc9e7\uc740 \uc2a4\ud2b8\ub808\uc2a4 \uae09\ub4f1\uc5d0\uc11c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694."],t.w)
B.eqm=new A.b(B.h,["TLT is a market symbol; spreads and conditions are FRED data.","TLT\ub294 \uc2dc\uc7a5 \uc885\ubaa9\uc774\uace0, \uc2a4\ud504\ub808\ub4dc\uc640 \uae08\uc735 \uc5ec\uac74\uc740 FRED \ub370\uc774\ud130\uc608\uc694."],t.w)
B.aRz=new A.b(B.h,["Risk-On / Risk-Off Ratios","\uc704\ud5d8 \uc120\ud638 / \ud68c\ud53c \ube44\uc728"],t.w)
B.eqf=new A.b(B.h,["Discretionary\xf7staples and copper\xf7gold ratio charts voting on risk appetite.","\uacbd\uae30\uc18c\ube44\uc7ac\xf7\ud544\uc218\uc18c\ube44\uc7ac, \uad6c\ub9ac\xf7\uae08 \ube44\uc728 \ucc28\ud2b8\uac00 \uc704\ud5d8 \uc120\ud638\ub3c4\ub97c \ud22c\ud45c\ud574\uc694."],t.w)
B.eLl=new A.b(B.h,['Ratio charts strip out the overall market and show preference. When consumers\' "wants" (discretionary) beat their "needs" (staples), and industrial copper beats safe-haven gold, investors are leaning into growth. Both ratios turning down is a defensive rotation.',"\ube44\uc728 \ucc28\ud2b8\ub294 \uc2dc\uc7a5 \uc804\uccb4\uc758 \uc6c0\uc9c1\uc784\uc744 \uac77\uc5b4 \ub0b4\uace0 \uc120\ud638\ub3c4\ub97c \ubcf4\uc5ec \uc918\uc694. \uc18c\ube44\uc790\uc758 '\uc6d0\ud558\ub294 \uac83'(\uacbd\uae30\uc18c\ube44\uc7ac)\uc774 '\ud544\uc694\ud55c \uac83'(\ud544\uc218\uc18c\ube44\uc7ac)\uc744 \uc55e\uc11c\uace0, \uc0b0\uc5c5\uc6a9 \uad6c\ub9ac\uac00 \uc548\uc804 \uc790\uc0b0\uc778 \uae08\uc744 \uc55e\uc11c\uba74 \ud22c\uc790\uc790\ub4e4\uc774 \uc131\uc7a5\uc5d0 \uae30\ub300\uace0 \uc788\ub294 \uac70\uc608\uc694. \ub450 \ube44\uc728\uc774 \ud568\uaed8 \ub0b4\ub824\uac00\uba74 \ubc29\uc5b4\uc801\uc778 \uc21c\ud658\uc774\uc5d0\uc694."],t.w)
