B.ewK=new A.b(B.h,["One number from \u2212100 to +100 that ranks the rows. Higher = stronger trend and momentum, nearer the high, calmer.","\ud589\uc744 \uc904 \uc138\uc6b0\ub294 \u2212100~+100\uc758 \uc22b\uc790 \ud558\ub098\uc608\uc694. \ub192\uc744\uc218\ub85d \ucd94\uc138\uc640 \ubaa8\uba58\ud140\uc774 \uac15\ud558\uace0, \uace0\uc810\uc5d0 \uac00\uae5d\uace0, \ub354 \uc548\uc815\uc801\uc774\uc5d0\uc694."],t.w)
B.eIg=new A.b(B.h,["Weighted mean of five parts, each scaled to \u22121..+1: relative strength (13w \xf7 10%, 26w \xf7 15%), 12-1 momentum \xf7 25%, trend (\xb11), near-high (0% = +1, 20% below = \u22121), calm (0% = +1, 40% a year = \u22121). You can change the weights in Edit scan.","\ub2e4\uc12f \ubd80\ubd84\uc744 \uac01\uac01 \u22121~+1\ub85c \ud658\uc0b0\ud55c \uac00\uc911 \ud3c9\uade0\uc774\uc5d0\uc694: \uc0c1\ub300 \uac15\ub3c4(13\uc8fc \xf7 10%, 26\uc8fc \xf7 15%), 12-1 \ubaa8\uba58\ud140 \xf7 25%, \ucd94\uc138(\xb11), \uace0\uc810 \uadfc\uc811\ub3c4(0% = +1, 20% \uc544\ub798 = \u22121), \uc548\uc815\uc131(0% = +1, \uc5f0 40% = \u22121). \uac00\uc911\uce58\ub294 \uc2a4\uce94 \ud3b8\uc9d1\uc5d0\uc11c \ubc14\uafc0 \uc218 \uc788\uc5b4\uc694."],t.w)
