B.exa=new A.b(B.h,["mean ETF score + regime tilt; \u2265 +20 Favoured, \u2264 \u221220 Avoid, else Neutral. Tilts: stress \u2014 equities \u221215, credit \u221220, bonds +15, commodities \u221210, dollar +10, crypto \u221215, real estate \u221210; slowdown \u2014 equities \u221210, credit \u221210, bonds +15, commodities \u221210, real estate \u22125; late cycle \u2014 equities \u22125, bonds \u22125, commodities +10; expansion \u2014 equities +10, credit +5, commodities +5, bonds \u221210, dollar \u22125, crypto +5.","ETF \uc810\uc218 \ud3c9\uade0 + \uad6d\uba74 \uae30\uc6b8\uae30\uc608\uc694. \u2265 +20\uc774\uba74 \uc720\ub9ac, \u2264 \u221220\uc774\uba74 \ud68c\ud53c, \uadf8 \uc678\ub294 \uc911\ub9bd\uc774\uc5d0\uc694. \uae30\uc6b8\uae30: \uae34\uc7a5 \u2014 \uc8fc\uc2dd \u221215, \uc2e0\uc6a9 \u221220, \ucc44\uad8c +15, \uc6d0\uc790\uc7ac \u221210, \ub2ec\ub7ec +10, \uc554\ud638\ud654\ud3d0 \u221215, \ubd80\ub3d9\uc0b0 \u221210; \ub454\ud654 \u2014 \uc8fc\uc2dd \u221210, \uc2e0\uc6a9 \u221210, \ucc44\uad8c +15, \uc6d0\uc790\uc7ac \u221210, \ubd80\ub3d9\uc0b0 \u22125; \uc0ac\uc774\ud074 \ud6c4\ubc18 \u2014 \uc8fc\uc2dd \u22125, \ucc44\uad8c \u22125, \uc6d0\uc790\uc7ac +10; \ud655\uc7a5 \u2014 \uc8fc\uc2dd +10, \uc2e0\uc6a9 +5, \uc6d0\uc790\uc7ac +5, \ucc44\uad8c \u221210, \ub2ec\ub7ec \u22125, \uc554\ud638\ud654\ud3d0 +5."],t.w)
B.eDA=new A.b(B.h,["The tilt table is a simple rule of thumb, kept small on purpose. With no live macro readings there is no tilt.","\uae30\uc6b8\uae30 \ud45c\ub294 \uc77c\ubd80\ub7ec \uc791\uac8c \uc720\uc9c0\ud55c \uac04\ub2e8\ud55c \uacbd\ud5d8\uce59\uc774\uc5d0\uc694. \uc2e4\uc2dc\uac04 \uac70\uc2dc \ud310\ub3c5\uc774 \uc5c6\uc73c\uba74 \uae30\uc6b8\uae30\ub3c4 \uc5c6\uc5b4\uc694."],t.w)
