B.fvh=new A.b(B.m,["Restore save point?","\xbfRestaurar punto de guardado?","Restaurer ce point de sauvegarde ?","Speicherpunkt wiederherstellen?","Ripristinare il punto di salvataggio?","Restaurar ponto de salvamento?","Opslagpunt herstellen?","\xc5terst\xe4ll sparpunkt?","Obnovit ulo\u017een\xfd bod?","\u0395\u03c0\u03b1\u03bd\u03b1\u03c6\u03bf\u03c1\u03ac \u03c3\u03b7\u03bc\u03b5\u03af\u03bf\u03c5 \u03b1\u03c0\u03bf\u03b8\u03ae\u03ba\u03b5\u03c5\u03c3\u03b7\u03c2;","Przywr\xf3ci\u0107 punkt zapisu?","\u0412\u0456\u0434\u043d\u043e\u0432\u0438\u0442\u0438 \u0442\u043e\u0447\u043a\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f?","\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0442\u043e\u0447\u043a\u0443 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f?","Kay\u0131t noktas\u0131 geri y\xfcklensin mi?","Kh\xf4i ph\u1ee5c \u0111i\u1ec3m l\u01b0u?","\uc800\uc7a5 \uc9c0\uc810\uc744 \ubcf5\uc6d0\ud560\uae4c\uc694?","\u30bb\u30fc\u30d6\u30dd\u30a4\u30f3\u30c8\u3092\u5fa9\u5143\u3057\u307e\u3059\u304b?","\u8981\u6062\u590d\u5b58\u6863\u70b9\u5417\uff1f","\u0647\u0644 \u062a\u0631\u064a\u062f \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0646\u0642\u0637\u0629 \u0627\u0644\u062d\u0641\u0638\u061f","\u0915\u094d\u092f\u093e \u0938\u0947\u0935 \u092a\u0949\u0907\u0902\u091f \u092a\u0941\u0928\u0930\u094d\u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0915\u0930\u0947\u0902?","\u0646\u0642\u0637\u0647 \u0630\u062e\u06cc\u0631\u0647 \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u0634\u0648\u062f\u061f"],t.w)
B.fgs=new A.b(B.m,['Replaces this applet\'s CURRENT definition and data with "{label}" ({ts}).\n\nAn automatic save point of the current state is taken first, so this restore is itself reversible.','Reemplaza la definici\xf3n y los datos ACTUALES de esta app con "{label}" ({ts}).\n\nPrimero se toma autom\xe1ticamente un punto de guardado del estado actual, por lo que esta restauraci\xf3n tambi\xe9n se puede deshacer.',"Remplace la d\xe9finition et les donn\xe9es ACTUELLES de cet applet par \xab {label} \xbb ({ts}).\n\nUn point de sauvegarde automatique de l'\xe9tat actuel est pris en premier, donc cette restauration est elle-m\xeame r\xe9versible.","Ersetzt die AKTUELLE Definition und Daten dieser App durch \u201e{label}\u201c ({ts}).\n\nZuerst wird automatisch ein Speicherpunkt des aktuellen Zustands erstellt, sodass diese Wiederherstellung selbst r\xfcckg\xe4ngig gemacht werden kann.",'Sostituisce la definizione e i dati ATTUALI di quest\'app con "{label}" ({ts}).\n\nViene prima creato automaticamente un punto di salvataggio dello stato attuale, quindi questo ripristino \xe8 a sua volta reversibile.','Substitui a defini\xe7\xe3o e os dados ATUAIS deste aplicativo por "{label}" ({ts}).\n\nUm ponto de salvamento autom\xe1tico do estado atual \xe9 feito primeiro, ent\xe3o esta restaura\xe7\xe3o \xe9 revers\xedvel.','Vervangt de HUIDIGE definitie en gegevens van deze app door "{label}" ({ts}).\n\nEr wordt eerst automatisch een opslagpunt van de huidige status gemaakt, zodat dit herstel zelf ook omkeerbaar is.','Ers\xe4tter denna apps AKTUELLA definition och data med "{label}" ({ts}).\n\nEn automatisk sparpunkt av det aktuella tillst\xe5ndet tas f\xf6rst, s\xe5 den h\xe4r \xe5terst\xe4llningen \xe4r i sig reversibel.',"Nahrad\xed AKTU\xc1LN\xcd definici a data t\xe9to aplikace bodem \u201e{label}\u201c ({ts}).\n\nNejprve se automaticky vytvo\u0159\xed ulo\u017een\xfd bod aktu\xe1ln\xedho stavu, tak\u017ee i toto obnoven\xed lze vr\xe1tit zp\u011bt.",'\u0391\u03bd\u03c4\u03b9\u03ba\u03b1\u03b8\u03b9\u03c3\u03c4\u03ac \u03c4\u03bf\u03bd \u03a4\u03a1\u0395\u03a7\u039f\u039d\u03a4\u0391 \u03bf\u03c1\u03b9\u03c3\u03bc\u03cc \u03ba\u03b1\u03b9 \u03c4\u03b1 \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1 \u03b1\u03c5\u03c4\u03ae\u03c2 \u03c4\u03b7\u03c2 \u03b5\u03c6\u03b1\u03c1\u03bc\u03bf\u03b3\u03ae\u03c2 \u03bc\u03b5 "{label}" ({ts}).\n\n\u03a0\u03c1\u03ce\u03c4\u03b1 \u03bb\u03b1\u03bc\u03b2\u03ac\u03bd\u03b5\u03c4\u03b1\u03b9 \u03b1\u03c5\u03c4\u03cc\u03bc\u03b1\u03c4\u03b1 \u03ad\u03bd\u03b1 \u03c3\u03b7\u03bc\u03b5\u03af\u03bf \u03b1\u03c0\u03bf\u03b8\u03ae\u03ba\u03b5\u03c5\u03c3\u03b7\u03c2 \u03c4\u03b7\u03c2 \u03c4\u03c1\u03ad\u03c7\u03bf\u03c5\u03c3\u03b1\u03c2 \u03ba\u03b1\u03c4\u03ac\u03c3\u03c4\u03b1\u03c3\u03b7\u03c2, \u03bf\u03c0\u03cc\u03c4\u03b5 \u03ba\u03b1\u03b9 \u03b1\u03c5\u03c4\u03ae \u03b7 \u03b5\u03c0\u03b1\u03bd\u03b1\u03c6\u03bf\u03c1\u03ac \u03b5\u03af\u03bd\u03b1\u03b9 \u03b1\u03bd\u03b1\u03c3\u03c4\u03c1\u03ad\u03c8\u03b9\u03bc\u03b7.',"Zast\u0119puje AKTUALN\u0104 definicj\u0119 i dane tej aplikacji punktem \u201e{label}\u201d ({ts}).\n\nNajpierw automatycznie tworzony jest punkt zapisu bie\u017c\u0105cego stanu, wi\u0119c to przywr\xf3cenie r\xf3wnie\u017c mo\u017cna cofn\u0105\u0107.","\u0417\u0430\u043c\u0456\u043d\u044e\u0454 \u041f\u041e\u0422\u041e\u0427\u041d\u0415 \u0432\u0438\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u0442\u0430 \u0434\u0430\u043d\u0456 \u0446\u044c\u043e\u0433\u043e \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u0443 \u043d\u0430 \xab{label}\xbb ({ts}).\n\n\u0421\u043f\u043e\u0447\u0430\u0442\u043a\u0443 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e \u0441\u0442\u0432\u043e\u0440\u044e\u0454\u0442\u044c\u0441\u044f \u0442\u043e\u0447\u043a\u0430 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u043f\u043e\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0441\u0442\u0430\u043d\u0443, \u0442\u043e\u0436 \u0446\u0435 \u0432\u0456\u0434\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0442\u0435\u0436 \u043c\u043e\u0436\u043d\u0430 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438.","\u0417\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u0422\u0415\u041a\u0423\u0429\u0415\u0415 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0438 \u0434\u0430\u043d\u043d\u044b\u0435 \u044d\u0442\u043e\u0433\u043e \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043d\u0430 \xab{label}\xbb ({ts}).\n\n\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0441\u043e\u0437\u0434\u0430\u0451\u0442\u0441\u044f \u0442\u043e\u0447\u043a\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u044d\u0442\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0442\u043e\u0436\u0435 \u043e\u0431\u0440\u0430\u0442\u0438\u043c\u043e.",'Bu uygulaman\u0131n MEVCUT tan\u0131m\u0131n\u0131 ve verilerini "{label}" ({ts}) ile de\u011fi\u015ftirir.\n\n\xd6nce mevcut durumun otomatik bir kay\u0131t noktas\u0131 al\u0131n\u0131r, b\xf6ylece bu geri y\xfckleme de geri al\u0131nabilir.','Thay th\u1ebf \u0111\u1ecbnh ngh\u0129a v\xe0 d\u1eef li\u1ec7u HI\u1ec6N T\u1ea0I c\u1ee7a \u1ee9ng d\u1ee5ng n\xe0y b\u1eb1ng "{label}" ({ts}).\n\nM\u1ed9t \u0111i\u1ec3m l\u01b0u t\u1ef1 \u0111\u1ed9ng c\u1ee7a tr\u1ea1ng th\xe1i hi\u1ec7n t\u1ea1i s\u1ebd \u0111\u01b0\u1ee3c t\u1ea1o tr\u01b0\u1edbc, v\xec v\u1eady vi\u1ec7c kh\xf4i ph\u1ee5c n\xe0y c\u0169ng c\xf3 th\u1ec3 ho\xe0n t\xe1c.','\uc774 \uc571\uc758 \ud604\uc7ac \uc815\uc758\uc640 \ub370\uc774\ud130\ub97c "{label}"({ts})\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4.\n\n\uba3c\uc800 \ud604\uc7ac \uc0c1\ud0dc\uc758 \uc790\ub3d9 \uc800\uc7a5 \uc9c0\uc810\uc774 \uc0dd\uc131\ub418\ubbc0\ub85c \uc774 \ubcf5\uc6d0 \uc790\uccb4\ub3c4 \ub418\ub3cc\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.',"\u3053\u306e\u30a2\u30d7\u30ea\u306e\u73fe\u5728\u306e\u5b9a\u7fa9\u3068\u30c7\u30fc\u30bf\u3092\u300c{label}\u300d({ts})\u306b\u7f6e\u304d\u63db\u3048\u307e\u3059\u3002\n\n\u6700\u521d\u306b\u73fe\u5728\u306e\u72b6\u614b\u306e\u81ea\u52d5\u30bb\u30fc\u30d6\u30dd\u30a4\u30f3\u30c8\u304c\u4f5c\u6210\u3055\u308c\u308b\u305f\u3081\u3001\u3053\u306e\u5fa9\u5143\u81ea\u4f53\u3082\u5143\u306b\u623b\u305b\u307e\u3059\u3002",'\u5c06\u6b64\u5e94\u7528\u5f53\u524d\u7684\u5b9a\u4e49\u548c\u6570\u636e\u66ff\u6362\u4e3a "{label}" ({ts})\u3002\n\n\u7cfb\u7edf\u4f1a\u5148\u81ea\u52a8\u4e3a\u5f53\u524d\u72b6\u6001\u521b\u5efa\u4e00\u4e2a\u5b58\u6863\u70b9\uff0c\u56e0\u6b64\u8fd9\u6b21\u6062\u590d\u672c\u8eab\u4e5f\u662f\u53ef\u64a4\u9500\u7684\u3002','\u064a\u0633\u062a\u0628\u062f\u0644 \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u0640 "{label}" ({ts}).\n\n\u064a\u062a\u0645 \u0623\u0648\u0644\u0627\u064b \u0623\u062e\u0630 \u0646\u0642\u0637\u0629 \u062d\u0641\u0638 \u062a\u0644\u0642\u0627\u0626\u064a\u0629 \u0644\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629\u060c \u0644\u0630\u0627 \u0641\u0625\u0646 \u0647\u0630\u0647 \u0627\u0644\u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0631\u0627\u062c\u0639 \u0647\u064a \u0646\u0641\u0633\u0647\u0627.','\u0907\u0938 \u0910\u092a \u0915\u0940 \u0935\u0930\u094d\u0924\u092e\u093e\u0928 \u092a\u0930\u093f\u092d\u093e\u0937\u093e \u0914\u0930 \u0921\u0947\u091f\u093e \u0915\u094b "{label}" ({ts}) \u0938\u0947 \u092c\u0926\u0932 \u0926\u0947\u0924\u093e \u0939\u0948\u0964\n\n\u092a\u0939\u0932\u0947 \u0935\u0930\u094d\u0924\u092e\u093e\u0928 \u0938\u094d\u0925\u093f\u0924\u093f \u0915\u093e \u090f\u0915 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u0938\u0947\u0935 \u092a\u0949\u0907\u0902\u091f \u0932\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u092f\u0939 \u092a\u0941\u0928\u0930\u094d\u0938\u094d\u0925\u093e\u092a\u0928 \u092d\u0940 \u0909\u0932\u091f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964',"\u062a\u0639\u0631\u06cc\u0641 \u0648 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u0641\u0639\u0644\u06cc \u0627\u06cc\u0646 \u0628\u0631\u0646\u0627\u0645\u0647 \u0631\u0627 \u0628\u0627 \xab{label}\xbb ({ts}) \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u0645\u06cc\u200c\u06a9\u0646\u062f.\n\n\u0627\u0628\u062a\u062f\u0627 \u06cc\u06a9 \u0646\u0642\u0637\u0647 \u0630\u062e\u06cc\u0631\u0647 \u062e\u0648\u062f\u06a9\u0627\u0631 \u0627\u0632 \u0648\u0636\u0639\u06cc\u062a \u0641\u0639\u0644\u06cc \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0627\u06cc\u0646 \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u0646\u06cc\u0632 \u062e\u0648\u062f \u0642\u0627\u0628\u0644 \u0628\u0627\u0632\u06af\u0634\u062a \u0627\u0633\u062a."],t.w)
