B.dZX=new A.b(B.J,["Change files without asking?","\ubb3b\uc9c0 \uc54a\uace0 \ud30c\uc77c\uc744 \ubcc0\uacbd\ud560\uae4c\uc694?","\u65e0\u9700\u8be2\u95ee\u5373\u53ef\u66f4\u6539\u6587\u4ef6\uff1f","\u092c\u093f\u0928\u093e \u092a\u0942\u091b\u0947 \u092b\u093c\u093e\u0907\u0932\u0947\u0902 \u092c\u0926\u0932\u0947\u0902?","\xbfCambiar archivos sin preguntar?","Modifier les fichiers sans demander ?","\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u062f\u0648\u0646 \u0633\u0624\u0627\u0644\u061f","Alterar arquivos sem perguntar?","\u0418\u0437\u043c\u0435\u043d\u044f\u0442\u044c \u0444\u0430\u0439\u043b\u044b \u0431\u0435\u0437 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u0432?","Dateien ohne Nachfrage \xe4ndern?","\u78ba\u8a8d\u305b\u305a\u306b\u30d5\u30a1\u30a4\u30eb\u3092\u5909\u66f4\u3057\u307e\u3059\u304b\uff1f","Dosyalar sormadan de\u011fi\u015ftirilsin mi?","Thay \u0111\u1ed5i t\u1ec7p m\xe0 kh\xf4ng c\u1ea7n h\u1ecfi?","Modificare i file senza chiedere?","\u0641\u0627\u06cc\u0644\u200c\u0647\u0627 \u0628\u062f\u0648\u0646 \u067e\u0631\u0633\u06cc\u062f\u0646 \u062a\u063a\u06cc\u06cc\u0631 \u06a9\u0646\u0646\u062f\u061f","Zmienia\u0107 pliki bez pytania?","\u0417\u043c\u0456\u043d\u044e\u0432\u0430\u0442\u0438 \u0444\u0430\u0439\u043b\u0438 \u0431\u0435\u0437 \u0437\u0430\u043f\u0438\u0442\u0443?","Bestanden wijzigen zonder te vragen?","\xc4ndra filer utan att fr\xe5ga?","M\u011bnit soubory bez ptan\xed?","\u0391\u03bb\u03bb\u03b1\u03b3\u03ae \u03b1\u03c1\u03c7\u03b5\u03af\u03c9\u03bd \u03c7\u03c9\u03c1\u03af\u03c2 \u03b5\u03c1\u03ce\u03c4\u03b7\u03c3\u03b7;"],t.w)
B.e0Q=new A.b(B.J,["Chat will create and edit files in this folder without asking first. Deleting, moving and bringing in files from elsewhere still ask. You can undo any change in Activity.","Chat\uc774 \uc774 \ud3f4\ub354\uc5d0\uc11c \uba3c\uc800 \ubb3b\uc9c0 \uc54a\uace0 \ud30c\uc77c\uc744 \ub9cc\ub4e4\uace0 \ud3b8\uc9d1\ud569\ub2c8\ub2e4. \uc0ad\uc81c, \uc774\ub3d9, \ub2e4\ub978 \uacf3\uc758 \ud30c\uc77c \uac00\uc838\uc624\uae30\ub294 \uacc4\uc18d \ubb3b\uc2b5\ub2c8\ub2e4. \ubaa8\ub4e0 \ubcc0\uacbd\uc740 \ud65c\ub3d9\uc5d0\uc11c \ub418\ub3cc\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Chat \u5c06\u5728\u6b64\u6587\u4ef6\u5939\u4e2d\u76f4\u63a5\u521b\u5efa\u548c\u7f16\u8f91\u6587\u4ef6\uff0c\u4e0d\u518d\u5148\u8be2\u95ee\u3002\u5220\u9664\u3001\u79fb\u52a8\u4ee5\u53ca\u4ece\u5176\u4ed6\u4f4d\u7f6e\u5f15\u5165\u6587\u4ef6\u4ecd\u4f1a\u8be2\u95ee\u3002\u4f60\u53ef\u4ee5\u5728\u201c\u6d3b\u52a8\u201d\u4e2d\u64a4\u9500\u4efb\u4f55\u66f4\u6539\u3002","Chat \u0907\u0938 \u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u092e\u0947\u0902 \u092a\u0939\u0932\u0947 \u092a\u0942\u091b\u0947 \u092c\u093f\u0928\u093e \u092b\u093c\u093e\u0907\u0932\u0947\u0902 \u092c\u0928\u093e\u090f\u0917\u093e \u0914\u0930 \u0938\u0902\u092a\u093e\u0926\u093f\u0924 \u0915\u0930\u0947\u0917\u093e\u0964 \u0939\u091f\u093e\u0928\u0947, \u0932\u0947 \u091c\u093e\u0928\u0947 \u0914\u0930 \u0915\u0939\u0940\u0902 \u0914\u0930 \u0938\u0947 \u092b\u093c\u093e\u0907\u0932\u0947\u0902 \u0932\u093e\u0928\u0947 \u092a\u0930 \u0905\u092c \u092d\u0940 \u092a\u0942\u091b\u093e \u091c\u093e\u090f\u0917\u093e\u0964 \u0906\u092a \u0917\u0924\u093f\u0935\u093f\u0927\u093f \u092e\u0947\u0902 \u0915\u094b\u0908 \u092d\u0940 \u092c\u0926\u0932\u093e\u0935 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964","Chat crear\xe1 y editar\xe1 archivos en esta carpeta sin preguntar antes. Eliminar, mover y traer archivos de otro lugar siguen preguntando. Puedes deshacer cualquier cambio en Actividad.","Chat cr\xe9era et modifiera des fichiers dans ce dossier sans demander d\u2019abord. Supprimer, d\xe9placer et importer des fichiers d\u2019ailleurs demandent toujours. Vous pouvez annuler toute modification dans Activit\xe9.","\u0633\u064a\u0646\u0634\u0626 Chat \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u0648\u064a\u062d\u0631\u0631\u0647\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u062c\u0644\u062f \u062f\u0648\u0646 \u0623\u0646 \u064a\u0633\u0623\u0644 \u0623\u0648\u0644\u064b\u0627. \u0627\u0644\u062d\u0630\u0641 \u0648\u0627\u0644\u0646\u0642\u0644 \u0648\u062c\u0644\u0628 \u0645\u0644\u0641\u0627\u062a \u0645\u0646 \u0645\u0643\u0627\u0646 \u0622\u062e\u0631 \u0644\u0627 \u062a\u0632\u0627\u0644 \u062a\u0633\u0623\u0644. \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0623\u064a \u062a\u063a\u064a\u064a\u0631 \u0645\u0646 \u0627\u0644\u0646\u0634\u0627\u0637.","O Chat vai criar e editar arquivos nesta pasta sem perguntar antes. Excluir, mover e trazer arquivos de outro lugar ainda perguntam. Voc\xea pode desfazer qualquer altera\xe7\xe3o em Atividade.","Chat \u0431\u0443\u0434\u0435\u0442 \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u0438 \u0440\u0435\u0434\u0430\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0444\u0430\u0439\u043b\u044b \u0432 \u044d\u0442\u043e\u0439 \u043f\u0430\u043f\u043a\u0435, \u043d\u0435 \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435. \u0423\u0434\u0430\u043b\u0435\u043d\u0438\u0435, \u043f\u0435\u0440\u0435\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u0438 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0444\u0430\u0439\u043b\u043e\u0432 \u0438\u0437\u0432\u043d\u0435 \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u044e\u0442. \u041b\u044e\u0431\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \xab\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u044f\xbb.","Chat erstellt und bearbeitet Dateien in diesem Ordner, ohne vorher zu fragen. L\xf6schen, Verschieben und Dateien von woanders hereinholen fragen weiterhin. Jede \xc4nderung kannst du in Aktivit\xe4t r\xfcckg\xe4ngig machen.","Chat \u306f\u3053\u306e\u30d5\u30a9\u30eb\u30c0\u30fc\u5185\u306e\u30d5\u30a1\u30a4\u30eb\u3092\u5148\u306b\u78ba\u8a8d\u305b\u305a\u306b\u4f5c\u6210\u30fb\u7de8\u96c6\u3057\u307e\u3059\u3002\u524a\u9664\u3001\u79fb\u52d5\u3001\u4ed6\u306e\u5834\u6240\u304b\u3089\u306e\u30d5\u30a1\u30a4\u30eb\u53d6\u308a\u8fbc\u307f\u306f\u5f15\u304d\u7d9a\u304d\u78ba\u8a8d\u3057\u307e\u3059\u3002\u5909\u66f4\u306f\u30a2\u30af\u30c6\u30a3\u30d3\u30c6\u30a3\u304b\u3089\u3044\u3064\u3067\u3082\u5143\u306b\u623b\u305b\u307e\u3059\u3002","Chat bu klas\xf6rde \xf6nce sormadan dosya olu\u015fturup d\xfczenleyecek. Silme, ta\u015f\u0131ma ve ba\u015fka yerden dosya getirme yine sorar. Herhangi bir de\u011fi\u015fikli\u011fi Etkinlik'ten geri alabilirsiniz.","Chat s\u1ebd t\u1ea1o v\xe0 ch\u1ec9nh s\u1eeda t\u1ec7p trong th\u01b0 m\u1ee5c n\xe0y m\xe0 kh\xf4ng h\u1ecfi tr\u01b0\u1edbc. X\xf3a, di chuy\u1ec3n v\xe0 \u0111\u01b0a t\u1ec7p t\u1eeb n\u01a1i kh\xe1c v\xe0o v\u1eabn h\u1ecfi. B\u1ea1n c\xf3 th\u1ec3 ho\xe0n t\xe1c m\u1ecdi thay \u0111\u1ed5i trong Ho\u1ea1t \u0111\u1ed9ng.","Chat creer\xe0 e modificher\xe0 i file in questa cartella senza chiedere prima. Eliminare, spostare e portare file da altrove chiedono ancora. Puoi annullare qualsiasi modifica in Attivit\xe0.","Chat \u062f\u0631 \u0627\u06cc\u0646 \u067e\u0648\u0634\u0647 \u0628\u062f\u0648\u0646 \u067e\u0631\u0633\u06cc\u062f\u0646 \u0641\u0627\u06cc\u0644 \u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u0648\u06cc\u0631\u0627\u06cc\u0634 \u0645\u06cc\u200c\u06a9\u0646\u062f. \u062d\u0630\u0641\u060c \u062c\u0627\u0628\u0647\u200c\u062c\u0627\u06cc\u06cc \u0648 \u0622\u0648\u0631\u062f\u0646 \u0641\u0627\u06cc\u0644 \u0627\u0632 \u062c\u0627\u06cc \u062f\u06cc\u06af\u0631 \u0647\u0645\u0686\u0646\u0627\u0646 \u0645\u06cc\u200c\u067e\u0631\u0633\u062f. \u0647\u0631 \u062a\u063a\u06cc\u06cc\u0631\u06cc \u0631\u0627 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u062f\u0631 \u0641\u0639\u0627\u0644\u06cc\u062a \u0648\u0627\u06af\u0631\u062f \u06a9\u0646\u06cc\u062f.","Chat b\u0119dzie tworzy\u0107 i edytowa\u0107 pliki w tym folderze bez pytania. Usuwanie, przenoszenie i dodawanie plik\xf3w z innych miejsc nadal pyta. Ka\u017cd\u0105 zmian\u0119 mo\u017cesz cofn\u0105\u0107 w Aktywno\u015bci.","Chat \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438\u043c\u0435 \u0439 \u0440\u0435\u0434\u0430\u0433\u0443\u0432\u0430\u0442\u0438\u043c\u0435 \u0444\u0430\u0439\u043b\u0438 \u0432 \u0446\u0456\u0439 \u043f\u0430\u043f\u0446\u0456, \u043d\u0435 \u043f\u0438\u0442\u0430\u044e\u0447\u0438 \u043d\u0430\u043f\u0435\u0440\u0435\u0434. \u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f, \u043f\u0435\u0440\u0435\u043c\u0456\u0449\u0435\u043d\u043d\u044f \u0442\u0430 \u0434\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f \u0444\u0430\u0439\u043b\u0456\u0432 \u0437 \u0456\u043d\u0448\u0438\u0445 \u043c\u0456\u0441\u0446\u044c \u0456 \u0434\u0430\u043b\u0456 \u0437\u0430\u043f\u0438\u0442\u0443\u044e\u0442\u044c. \u0411\u0443\u0434\u044c-\u044f\u043a\u0443 \u0437\u043c\u0456\u043d\u0443 \u043c\u043e\u0436\u043d\u0430 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0443 \xab\u0414\u0456\u044f\u0445\xbb.","Chat maakt en bewerkt bestanden in deze map zonder eerst te vragen. Verwijderen, verplaatsen en bestanden van elders binnenhalen vragen nog steeds. Je kunt elke wijziging ongedaan maken in Activiteit.","Chat skapar och redigerar filer i den h\xe4r mappen utan att fr\xe5ga f\xf6rst. Radering, flytt och att h\xe4mta in filer fr\xe5n annat h\xe5ll fr\xe5gar fortfarande. Du kan \xe5ngra varje \xe4ndring i Aktivitet.","Chat bude v t\xe9to slo\u017ece vytv\xe1\u0159et a upravovat soubory bez p\u0159edchoz\xedho ptan\xed. Maz\xe1n\xed, p\u0159esun a p\u0159id\xe1n\xed soubor\u016f odjinud se st\xe1le ptaj\xed. Ka\u017edou zm\u011bnu m\u016f\u017eete vr\xe1tit v Aktivit\u011b.","\u03a4\u03bf Chat \u03b8\u03b1 \u03b4\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03b5\u03af \u03ba\u03b1\u03b9 \u03b8\u03b1 \u03b5\u03c0\u03b5\u03be\u03b5\u03c1\u03b3\u03ac\u03b6\u03b5\u03c4\u03b1\u03b9 \u03b1\u03c1\u03c7\u03b5\u03af\u03b1 \u03c3\u03b5 \u03b1\u03c5\u03c4\u03cc\u03bd \u03c4\u03bf\u03bd \u03c6\u03ac\u03ba\u03b5\u03bb\u03bf \u03c7\u03c9\u03c1\u03af\u03c2 \u03bd\u03b1 \u03c1\u03c9\u03c4\u03ac \u03c0\u03c1\u03ce\u03c4\u03b1. \u0397 \u03b4\u03b9\u03b1\u03b3\u03c1\u03b1\u03c6\u03ae, \u03b7 \u03bc\u03b5\u03c4\u03b1\u03ba\u03af\u03bd\u03b7\u03c3\u03b7 \u03ba\u03b1\u03b9 \u03b7 \u03b5\u03b9\u03c3\u03b1\u03b3\u03c9\u03b3\u03ae \u03b1\u03c1\u03c7\u03b5\u03af\u03c9\u03bd \u03b1\u03c0\u03cc \u03b1\u03bb\u03bb\u03bf\u03cd \u03c1\u03c9\u03c4\u03bf\u03cd\u03bd \u03b1\u03ba\u03cc\u03bc\u03b1. \u039c\u03c0\u03bf\u03c1\u03b5\u03af\u03c4\u03b5 \u03bd\u03b1 \u03b1\u03bd\u03b1\u03b9\u03c1\u03ad\u03c3\u03b5\u03c4\u03b5 \u03ba\u03ac\u03b8\u03b5 \u03b1\u03bb\u03bb\u03b1\u03b3\u03ae \u03c3\u03c4\u03b7 \u0394\u03c1\u03b1\u03c3\u03c4\u03b7\u03c1\u03b9\u03cc\u03c4\u03b7\u03c4\u03b1."],t.w)
