B.egl=new A.b(B.h,["",'{"up":"\uace1\uc120\uc774 \uac00\ud314\ub77c\uc9c0\uace0 \uc788\uc5b4\uc694. \uc7a5\uae30 \uae08\ub9ac\uac00 \ub2e8\uae30\ubcf4\ub2e4 \ube60\ub974\uac8c \uc624\ub974\ub294 \uac70\uc608\uc694. \uc5ed\uc804 \uc774\ud6c4\uc5d0\ub294 \ubcf4\ud1b5 \uc5f0\uc900\uc774 \uae08\ub9ac\ub97c \ub0b4\ub9ac\uba74\uc11c \ub098\ud0c0\ub098\uace0, \uacbd\uae30 \ub454\ud654 \uc2dc\uc791 \ubb34\ub835\uc5d0 \uc624\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544\uc694.","down":"\uace1\uc120\uc774 \ud3c9\ud3c9\ud574\uc9c0\uace0 \uc788\uace0, 0 \uc544\ub798\uba74 \uc5ed\uc804\ub41c \uac70\uc608\uc694. \uc2dc\uc7a5\uc774 \uc9c0\uae08\uc740 \uae34\ucd95, \ub098\uc911\uc5d0\ub294 \uc57d\ud55c \uc131\uc7a5\uc744 \ubcf4\uace0 \uc788\uc5b4\uc694.","upShort":"\uace1\uc120 \uac00\ud314\ub77c\uc9d0 \u2014 \uae08\ub9ac \uc778\ud558\uac00 \uc624\uba74\uc11c \uc5ed\uc804 \ub4a4\uc5d0 \uc790\uc8fc \ub098\ud0c0\ub098\uc694.","downShort":"\uace1\uc120\uc774 \ud3c9\ud3c9\ud574\uc9c0\uba70 \uc5ed\uc804 \ucabd\uc73c\ub85c, \ub610\ub294 \ub354 \uae4a\uc740 \uc5ed\uc804\uc73c\ub85c \uac00\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uace1\uc120\uc740 \uc815\uc0c1\uc801\uc778 \uc6b0\uc0c1\ud5a5 \ubaa8\uc591\uc774\uc5d0\uc694. \uc2dc\uc7a5\uc774 \uac00\uae4c\uc6b4 \uc2dc\uc77c\uc758 \ubb38\uc81c\ub97c \uc54c\ub9ac\uace0 \uc788\uc9c0 \uc54a\uc544\uc694.","watch":"{v}\uc5d0\uc11c \uace1\uc120\uc774 \uac70\uc758 \ud3c9\ud3c9\ud574\uc694. \ub2e8\uae30 \uae08\ub9ac\uac00 \uc7a5\uae30 \uae08\ub9ac\ub97c \ub118\uc5b4\uc11c\ub294 \uc9c0\uc810\uc5d0 \uac00\uae4c\uc6cc\uc694.","stress":"{v}\uc5d0\uc11c \uace1\uc120\uc774 \uc5ed\uc804\ub3fc \uc788\uc5b4\uc694(\ub2e8\uae30 \uae08\ub9ac\uac00 \uc7a5\uae30\ubcf4\ub2e4 \ub192\uc544\uc694). \uc5ed\uc0ac\uc801\uc73c\ub85c \uacbd\uae30 \uce68\uccb4\uc758 \ucd08\uae30 \uacbd\uace0\uc608\uc694.","sectors":"\uc740\ud589\uc740 \uc5ed\uc804\uc758 \ub300\ud45c\uc801\uc778 \ud53c\ud574 \uc5c5\uc885\uc774\uace0, \uc5ed\uc804\uc774 \uc774\uc5b4\uc9c0\uba74 \uc720\ud2f8\ub9ac\ud2f0\uc640 \ud544\uc218\uc18c\ube44\uc7ac \uac19\uc740 \ubc29\uc5b4\uc8fc\uac00 \uc55e\uc11c\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694.","read":[["+0.5%p \ucd08\uacfc","\uc815\uc0c1\uc801\uc778 \uae30\uc6b8\uae30\uc608\uc694 (\ud3c9\uc628)."],["0 ~ +0.5%p","\ud3c9\ud3c9\ud574\uc11c \uc5ec\uc720\uac00 \uc801\uc5b4\uc694 (\uc8fc\uc758)."],["0%p \ubbf8\ub9cc","\uc5ed\uc804\uc774\uc5d0\uc694 (\uacbd\uacc4). 1970\ub144\ub300 \uc774\ud6c4 \ubbf8\uad6d \uacbd\uae30 \uce68\uccb4 \ub300\ubd80\ubd84\uc5d0 \uc55e\uc11c \ub098\ud0c0\ub09c \uacbd\uace0\uc9c0\ub9cc, \uba87 \ub2ec\uc529 \uc2dc\ucc28\uac00 \uc788\uc5b4\uc694."],["\uc5ed\uc804 \ub4a4 \ub2e4\uc2dc \uac00\ud314\ub77c\uc9d0","\ubcf4\ud1b5 \uc778\ud558\uac00 \uc2dc\uc791\ub420 \ub54c \ub098\ud0c0\ub098\uc694. \uce68\uccb4\uac00 \uc628\ub2e4\uba74 \uc774 \uc988\uc74c\uc774\ub098 \uadf8 \uc774\ud6c4\uc5d0 \uc2dc\uc791\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\uc5c8\uc5b4\uc694."]],"chain":["\uc5f0\uc900\uc774 \ubb3c\uac00\ub97c \uc7a1\uc73c\ub824 \ub2e8\uae30 \uae08\ub9ac\ub97c \ub192\uac8c \uc720\uc9c0\ud574\uc694.","\ud22c\uc790\uc790\uac00 \uc131\uc7a5\uc774 \uaebe\uc774\uace0 \ub098\uc911\uc5d0 \uae08\ub9ac\uac00 \ub0b4\ub9b4 \uac83\uc73c\ub85c \ubcf4\ub2c8 \uc7a5\uae30 \uae08\ub9ac\uac00 \ub2e8\uae30\ubcf4\ub2e4 \ub0ae\uac8c \ub0a8\uc544\uc694.","\uc740\ud589\uc740 \uae38\uac8c \ube4c\ub824\uc8fc\uace0 \uc9e7\uac8c \ube4c\ub824 \uc218\uc775\uc774 \uc904\uc5b4\uc694 \u2192 \ub300\ucd9c\uc744 \uc870\uc5ec\uc694 \u2192 \uc131\uc7a5\uc774 \ub454\ud654\ub3fc\uc694."],"episodes":[["2022\ub144 7\uc6d4 ~ 2024\ub144 9\uc6d4\uacbd","\uae30\ub85d\uc0c1 \uac00\uc7a5 \uae34 \uc5ed\uc804 \uc911 \ud558\ub098\ub85c \uc57d 2\ub144\uac04 \uc774\uc5b4\uc84c\uace0, 2023\ub144 \uc911\ubc18\uc5d0 \u22121%p \ubd80\uadfc\uae4c\uc9c0 \uae4a\uc5b4\uc84c\uc5b4\uc694. \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \uce68\uccb4\uac00 \uc120\uc5b8\ub418\uc9c0 \uc54a\uc558\uc5b4\uc694. \uc774 \uc2e0\ud638\ub294 \uacbd\uace0\uc774\uc9c0 \uc2dc\uacc4\uac00 \uc544\ub2c8\uc5d0\uc694."],["2006~2007\ub144","2006\ub144\uc5d0 \uace1\uc120\uc774 \uc5ed\uc804\ub410\uace0 \uce68\uccb4\ub294 2007\ub144 12\uc6d4\uc5d0 \uc2dc\uc791\ub410\uc5b4\uc694."],["2019\ub144 8\uc6d4","\uc9e7\uc740 \uc5ed\uc804\uc774\uc5c8\uc5b4\uc694. 2020\ub144 \uce68\uccb4\ub294 \ud32c\ub370\ubbf9\uc774 \uc6d0\uc778\uc774\ub77c \uc774 \uc2e0\ud638\ub97c \uc2dc\ud5d8\ud558\uae30\uc5d4 \uc801\uc808\ud558\uc9c0 \uc54a\uc544\uc694."]]}'],t.w)
B.eTM=new A.b(B.h,["",'{"up":"\uace1\uc120\uc774 \uac00\ud314\ub77c\uc9c0\uace0 \uc788\uc5b4\uc694. \ub2e8\uae30 \uae08\ub9ac\uac00 \uc778\ud558\ub97c \ud5a5\ud574 \ub0b4\ub824\uac00\uac70\ub098 \uc7a5\uae30 \uae08\ub9ac\uac00 \uc624\ub974\uace0 \uc788\uc5b4\uc694.","down":"\uace1\uc120\uc774 \ud3c9\ud3c9\ud574\uc9c0\uac70\ub098 \uc5ed\uc804\ub418\uace0 \uc788\uc5b4\uc694. \uc7a5\uae30 \uc804\ub9dd\uc5d0 \ube44\ud574 \uc815\ucc45\uc774 \uae34\ucd95\uc801\uc774\uc5d0\uc694.","upShort":"\uace1\uc120 \uac00\ud314\ub77c\uc9d0 \u2014 \ub2e8\uae30 \uae08\ub9ac \ud558\ub77d \ub610\ub294 \uc7a5\uae30 \uae08\ub9ac \uc0c1\uc2b9\uc774\uc5d0\uc694.","downShort":"\uace1\uc120\uc774 \ud3c9\ud3c9\ud574\uc9c0\uba70 \uc5ed\uc804 \ucabd\uc73c\ub85c \uac00\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uace1\uc120\uc740 \uc815\uc0c1\uc801\uc778 \uae30\uc6b8\uae30\uc608\uc694.","watch":"{v}\uc5d0\uc11c \uace1\uc120\uc774 \ud3c9\ud3c9\uc5d0 \uac00\uae4c\uc6cc\uc694.","stress":"{v}\uc5d0\uc11c \uace1\uc120\uc774 \uc5ed\uc804\ub410\uc5b4\uc694. \uc7a5\uae30 \uae30\ub85d\uc774 \uac00\uc7a5 \uc88b\uc740 \ud615\ud0dc\uc758 \uc2e0\ud638\uc608\uc694.","sectors":"10\ub144-2\ub144 \uace1\uc120\uacfc \uac19\uc544\uc694. \uc740\ud589\uacfc \uacbd\uae30\ubbfc\uac10\uc8fc\uac00 \uac00\uc7a5 \uba3c\uc800 \ub290\uaef4\uc694.","read":[["+0.5%p \ucd08\uacfc","\uc815\uc0c1\uc801\uc778 \uae30\uc6b8\uae30\uc608\uc694 (\ud3c9\uc628)."],["0 ~ +0.5%p","\ud3c9\ud3c9\ud574\uc694 (\uc8fc\uc758)."],["0%p \ubbf8\ub9cc","\uc5ed\uc804\uc774\uc5d0\uc694 (\uacbd\uacc4). \ud559\uacc4\uc640 \uc5f0\uc900 \uc5f0\uad6c\uc5d0\uc11c \uc774 \uc2a4\ud504\ub808\ub4dc\uac00 \uc57d 1\ub144 \uc2dc\ucc28\ub85c \ubbf8\uad6d \ub370\uc774\ud130\uc758 \uac15\ud55c \uce68\uccb4 \uc9c0\ud45c\ub77c\uace0 \ubc1d\ud614\uc5b4\uc694."]],"chain":["3\uac1c\uc6d4\ubb3c \uae08\ub9ac\ub294 \uc5f0\uc900 \uc815\ucc45\uae08\ub9ac\ub97c \uac70\uc758 \uadf8\ub300\ub85c \ub530\ub77c\uac00\uc694.","\uc774\uac83\uc774 10\ub144\ubb3c \uae08\ub9ac\ubcf4\ub2e4 \ub192\uc73c\uba74 \uc815\ucc45\uc774 \uc2dc\uc7a5\uc758 \uc7a5\uae30 \uc804\ub9dd\ubcf4\ub2e4 \uae34\ucd95\uc801\uc774\uc5d0\uc694.","\uc740\ud589 \ub9c8\uc9c4\uacfc \uc2e0\uc6a9 \uc131\uc7a5\uc774 \uc9d3\ub20c\ub9ac\uace0, \uc774\uac83\uc774 \uc2e4\ubb3c\uacbd\uc81c\ub85c \uc804\ud574\uc9c8 \uc218 \uc788\uc5b4\uc694."],"episodes":[["2022\ub144 10\uc6d4 ~ 2024\ub144 \ub9d0\uacbd","\uc57d 2\ub144\uac04 \uc5ed\uc804\ub410\uc9c0\ub9cc \uc774\ubc88\uc5d0\ub3c4 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \uce68\uccb4\uac00 \uc120\uc5b8\ub418\uc9c0 \uc54a\uc558\uc5b4\uc694."],["2006~2007\ub144","2006~2007\ub144 \uc0c1\ub2f9 \uae30\uac04 \uc5ed\uc804\ub410\uace0 \uce68\uccb4\ub294 2007\ub144 12\uc6d4\uc5d0 \uc2dc\uc791\ub410\uc5b4\uc694."]]}'],t.w)
B.eFY=new A.b(B.h,["",'{"up":"\ub3c8\uc758 \uc2e4\uc9c8 \uac00\uaca9\uc774 \uc62c\ub77c\uac00\uace0 \uc788\uc5b4\uc694. \uae08\uacfc \uc7a5\uae30 \uc131\uc7a5\uc8fc\uc5d0\ub294 \ub098\uc058\uace0 \uc800\ucd95\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc88b\uc544\uc694.","down":"\uc2e4\uc9c8 \ucc28\uc785 \ube44\uc6a9\uc774 \ub0ae\uc544\uc9c0\uace0 \uc788\uc5b4\uc694. \uae08\uacfc \uc131\uc7a5\uc8fc\uc5d0 \uc6b0\ud638\uc801\uc774\uc5d0\uc694.","upShort":"\uc2e4\uc9c8 \ucc28\uc785 \ube44\uc6a9 \uc0c1\uc2b9\uc740 \uae08\uacfc \uc131\uc7a5\uc8fc\uc5d0 \uc5ed\ud48d\uc774\uc5d0\uc694.","downShort":"\uc2e4\uc9c8\uae08\ub9ac \ud558\ub77d\uc740 \uae08\uacfc \uc131\uc7a5\uc8fc\uc5d0 \uc21c\ud48d\uc774\uc5d0\uc694.","calm":"{v}\uc5d0\uc11c \uc2e4\uc9c8\uae08\ub9ac\ub294 \ubcf4\ud1b5 \uc218\uc900\uc774\uc5d0\uc694.","watch":"{v}\uc5d0\uc11c \uc2e4\uc9c8\uae08\ub9ac\uac00 \uac00\uce58\ud3c9\uac00\uc640 \uae08\uc5d0 \ubd80\ub2f4\uc744 \uc904 \ub9cc\ud07c \ub192\uc544\uc694.","stress":"{v}\uc5d0\uc11c \uc2e4\uc9c8\uae08\ub9ac\uac00 2008\ub144 \uc774\ud6c4 \ubc94\uc704\uc758 \ub192\uc740 \ub05d\uc5d0 \uc788\uc5b4\uc694. \uc81c\uc57d\uc801\uc778 \ud658\uacbd\uc774\uc5d0\uc694.","sectors":"\uc7a5\uae30 \uc131\uc7a5 \uae30\uc220\uc8fc\uc640 \uc801\uc790 \uc131\uc7a5\uc8fc\uac00 \uac00\uc7a5 \ubbfc\uac10\ud558\uace0, \uae08\uad11\uc8fc\ub294 \uae08\uc744 \ub530\ub77c\uac00\uc694.","read":[["1.5% \ubbf8\ub9cc","\ubcf4\ud1b5\uc774\uc5d0\uc694 (\ud3c9\uc628)."],["1.5% ~ 2.5%","\uc81c\uc57d\uc801\uc774\uc5d0\uc694 (\uc8fc\uc758)."],["2.5% \uc774\uc0c1","2008\ub144 \uc774\ud6c4 \uae30\uc900\uc73c\ub85c \ub9e4\uc6b0 \uc81c\uc57d\uc801\uc774\uc5d0\uc694 (\uacbd\uacc4)."],["\ub9c8\uc774\ub108\uc2a4","\uc800\ucd95\ud558\ub294 \uc0ac\ub78c\uc774 \ubb3c\uac00\uc5d0 \uc9c0\uace0, \uc218\uc775\uc744 \ucc3e\uc544 \ub098\uc11c\uac8c \ud574\uc694 (2020~21)."]],"chain":["\uc2e4\uc9c8\uae08\ub9ac = \uba85\ubaa9 10\ub144\ubb3c \uae08\ub9ac \u2212 \uc2dc\uc7a5\uc758 \uae30\ub300 \uc778\ud50c\ub808\uc774\uc158(breakeven)\uc774\uc5d0\uc694.","\uc2e4\uc9c8\uae08\ub9ac\uac00 \ub192\uc544\uc9c0\uba74 \ubaa8\ub4e0 \ud22c\uc790\uac00 \ub118\uc5b4\uc57c \ud560 \uae30\uc900\uc774 \uc62c\ub77c\uac00\uc694.","\uc9c0\uae08 \uc544\ubb34\uac83\ub3c4 \uc9c0\uae09\ud558\uc9c0 \uc54a\ub294 \uc790\uc0b0(\uae08)\uc774\ub098 \uc774\uc775 \ub300\ubd80\ubd84\uc774 \uba3c \ubbf8\ub798\uc5d0 \uc788\ub294 \uc790\uc0b0(\uc131\uc7a5\uc8fc)\uc740 \ub9e4\ub825\uc774 \uc904\uc5b4\uc694."],"episodes":[["2021\ub144 12\uc6d4 (\uc57d)","\uc5f0\uc900\uc774 \uc544\uc9c1 \uc81c\ub85c \uae08\ub9ac\uc77c \ub54c \uc2e4\uc9c8\uae08\ub9ac\uac00 \u22121% \ubd80\uadfc\uc774\uc5c8\uc5b4\uc694."],["2023\ub144 10\uc6d4 (\uc57d)","\uc8fc\uc2dd\uc774 \ud558\ub77d\ud558\ub294 \uac00\uc6b4\ub370 2007\ub144 \uc774\ud6c4 \ucd5c\uace0\uc778 \uc57d 2.5%\uc5d0 \ub2ff\uc558\uc5b4\uc694."]]}'],t.w)
B.evB=new A.b(B.h,["",'{"up":"\uc815\ubd80 \ucc28\uc785 \ud655\ub300, \ubb3c\uac00 \ubd88\ud655\uc2e4\uc131, \uc218\uc694 \uc57d\ud654 \ub54c\ubb38\uc5d0 \ud22c\uc790\uc790\uac00 \uc7a5\uae30\ucc44 \ubcf4\uc720 \uc704\ud5d8\uc5d0 \ub354 \ud070 \ubcf4\uc0c1\uc744 \uc6d0\ud574\uc694.","down":"\uc7a5\uae30\ucc44\uac00 \uc548\uc804\ud558\uac70\ub098 \uc218\uc694\uac00 \ub192\ub2e4\uace0 \ubcf4\uace0 \uc788\uc5b4\uc694(\uc911\uc559\uc740\ud589 \ub9e4\uc785, \uc548\uc804\uc790\uc0b0 \uc120\ud638).","upShort":"\ud22c\uc790\uc790\uac00 \uc7a5\uae30\ucc44 \ubcf4\uc720\uc5d0 \ub354 \ud070 \ubcf4\uc0c1\uc744 \uc694\uad6c\ud558\uace0 \uc788\uc5b4\uc694.","downShort":"\uc7a5\uae30\ucc44 \uc218\uc694\uac00 \ub192\uc544 \ud504\ub9ac\ubbf8\uc5c4\uc774 \uc904\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uae30\uac04 \ud504\ub9ac\ubbf8\uc5c4\uc740 \uc5ed\uc0ac\uc0c1 \ubcf4\ud1b5 \ubc94\uc704\uc5d0 \uc788\uc5b4\uc694.","watch":"{v}\uc5d0\uc11c \uae30\uac04 \ud504\ub9ac\ubbf8\uc5c4\uc774 \uc790\uccb4 \uc5ed\uc0ac \ub300\ube44 \uc774\ub840\uc801\uc73c\ub85c \ub192\uac70\ub098 \ub0ae\uc544\uc694.","stress":"{v}\uc5d0\uc11c \uae30\uac04 \ud504\ub9ac\ubbf8\uc5c4\uc774 \uc790\uccb4 \uc5ed\uc0ac\uc758 \uadf9\ub2e8\uc5d0 \uc788\uc5b4\uc694.","sectors":"10\ub144\ubb3c \uae08\ub9ac\uc640 \uac19\uc740 \uacbd\ub85c\uc608\uc694. \uc8fc\ud0dd, \uc720\ud2f8\ub9ac\ud2f0, \uc7a5\uae30 \uc131\uc7a5\uc8fc\uac00 \ud574\ub2f9\ub3fc\uc694.","read":[["\uc5ed\uc0ac\uc758 \uc911\uac04 80% \uc548","\ubcf4\ud1b5\uc774\uc5d0\uc694 (\ud3c9\uc628)."],["\uc0c1\uc704 \ub610\ub294 \ud558\uc704 10%","\uc774\ub840\uc801\uc774\uc5d0\uc694 (\uc8fc\uc758)."],["\uc0c1\uc704 \ub610\ub294 \ud558\uc704 2%","\uadf9\ub2e8\uc774\uc5d0\uc694 (\uacbd\uacc4)."],["\ucd94\uc815 \uad00\ub828 \uc8fc\uc758","\ubaa8\ub378\ub9c8\ub2e4 \uc218\uc900\uc774 \ub2ec\ub77c\uc694. \uc18c\uc218\uc810\ubcf4\ub2e4 \ubc29\ud5a5\uc744 \uc77d\uc73c\uc138\uc694."]],"chain":["10\ub144\ubb3c \uae08\ub9ac = \uae30\ub300 \ud3c9\uade0 \ub2e8\uae30 \uae08\ub9ac + \uae30\uac04 \ud504\ub9ac\ubbf8\uc5c4\uc774\uc5d0\uc694.","\ud504\ub9ac\ubbf8\uc5c4\uc774 \uc624\ub974\uba74 \uae08\ub9ac \uae30\ub300\uac00 \uadf8\ub300\ub85c\uc5ec\ub3c4 \uae08\ub9ac\uac00 \uc62c\ub77c\uc694.","\uc7a5\uae30 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc5f0\uc900\uc774 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc8fc\ud0dd\ub2f4\ubcf4\uc640 \uac00\uce58\ud3c9\uac00\uc5d0 \ud0c0\uaca9\uc774 \ub3fc\uc694."],"episodes":[["2019~2022\ub144 (\uc57d)","\uc911\uc559\uc740\ud589\uc758 \ub300\uaddc\ubaa8 \ucc44\uad8c \ub9e4\uc785\uc73c\ub85c \ud504\ub9ac\ubbf8\uc5c4\uc774 0 \uc544\ub798\ub85c \ub0b4\ub824\uac00 \uae30\uac04 \ub300\ubd80\ubd84 \ucd94\uc815\uce58\uac00 \ub9c8\uc774\ub108\uc2a4\uc600\uc5b4\uc694."],["2023\ub144 (\uc57d)","\uc5f0\uc900\uc774 \ub300\ucc28\ub300\uc870\ud45c\ub97c \uc904\uc774\uace0 \uad6d\ucc44 \ubc1c\ud589\uc774 \ub298\uba74\uc11c \ud50c\ub7ec\uc2a4\ub85c \ub3cc\uc544\uc11c \uc62c\ub77c\uac14\uc5b4\uc694."]]}'],t.w)
B.eZx=new A.b(B.h,["",'{"up":"\ubb3c\uac00\uac00 \ub354 \ube68\ub9ac \uc624\ub974\uace0 \uc788\uc5b4\uc694. \uc5f0\uc900\uc774 \uae08\ub9ac\ub97c \uc720\uc9c0\ud558\uac70\ub098 \uc62c\ub9b4 \uac00\ub2a5\uc131\uc774 \ub192\uc544\uc9c0\uace0 \uc2e4\uc9c8 \uc18c\ub4dd\uc774 \uc555\ubc15\ubc1b\uc544\uc694.","down":"\ub514\uc2a4\uc778\ud50c\ub808\uc774\uc158\uc774\uc5d0\uc694. \ubb3c\uac00 \uc555\ub825\uc774 \uc57d\ud574\uc838 \uae08\ub9ac \uc778\ud558 \uc5ec\uc9c0\uac00 \uc0dd\uaca8\uc694.","upShort":"\ubb3c\uac00\uac00 \ub2ec\uc544\uc624\ub974\uba70 \uae08\ub9ac \uc778\ud558 \uae30\ub300\uac00 \uc57d\ud574\uc838\uc694.","downShort":"\ubb3c\uac00\uac00 \uc2dd\uc73c\uba70 \uc778\ud558 \uc5ec\uc9c0\uac00 \ucee4\uc838\uc694.","calm":"{v}\uc5d0\uc11c \ud5e4\ub4dc\ub77c\uc778 \ubb3c\uac00\ub294 \uc5f0\uc900\uc774 \ubc1b\uc544\ub4e4\uc77c \ub9cc\ud55c \ubc94\uc704 \uadfc\ucc98\uc608\uc694.","watch":"{v}\uc5d0\uc11c \ubb3c\uac00\uac00 \uc5f0\uc900 \ubaa9\ud45c 2%\ub97c \ud55c\ucc38 \uc6c3\ub3cc\uc544\uc694.","stress":"{v}\uc5d0\uc11c \ubb3c\uac00\uac00 \uacf5\uaca9\uc801\uc778 \uae34\ucd95\uc744 \ubd88\ub7ec\uc62c \ub9cc\ud07c \ub192\uc544\uc694.","sectors":"\uc5d0\ub108\uc9c0\uc640 \uc6d0\uc790\uc7ac \uc0dd\uc0b0\uc790\ub294 \ubb3c\uac00 \uc0c1\uc2b9\uc758 \uc218\ud61c\ub97c \ubcf4\uace0, \uacbd\uae30\uc18c\ube44\uc7ac\uc640 \uc7a5\uae30 \uc131\uc7a5\uc8fc\ub294 \uc555\ubc15\ubc1b\uc544\uc694.","read":[["3% \ubbf8\ub9cc","\ubaa9\ud45c \uadfc\ucc98\uc608\uc694 (\ud3c9\uc628). \uc5f0\uc900\uc758 2% \ubaa9\ud45c\ub294 PCE \uae30\uc900\uc774\uba70, PCE\ub294 \ubcf4\ud1b5 CPI\ubcf4\ub2e4 \uc870\uae08 \ub0ae\uac8c \ub098\uc640\uc694."],["3% ~ 5%","\ubaa9\ud45c \uc704\uc608\uc694 (\uc8fc\uc758)."],["5% \uc774\uc0c1","\ub192\uc544\uc694 (\uacbd\uacc4)."],["0% \ubbf8\ub9cc","\ub514\ud50c\ub808\uc774\uc158\uc774\uc5d0\uc694. \ubb3c\uac00\uac00 \ub5a8\uc5b4\uc9c0\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ubb38\uc81c\uc608\uc694."]],"chain":["\ubb3c\uac00\uac00 \uc784\uae08\ubcf4\ub2e4 \ube68\ub9ac \uc62c\ub77c\uc694 \u2192 \uac00\uacc4\uac00 \uc18c\ube44\ub97c \uc904\uc5ec\uc694.","\uc5f0\uc900\uc774 \uc218\uc694\ub97c \uc2dd\ud788\ub824 \uae08\ub9ac\ub97c \uc62c\ub824\uc694 \u2192 \ucc28\uc785 \ube44\uc6a9\uc774 \uc62c\ub77c\uac00\uc694.","\uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc8fc\uc2dd\uacfc \ucc44\uad8c \uac00\uaca9\uc774 \ub0b4\ub9ac\uace0 \ucc44\uc6a9\uc774 \ub454\ud654\ub3fc\uc694."],"episodes":[["2022\ub144 6\uc6d4","\ubbf8\uad6d CPI \ubb3c\uac00\uc0c1\uc2b9\ub960\uc774 1981\ub144 \uc774\ud6c4 \ucd5c\uace0\uc778 \uc57d 9.1%\uc5d0\uc11c \uc815\uc810\uc744 \ucc0d\uc5c8\uc5b4\uc694."],["1980\ub144 3\uc6d4","\ubcfc\ucee4 \uc5f0\uc900\uc758 \uae08\ub9ac \uc778\uc0c1\uc774 \uc7a1\uae30 \uc804\uc5d0 \ubb3c\uac00\uac00 \uc57d 14.8%\uc5d0\uc11c \uc815\uc810\uc744 \ucc0d\uc5c8\uc5b4\uc694."],["2020\ub144 5\uc6d4 (\uc57d)","\ud32c\ub370\ubbf9\uc73c\ub85c \uacbd\uc81c\uac00 \uba48\ucd94\uba70 \ubb3c\uac00\uc0c1\uc2b9\ub960\uc774 0% \ubd80\uadfc\uae4c\uc9c0 \ub5a8\uc5b4\uc84c\uc5b4\uc694."]]}'],t.w)
B.eiV=new A.b(B.h,["",'{"up":"\uae30\uc870\uc801 \ubb3c\uac00\uac00 \ub2e8\ub2e8\ud574\uc9c0\uace0 \uc788\uc5b4\uc694. \uc5f0\uc900\uc774 \uae08\ub9ac \uacb0\uc815\uc5d0\uc11c \uac00\uc7a5 \ub9ce\uc774 \ubcf4\ub294 \uc218\uce58\uc608\uc694.","down":"\uae30\uc870\uc801 \ubb3c\uac00\uac00 2% \ubaa9\ud45c\ub85c \uc2dd\uace0 \uc788\uc5b4\uc694.","upShort":"\uae30\uc870\uc801 \ubb3c\uac00\uac00 \ub2e8\ub2e8\ud574\uc9c0\uace0 \uc788\uc5b4\uc694.","downShort":"\uae30\uc870\uc801 \ubb3c\uac00\uac00 \ubaa9\ud45c\ub85c \uc2dd\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uadfc\uc6d0 \ubb3c\uac00\ub294 \uc5f0\uc900\uc758 2% \ubaa9\ud45c\uc5d0 \uac00\uae4c\uc6cc\uc694.","watch":"{v}\uc5d0\uc11c \uadfc\uc6d0 \ubb3c\uac00\uac00 \uc5f0\uc900 \ubaa9\ud45c \uc704\uc5d0 \uc788\uc5b4\uc694.","stress":"{v}\uc5d0\uc11c \uadfc\uc6d0 \ubb3c\uac00\uac00 \uc5f0\uc900 \ubaa9\ud45c\ub97c \ud6cc\uca4d \uc6c3\ub3cc\uc544\uc694.","sectors":"CPI\uc640 \uac19\uc544\uc694. \uae34\ucd95 \uc815\ucc45\uc740 \uae08\ub9ac\uc5d0 \ubbfc\uac10\ud55c \ubd80\ubb38\uc5d0 \ud0c0\uaca9\uc744 \uc918\uc694.","read":[["2.5% \ubbf8\ub9cc","2% \ubaa9\ud45c \uadfc\ucc98\uc608\uc694 (\ud3c9\uc628)."],["2.5% ~ 4%","\ubaa9\ud45c \uc704\uc608\uc694 (\uc8fc\uc758)."],["4% \uc774\uc0c1","\ubaa9\ud45c\ub97c \ud06c\uac8c \uc6c3\ub3cc\uc544\uc694 (\uacbd\uacc4)."]],"chain":["\uadfc\uc6d0\uc740 \ubcc0\ub3d9\uc774 \ud070 \uc2dd\ud488\uacfc \uc5d0\ub108\uc9c0\ub97c \ube7c\uc11c \ucd94\uc138\ub97c \ubcf4\uc5ec\uc918\uc694.","\uc5f0\uc900\uc740 \uc804\uccb4 PCE\ub85c 2% \ubaa9\ud45c\ub97c \uc815\ud558\uace0, \uadfc\uc6d0\uc740 \uadf8 \ubc29\ud5a5\uc744 \uc54c\ub824\uc8fc\ub294 \uae38\uc7a1\uc774\uc608\uc694.","\uadfc\uc6d0 \uc218\uce58\uac00 \ubaa9\ud45c \uc704\uc5d0 \uacc4\uc18d \uba38\ubb3c\uba74 \uc815\ucc45\uc774 \uae34\ucd95\uc73c\ub85c \uc720\uc9c0\ub3fc\uc694."],"episodes":[["2022\ub144 \ucd08 (\uc57d)","\uadfc\uc6d0 PCE \ubb3c\uac00\uc0c1\uc2b9\ub960\uc774 \uc57d 40\ub144 \ub9cc\uc758 \ucd5c\uace0\uc778 5%\ub97c \uc6c3\ub3cc\uc558\uc5b4\uc694."]]}'],t.w)
B.eKX=new A.b(B.h,["",'{"up":"\uc2dc\uc7a5\uc774 \ub354 \ub192\uc740 \ubb3c\uac00\ub97c \uc608\uc0c1\ud574\uc694(\ub610\ub294 \ub354 \ub9ce\uc740 \ubcf4\ud638\ub97c \uc6d0\ud574\uc694).","down":"\uc2dc\uc7a5\uc774 \ub354 \ub0ae\uc740 \ubb3c\uac00\ub97c \uc608\uc0c1\ud558\uac70\ub098, \uc131\uc7a5 \uc6b0\ub824\uac00 \uae30\ub300\ub97c \ub04c\uc5b4\ub0b4\ub9ac\uace0 \uc788\uc5b4\uc694.","upShort":"\ubb3c\uac00 \uae30\ub300\uac00 \uc624\ub974\uace0 \uc788\uc5b4\uc694.","downShort":"\ubb3c\uac00 \uae30\ub300\uac00 \ub0b4\ub9ac\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uc2dc\uc7a5\uc740 \uc5f0\uc900 \ubaa9\ud45c\uc5d0 \uac00\uae4c\uc6b4 \ubb3c\uac00\ub97c \uc608\uc0c1\ud574\uc694.","watch":"{v}\uc5d0\uc11c \uae30\ub300\uac00 \ud3c9\uc18c \ubc94\uc704\uc5d0\uc11c \ubc97\uc5b4\ub098\uace0 \uc788\uc5b4\uc694.","stress":"{v}\uc5d0\uc11c \uae30\ub300\uac00 \uadf9\ub2e8\uc5d0 \uc788\uc5b4\uc694. \uc704\ub85c \uc774\ud0c8\ud588\uac70\ub098 \ub514\ud50c\ub808\uc774\uc158 \uacf5\ud3ec\ub97c \uc54c\ub9ac\uace0 \uc788\uc5b4\uc694.","sectors":"breakeven\uc774 \uc624\ub974\uba74 \uc5d0\ub108\uc9c0, \uc18c\uc7ac, TIPS \ubcf4\uc720\uc790\uc5d0\uac8c \uc720\ub9ac\ud574\uc694.","read":[["1.8% ~ 2.6%","\ubaa9\ud45c \uadfc\ucc98\uc5d0 \uace0\uc815\ub3fc \uc788\uc5b4\uc694 (\ud3c9\uc628)."],["\uadf8 \ubc94\uc704 \ubc16","\ubc97\uc5b4\ub098\uace0 \uc788\uc5b4\uc694 (\uc8fc\uc758)."],["1.0% \ubbf8\ub9cc \ub610\ub294 3.2% \ucd08\uacfc","\uadf9\ub2e8\uc774\uc5d0\uc694 (\uacbd\uacc4)."]],"chain":["breakeven = \uba85\ubaa9 \uae08\ub9ac \u2212 \uc2e4\uc9c8 \uae08\ub9ac\uc608\uc694.","\uc720\uac00\uc640 \ud568\uaed8 \uae09\ub4f1\ud558\uba74 \uc2dc\uc7a5\uc774 \uc5d0\ub108\uc9c0 \ube44\uc6a9\uc744 \uadf8\ub300\ub85c \uc5f0\uc7a5\ud574 \ubcf4\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694.","\ud558\ub77d\uc7a5\uc5d0\uc11c breakeven\uc774 \ub0b4\ub9ac\uba74 \uc88b\uc740 \uc18c\uc2dd\uc774 \uc544\ub2c8\ub77c \ub514\ud50c\ub808\uc774\uc158 \uacf5\ud3ec\uc77c \uc218 \uc788\uc5b4\uc694."],"episodes":[["2008\ub144 \ub9d0\uacfc 2020\ub144 3\uc6d4","\ub450 \uc704\uae30 \ubaa8\ub450 \ub514\ud50c\ub808\uc774\uc158 \uacf5\ud3ec\uac00 \ud37c\uc9c0\uba70 10\ub144 breakeven\uc774 1% \uc544\ub798\ub85c \ub5a8\uc5b4\uc84c\uc5b4\uc694."],["2022\ub144 \ubd04 (\uc57d)","\ubb3c\uac00\uac00 \uae09\ub4f1\ud558\uba70 \uc57d 3%\uae4c\uc9c0 \uc62c\ub790\uc5b4\uc694."]]}'],t.w)
B.eWo=new A.b(B.h,["",'{"up":"\ucc44\uc6a9\uc774 \ub454\ud654\ub418\uac70\ub098 \ud574\uace0\uac00 \ub298\uace0 \uc788\uc5b4\uc694. \ube60\ub978 \uc0c1\uc2b9\uc740 \ub454\ud654\uac00 \uc2dc\uc791\ub410\ub2e4\ub294 \uac00\uc7a5 \ubd84\uba85\ud55c \uc2e0\ud638 \uc911 \ud558\ub098\uc608\uc694.","down":"\ub178\ub3d9\uc2dc\uc7a5\uc774 \uc870\uc5ec\uc9c0\uace0 \uc788\uc5b4\uc694. \uc77c\uc790\ub9ac\ub97c \uad6c\ud558\uae30 \uc27d\uace0 \uc784\uae08\uc774 \uc624\ub974\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694.","upShort":"\uc2e4\uc5c5\uc774 \ub298\uba70 \ub178\ub3d9\uc2dc\uc7a5\uc774 \ub290\uc2a8\ud574\uc9c0\uace0 \uc788\uc5b4\uc694.","downShort":"\uc2e4\uc5c5\uc774 \uc904\uba70 \ub178\ub3d9\uc2dc\uc7a5\uc774 \uc870\uc5ec\uc9c0\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uc2e4\uc5c5\ub960\uc740 \uc9c0\ub09c 1\ub144\uac04 \uc758\ubbf8 \uc788\uac8c \uc624\ub974\uc9c0 \uc54a\uc558\uc5b4\uc694.","watch":"{v}\uc5d0\uc11c \uc2e4\uc5c5\ub960\uc774 1\ub144 \uc804\ubcf4\ub2e4 0.5%p \uc774\uc0c1 \uc62c\ub790\uc5b4\uc694. \ub178\ub3d9\uc2dc\uc7a5\uc774 \uc57d\ud574\uc9c0\uace0 \uc788\uc5b4\uc694.","stress":"{v}\uc5d0\uc11c \uc2e4\uc5c5\ub960\uc774 1\ub144 \uc804\ubcf4\ub2e4 1%p \uc774\uc0c1 \uc62c\ub790\uc5b4\uc694. \uacbd\uae30 \uce68\uccb4\uc5d0\uc11c \ubcf4\uc774\ub294 \ud328\ud134\uc774\uc5d0\uc694.","sectors":"\uacbd\uae30\uc18c\ube44\uc7ac, \uc8fc\ud0dd, \uc18c\ub9e4\uac00 \uc9c0\ucd9c \uac10\uc18c\ub97c \uac00\uc7a5 \uba3c\uc800 \ub290\uaef4\uc694.","read":[["1\ub144 \uc804 \ub300\ube44 0.5%p \ubbf8\ub9cc \uc0c1\uc2b9","\uc548\uc815\uc801\uc774\uc5d0\uc694 (\ud3c9\uc628)."],["0.5~1.0%p \uc0c1\uc2b9","\uc57d\ud574\uc9c0\uace0 \uc788\uc5b4\uc694 (\uc8fc\uc758)."],["1.0%p \uc774\uc0c1 \uc0c1\uc2b9","\uce68\uccb4\ud615 \uc545\ud654\uc608\uc694 (\uacbd\uacc4)."],["\uc218\uc900 \uc790\uccb4","\uc2dc\ub300\ub9c8\ub2e4 \ub2ec\ub77c\uc694. \ubcc0\ud654\uc758 \ubc29\ud5a5\uc774 \uc4f8\ubaa8 \uc788\ub294 \uc2e0\ud638\uc608\uc694."]],"chain":["\uae30\uc5c5\uc774 \uc218\uc694 \uc57d\ud654\ub97c \ubcf4\uace0 \ucc44\uc6a9\uc744 \ub2a6\ucd94\ub2e4\uac00 \uc778\uc6d0\uc744 \uc904\uc5ec\uc694.","\uc6d4\uae09\uc774 \uc904\uc5b4\uc694 \u2192 \uc18c\ube44\uac00 \uc904\uc5b4\uc694 \u2192 \ub9e4\ucd9c\uc774 \uc57d\ud574\uc838\uc694 \u2192 \ud574\uace0\uac00 \ub298\uc5b4\uc694.","\uc5f0\uc900\uc774 \uc77c\uc790\ub9ac\ub97c \uc9c0\ud0a4\ub824 \uae08\ub9ac\ub97c \ub0b4\ub9b4 \uc218 \uc788\uace0, \ucc28\uc785 \ube44\uc6a9\uc774 \ub0ae\uc544\uc838\uc694."],"episodes":[["2020\ub144 4\uc6d4","\ud32c\ub370\ubbf9 \ucd08\uae30 \ud55c \ub2ec \ub9cc\uc5d0 \uc2e4\uc5c5\ub960\uc774 \uc57d 14.8%\ub85c \ub6f0\uc5c8\uc5b4\uc694. 1948\ub144\uc5d0 \uc2dc\uc791\ud55c \ub370\uc774\ud130 \uc911 \ucd5c\uace0\uc608\uc694."],["2009\ub144 10\uc6d4 (\uc57d)","\uae08\uc735\uc704\uae30 \ub4a4 10% \ubd80\uadfc\uc5d0\uc11c \uc815\uc810\uc744 \ucc0d\uc5c8\uc5b4\uc694."],["2023\ub144 \ucd08","1969\ub144 \uc774\ud6c4 \uac00\uc7a5 \ub0ae\uc740 \uc57d 3.4%\uae4c\uc9c0 \ub0b4\ub824\uac14\uc5b4\uc694."]]}'],t.w)
B.ePk=new A.b(B.h,["",'{"up":"\uc2e4\uc5c5\uc774 \ucd5c\uadfc \uc800\uc810\uc5d0 \ube44\ud574 \ube60\ub974\uac8c \uc624\ub974\uace0 \uc788\uc5b4\uc694. 0.5\uac00 \ub418\uba74 \uaddc\uce59\uc774 \ubc1c\ub3d9\ub3fc\uc694.","down":"\ub178\ub3d9\uc2dc\uc7a5\uc774 \uc548\uc815\ub418\uac70\ub098 \uc88b\uc544\uc9c0\uace0 \uc788\uc5b4\uc694.","upShort":"Sahm \uaca9\ucc28\uac00 \ubc8c\uc5b4\uc9c0\uba70 \uc2e4\uc5c5\uc774 \ube60\ub974\uac8c \ub298\uace0 \uc788\uc5b4\uc694.","downShort":"Sahm \uaca9\ucc28\uac00 \uc881\uc544\uc9c0\uba70 \ub178\ub3d9\uc2dc\uc7a5\uc774 \uc548\uc815\ub418\uace0 \uc788\uc5b4\uc694.","calm":"{v}\uc5d0\uc11c \uc2e4\uc5c5\ub960\uc740 \ucd5c\uadfc \uc800\uc810 \uc704\ub85c \uc758\ubbf8 \uc788\uac8c \uc624\ub974\uc9c0 \uc54a\uace0 \uc788\uc5b4\uc694.","watch":"{v}\uc5d0\uc11c \uc2e4\uc5c5\ub960\uc774 \ucd5c\uadfc \uc800\uc810 \uc704\ub85c \uc624\ub974\uace0 \uc788\uc5b4\uc694. 0.5 \ubc1c\ub3d9\uc120\uc5d0 \uac00\uae4c\uc6cc\uc9c0\uace0 \uc788\uc5b4\uc694.","stress":"{v}\uc5d0\uc11c Sahm \uaddc\uce59\uc774 0.5 \ubc1c\ub3d9\uc120\uc5d0 \ub2ff\uc558\uac70\ub098 \ub118\uc5c8\uc5b4\uc694.","sectors":"\ub178\ub3d9\uc2dc\uc7a5\uc774 \uc57d\ud574\uc9c0\uba74 \uacbd\uae30\ubbfc\uac10 \ubd80\ubb38\uacfc \uc18c\ud615\uc8fc\uac00 \ub4a4\ucc98\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4\uc694.","read":[["0.3%p \ubbf8\ub9cc","\uc2e0\ud638 \uc5c6\uc74c (\ud3c9\uc628)."],["0.3 ~ 0.5%p","\ubc1c\ub3d9\uc120\uc5d0 \uc811\uadfc \uc911\uc774\uc5d0\uc694 (\uc8fc\uc758)."],["0.5%p \uc774\uc0c1","\uaddc\uce59 \ubc1c\ub3d9 (\uacbd\uacc4). 1970\ub144 \uc774\ud6c4 \ubbf8\uad6d \uacbd\uae30 \uce68\uccb4\ub9c8\ub2e4 \uc2dc\uc791 \uc2dc\uc810\uc774\ub098 \uadf8 \ubd80\uadfc\uc5d0\uc11c \ubc1c\ub3d9\ud588\uc5b4\uc694."],["\uc8fc\uc758","\uc5ed\uc0ac\uc5d0 \ub9de\ucd98 \uaddc\uce59\uc774\uc9c0 \ubc95\uce59\uc774 \uc544\ub2c8\uc5d0\uc694. 2024\ub144 8\uc6d4\uc5d0\ub294 \ub178\ub3d9 \uacf5\uae09\uc774 \ube60\ub974\uac8c \ub298\ub358 \uc911\uc5d0 \ubc1c\ub3d9\ud588\uace0, \uace0\uc548\uc790\ub3c4 \uc774\ubc88\uc5d0\ub294 \ub2e4\ub974\ub2e4\uace0 \ub9d0\ud588\uc5b4\uc694."]],"chain":["\uc774\ub807\uac8c \ube60\ub978 \uc2e4\uc5c5 \uc0c1\uc2b9\uc740 \uc5ed\uc0ac\uc801\uc73c\ub85c \uc2a4\uc2a4\ub85c\ub97c \ud0a4\uc6e0\uc5b4\uc694. \ud574\uace0 \u2192 \uc18c\ube44 \uac10\uc18c \u2192 \ucd94\uac00 \ud574\uace0\uc608\uc694.","\uaddc\uce59\uc740 \uc77c\ubd80\ub7ec \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc11c \uacfc\uc801\ud569\ud558\uae30 \uc5b4\ub824\uc6cc\uc694."],"episodes":[["2024\ub144 8\uc6d4","\uc2e4\uc2dc\uac04 \uc9c0\ud45c\uac00 2020\ub144 \uc774\ud6c4 \ucc98\uc74c 0.5\ub97c \ub118\uc5c8\uc5b4\uc694. \uadf8\ud574 \ub9d0\uae4c\uc9c0 NBER\ub294 \uce68\uccb4 \uc2dc\uc810\uc744 \uc815\ud558\uc9c0 \uc54a\uc558\uc5b4\uc694."],["2007\ub144 12\uc6d4\uacfc 2020\ub144 3\uc6d4","\uce68\uccb4 \uc2dc\uc791\uc77c\ub85c\ubd80\ud130 \uba87 \ub2ec \uc548\uc5d0 \uaddc\uce59\uc774 \ubc1c\ub3d9\ud588\uc5b4\uc694."]]}'],t.w)
