B.eDm=new A.b(B.h,["",'{"up":"\uace1\uc120\uc774 \uac00\ud314\ub77c\uc9c0\ub294 \uac70\uc608\uc694. \uc7a5\uae30 \uae08\ub9ac\uac00 \ub2e8\uae30 \uae08\ub9ac\ubcf4\ub2e4 \uc0c1\ub300\uc801\uc73c\ub85c \uc62c\ub77c\uc694.","down":"\uace1\uc120\uc774 \ud3c9\ud3c9\ud574\uc9c0\ub294 \uac70\uc608\uc694. 0 \uc544\ub798\uba74 \uc5ed\uc804\uc774\uc5d0\uc694.","chain":["\uc5f0\uc900\uc740 \ub2e8\uae30 \uae08\ub9ac\ub97c \uc815\ud558\uace0, \uc2dc\uc7a5\uc740 \uc131\uc7a5\uacfc \ubb3c\uac00\uc5d0 \ub300\ud55c \uc804\ub9dd\uc73c\ub85c \uc7a5\uae30 \uae08\ub9ac\ub97c \uc815\ud574\uc694.","\uc2dc\uc7a5\uc774 (\uc131\uc7a5\uc774 \uc57d\ud574\uc9c8 \uac83\uc774\ub77c\uc11c) \uc5f0\uc900\uc774 \ub098\uc911\uc5d0 \uc778\ud558\ud560 \uac83\uc73c\ub85c \ubcf4\uba74 \uc7a5\uae30 \uae08\ub9ac\ub294 \ub2e8\uae30 \uae08\ub9ac \uc544\ub798\uc5d0 \uba38\ubb3c\ub7ec\uc694.","\uc740\ud589\uc740 \uc9e7\uac8c \ube4c\ub824 \uae38\uac8c \ube4c\ub824\uc8fc\ubbc0\ub85c \uc5ed\uc804\uc740 \ub9c8\uc9c4\uc744 \uc904\uc774\uace0 \ub300\ucd9c\uc744 \uc904\uc774\uac8c \ud574\uc694."],"episodes":[["1970\ub144\ub300 \uc774\ud6c4 \ubbf8\uad6d \uacbd\uae30 \uce68\uccb4 \ub300\ubd80\ubd84 \uc774\uc804","\uace1\uc120\uc774 1\ub144 \uc774\uc0c1 \uc55e\uc11c \uc5ed\uc804\ub410\uc5b4\uc694."],["2022~2024\ub144","\uae34 \uc5ed\uc804\uc774 \uc774\uc5b4\uc84c\uc9c0\ub9cc \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \uce68\uccb4\uac00 \uc120\uc5b8\ub418\uc9c0 \uc54a\uc558\uc5b4\uc694. \uc120\ud589 \uc2dc\uac04\uc740 \ub2e4\uc591\ud558\uace0 \uc624\uacbd\ubcf4\ub3c4 \uc788\uc5b4\uc694."]]}'],t.w)
